function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide * 0.42;
  const phase = (loopT / duration) * Math.PI * 2;

  const COLORS = {
    bgTop: '#051215',
    bgMid: '#0A2024',
    bgBot: '#0F2D32',
    copper: '#E07A5F',
    copperDeep: '#C25E44',
    sandGold: '#F2CC8F',
    sandShade: '#DCAC66',
    creamSage: '#E6EFEA',
    sageMuted: '#A7C4B8',
    tealCard: '#143A40',
    tealShade: '#0E2D32',
    tealRecess: '#081E22',
    stageShadow: 'rgba(2, 10, 12, 0.48)',
    sheen: 'rgba(242, 204, 143, 0.22)',
    ambientMark: '#215259'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function seg(p, a, b) {
    return clamp01((p - a) / (b - a));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp01(u);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function octagonPath(x, y, r) {
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4 + Math.PI / 8;
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fill) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function drawSparkle4(x, y, r, fill, alpha) {
    if (r <= 0.5 || alpha <= 0.005) return;
    const inner = r * 0.26;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(x, y);
    ctx.beginPath();
    ctx.moveTo(0, -r);
    ctx.lineTo(inner, -inner);
    ctx.lineTo(r, 0);
    ctx.lineTo(inner, inner);
    ctx.lineTo(0, r);
    ctx.lineTo(-inner, inner);
    ctx.lineTo(-r, 0);
    ctx.lineTo(-inner, -inner);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.restore();
  }

  function drawClippedSheen(x, y, w, h, progress, alpha) {
    if (progress <= 0 || progress >= 1) return;
    const bandW = w * 0.22;
    const travel = w + h * 0.65 + bandW * 2;
    const startX = x - h * 0.35 - bandW + progress * travel;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.beginPath();
    ctx.moveTo(startX, y - h * 0.1);
    ctx.lineTo(startX + bandW, y - h * 0.1);
    ctx.lineTo(startX + bandW - h * 0.45, y + h * 1.1);
    ctx.lineTo(startX - h * 0.45, y + h * 1.1);
    ctx.closePath();
    ctx.fillStyle = COLORS.sheen;
    ctx.fill();
    ctx.restore();
  }

  function drawStageShadow(widthFactor, alpha) {
    if (alpha <= 0.001 || widthFactor <= 0.001) return;
    const sw = s * 0.54 * widthFactor;
    const sh = s * 0.044;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.ellipse(cx, cy + s * 0.68, sw, sh, 0, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.stageShadow;
    ctx.fill();
    ctx.restore();
  }

  // Clean Modern Deep Forest Teal Gradient Background (Zero Glow, Zero Edge Frames, Zero Corner Brackets)
  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, COLORS.bgTop);
    bgGrad.addColorStop(0.5, COLORS.bgMid);
    bgGrad.addColorStop(1, COLORS.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle crisp flat vector micro-accents strictly in outer margins far from hero icon
    const marks = [
      { nx: 0.10, ny: 0.25, type: 0, sz: 0.011, ph: 0.2, amp: 0.013, op: 0.22 },
      { nx: 0.16, ny: 0.72, type: 1, sz: 0.010, ph: 1.8, amp: 0.012, op: 0.18 },
      { nx: 0.08, ny: 0.54, type: 2, sz: 0.008, ph: 3.3, amp: 0.010, op: 0.16 },
      { nx: 0.20, ny: 0.35, type: 0, sz: 0.008, ph: 4.7, amp: 0.011, op: 0.15 },
      { nx: 0.90, ny: 0.26, type: 1, sz: 0.011, ph: 0.9, amp: 0.013, op: 0.20 },
      { nx: 0.84, ny: 0.74, type: 0, sz: 0.011, ph: 2.6, amp: 0.012, op: 0.22 },
      { nx: 0.92, ny: 0.56, type: 2, sz: 0.008, ph: 4.1, amp: 0.010, op: 0.16 },
      { nx: 0.80, ny: 0.36, type: 1, sz: 0.008, ph: 5.4, amp: 0.011, op: 0.15 }
    ];

    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      const mx = width * m.nx + Math.cos(phase + m.ph) * minSide * (m.amp * 0.45);
      const my = height * m.ny + Math.sin(phase + m.ph) * minSide * m.amp;
      const r = minSide * m.sz;
      const pulse = 0.78 + 0.22 * Math.sin(phase * 2 + m.ph);

      ctx.save();
      ctx.globalAlpha = m.op * pulse;
      ctx.fillStyle = COLORS.ambientMark;
      if (m.type === 0) {
        octagonPath(mx, my, r);
        ctx.fill();
      } else if (m.type === 1) {
        drawDiamond(mx, my, r, r, COLORS.ambientMark);
      } else {
        roundRectPath(mx - r * 1.45, my - r * 0.35, r * 2.9, r * 0.70, r * 0.35);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  // Shared Mid-Century Modern 2D Flat Golden Hourglass (Exact Match between Scene 1 Start and Scene 4 End!)
  function drawHourglass(scale, rot, sandProgress, streamAlpha, alpha) {
    if (alpha <= 0.005 || scale <= 0.01) return;
    const sc = s * scale;
    const capW = sc * 0.76;
    const capH = sc * 0.092;
    const topCapY = -sc * 0.44;
    const botCapY = sc * 0.44;
    const bulbW = sc * 0.58;
    const waistW = sc * 0.075;
    const chTop = topCapY + capH * 0.48;
    const chBot = botCapY - capH * 0.48;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(cx, cy);
    ctx.rotate(rot);

    // Subtle Side Vertical Brass Pillars connecting top & bottom caps (clean framing, wide gap from bulbs)
    const pilX = capW * 0.42;
    const pilW = sc * 0.036;
    for (let side = -1; side <= 1; side += 2) {
      roundRectPath(side * pilX - pilW * 0.5, topCapY, pilW, botCapY - topCapY, pilW * 0.5);
      ctx.fillStyle = COLORS.copperDeep;
      ctx.fill();
    }

    // Upper Glass Chamber Path
    function upperBulbPath() {
      ctx.beginPath();
      ctx.moveTo(-bulbW * 0.5, chTop);
      ctx.lineTo(bulbW * 0.5, chTop);
      ctx.bezierCurveTo(bulbW * 0.5, chTop + sc * 0.19, waistW * 0.85, -sc * 0.04, waistW * 0.5, 0);
      ctx.lineTo(-waistW * 0.5, 0);
      ctx.bezierCurveTo(-waistW * 0.85, -sc * 0.04, -bulbW * 0.5, chTop + sc * 0.19, -bulbW * 0.5, chTop);
      ctx.closePath();
    }

    // Lower Glass Chamber Path
    function lowerBulbPath() {
      ctx.beginPath();
      ctx.moveTo(-waistW * 0.5, 0);
      ctx.lineTo(waistW * 0.5, 0);
      ctx.bezierCurveTo(waistW * 0.85, sc * 0.04, bulbW * 0.5, chBot - sc * 0.19, bulbW * 0.5, chBot);
      ctx.lineTo(-bulbW * 0.5, chBot);
      ctx.bezierCurveTo(-bulbW * 0.5, chBot - sc * 0.19, -waistW * 0.85, sc * 0.04, -waistW * 0.5, 0);
      ctx.closePath();
    }

    // Fill Glass Chambers Background
    upperBulbPath();
    ctx.fillStyle = COLORS.tealRecess;
    ctx.fill();

    lowerBulbPath();
    ctx.fillStyle = COLORS.tealRecess;
    ctx.fill();

    // Upper Chamber Sand (drains smoothly from 80% down to 14%, level flat surface)
    const topFill = lerp(0.80, 0.14, sandProgress);
    const topSandY = lerp(0, chTop, topFill);
    ctx.save();
    upperBulbPath();
    ctx.clip();
    ctx.fillStyle = COLORS.sandGold;
    ctx.fillRect(-bulbW * 0.6, topSandY, bulbW * 1.2, -topSandY + 2);
    ctx.fillStyle = COLORS.sandShade;
    ctx.fillRect(0, topSandY, bulbW * 0.6, -topSandY + 2);
    ctx.restore();

    // Lower Chamber Sand (grows smoothly from 14% up to 80%, exact level flat surface left & right!)
    const botFill = lerp(0.14, 0.80, sandProgress);
    const botSandTop = lerp(chBot, sc * 0.06, botFill);
    ctx.save();
    lowerBulbPath();
    ctx.clip();

    // Falling Center Sand Stream strictly between waist and level lower sand surface
    if (streamAlpha > 0.01) {
      ctx.save();
      ctx.globalAlpha *= streamAlpha;
      const stW = Math.max(2, sc * 0.024);
      ctx.fillStyle = COLORS.sandGold;
      ctx.fillRect(-stW * 0.5, -2, stW, botSandTop + 4);
      ctx.restore();
    }

    // Exact Level Horizontal Sand Surface (left & right halves perfectly aligned at botSandTop!)
    ctx.fillStyle = COLORS.sandGold;
    ctx.fillRect(-bulbW * 0.6, botSandTop, bulbW * 1.2, chBot - botSandTop + 4);
    ctx.fillStyle = COLORS.sandShade;
    ctx.fillRect(0, botSandTop, bulbW * 0.6, chBot - botSandTop + 4);
    ctx.restore();

    // Crisp Glass Rim Outline on both bulbs
    upperBulbPath();
    ctx.strokeStyle = COLORS.creamSage;
    ctx.lineWidth = Math.max(2, sc * 0.028);
    ctx.stroke();

    lowerBulbPath();
    ctx.strokeStyle = COLORS.creamSage;
    ctx.lineWidth = Math.max(2, sc * 0.028);
    ctx.stroke();

    // Top & Bottom Copper Bronze Frame Caps with Sand Gold inner trim
    const capsY = [topCapY, botCapY];
    for (let i = 0; i < 2; i++) {
      const cyCap = capsY[i];
      roundRectPath(-capW * 0.5, cyCap - capH * 0.5, capW, capH, capH * 0.45);
      ctx.fillStyle = COLORS.copper;
      ctx.fill();

      ctx.save();
      roundRectPath(-capW * 0.5, cyCap - capH * 0.5, capW, capH, capH * 0.45);
      ctx.clip();
      ctx.fillStyle = COLORS.copperDeep;
      ctx.fillRect(0, cyCap - capH * 0.55, capW * 0.55, capH * 1.1);
      ctx.fillStyle = COLORS.sandGold;
      ctx.fillRect(-capW * 0.5, i === 0 ? cyCap + capH * 0.22 : cyCap - capH * 0.5, capW, capH * 0.28);
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 1 (0s - 5s): TIME VALUE HOURGLASS
  // =========================================================================
  function drawScene1(p) {
    // 0.00 - 0.54: Smooth continuous sand flow from upper chamber to lower chamber
    // 0.56 - 0.78: Precision 180-degree clockwise hourglass rotation (weighted easeInOutQuart)
    // 0.78 - 1.00: Hourglass retracts smoothly while Scene 2's Octagonal Compass Housing unfolds cleanly!

    const sandP = easeInOutCubic(seg(p, 0.04, 0.54));
    const streamA = easeOutCubic(seg(p, 0.02, 0.10)) * (1 - easeInCubic(seg(p, 0.50, 0.56)));
    const flipRot = easeInOutQuart(seg(p, 0.56, 0.78)) * Math.PI;
    const hgOut = easeInCubic(seg(p, 0.79, 0.90));
    const toCompU = easeOutCubic(seg(p, 0.85, 1.00));

    drawStageShadow(lerp(0.86, 0.94, toCompU), 1);

    if (hgOut < 0.995) {
      drawHourglass(lerp(1, 0.58, hgOut), flipRot, sandP, streamA, 1 - hgOut);
    }

    // Seamless Handoff: Scene 2 Solid Octagonal Compass Case unfolding cleanly at (cx, cy) (p = 0.85 -> 1.00)!
    if (toCompU > 0.005) {
      drawCompassBezelBase(s * 0.46 * toCompU, toCompU);
    }
  }

  // Shared Solid Octagonal Luxury Compass Bezel (Scene 1 -> Scene 2 Exact Handoff; NOT Thin HUD!)
  function drawCompassBezelBase(rOut, alpha) {
    if (alpha <= 0.005 || rOut <= 2) return;
    ctx.save();
    ctx.globalAlpha = alpha;

    // Outer Copper Bronze Octagon
    octagonPath(cx, cy, rOut);
    ctx.fillStyle = COLORS.copper;
    ctx.fill();

    // Right-half flat duotone bevel clipped strictly inside octagon
    ctx.save();
    octagonPath(cx, cy, rOut);
    ctx.clip();
    ctx.fillStyle = COLORS.copperDeep;
    ctx.fillRect(cx, cy - rOut * 1.1, rOut * 1.1, rOut * 2.2);
    ctx.restore();

    // Recessed Dark Forest Teal Octagonal Dial Face
    octagonPath(cx, cy, rOut * 0.78);
    ctx.fillStyle = COLORS.tealRecess;
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5s - 10s): STRATEGY COMPASS LOCK (OCTAGONAL DIAL & 45-DEGREE LOCK)
  // =========================================================================
  function drawScene2(p) {
    // 0.00 - 0.16: 4 cardinal ticks & two-tone diamond needle reveal smoothly inside octagonal dial
    // 0.16 - 0.64: Magnetic damped oscillation settling cleanly onto exact +45 deg (North-East growth vector!)
    // 0.58 - 0.78: NE Target Diamond illuminates cleanly outside top-right octagon corner + diagonal sheen
    // 0.78 - 1.00: Compass retracts cleanly; Scene 3's horizontal Milestone Base Plinth extends cleanly!

    const introU = easeOutCubic(seg(p, 0.02, 0.18));
    const compOut = easeInCubic(seg(p, 0.79, 0.90));
    const toPlinthU = easeOutCubic(seg(p, 0.85, 1.00));
    const vis = 1 - compOut;

    drawStageShadow(lerp(0.94, 1.32, toPlinthU), 1);

    if (vis > 0.005) {
      const sc = lerp(1, 0.62, compOut);
      const rOut = s * 0.46 * sc;

      ctx.save();
      ctx.globalAlpha = vis;

      // 1. Solid Octagonal Compass Housing (Matches Scene 1 p = 1.00 EXACTLY!)
      drawCompassBezelBase(rOut, 1);

      // Clipped diagonal sheen across octagonal housing
      const sheenP = seg(p, 0.56, 0.74);
      if (sheenP > 0 && sheenP < 1) {
        ctx.save();
        octagonPath(cx, cy, rOut);
        ctx.clip();
        drawClippedSheen(cx - rOut, cy - rOut, rOut * 2, rOut * 2, sheenP, 0.9);
        ctx.restore();
      }

      if (introU > 0.005) {
        // 2. 4 Clean Cardinal Tick Pills strictly inset inside dial rim (r = 0.285*s..0.335*s)
        ctx.save();
        ctx.globalAlpha *= introU;
        const tickDist = s * 0.295 * sc;
        const tickLen = s * 0.056 * sc;
        const tickThick = s * 0.024 * sc;
        for (let k = 0; k < 4; k++) {
          ctx.save();
          ctx.translate(cx, cy);
          ctx.rotate((k * Math.PI) / 2);
          roundRectPath(-tickThick * 0.5, -tickDist - tickLen * 0.5, tickThick, tickLen, tickThick * 0.5);
          ctx.fillStyle = k === 0 ? COLORS.sandGold : COLORS.sageMuted;
          ctx.fill();
          ctx.restore();
        }

        // 3. Magnetic Damped Compass Needle settling cleanly to +45 deg clockwise from North (= NE upward-right!)
        const targetAng = Math.PI * 0.25;
        const oscT = seg(p, 0.14, 0.66);
        const damp = Math.pow(1 - oscT, 2.4);
        const startOff = -Math.PI * 0.42;
        const curAng = targetAng + startOff * Math.cos(oscT * Math.PI * 2.5) * damp;

        const nLen = s * 0.235 * introU * sc;
        const nHalfW = s * 0.068 * introU * sc;

        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate(curAng);

        // North/Growth Half (Copper Bronze)
        ctx.beginPath();
        ctx.moveTo(0, -nLen);
        ctx.lineTo(nHalfW, 0);
        ctx.lineTo(-nHalfW, 0);
        ctx.closePath();
        ctx.fillStyle = COLORS.copper;
        ctx.fill();

        // South/Base Half (Sand Gold)
        ctx.beginPath();
        ctx.moveTo(0, nLen);
        ctx.lineTo(nHalfW, 0);
        ctx.lineTo(-nHalfW, 0);
        ctx.closePath();
        ctx.fillStyle = COLORS.sandGold;
        ctx.fill();

        // Center Pivot Cap
        ctx.beginPath();
        ctx.arc(0, 0, s * 0.044 * introU * sc, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.creamSage;
        ctx.fill();

        ctx.beginPath();
        ctx.arc(0, 0, s * 0.020 * introU * sc, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.tealRecess;
        ctx.fill();

        ctx.restore();
        ctx.restore();
      }

      // 4. North-East Growth Target Diamond strictly OUTSIDE top-right octagon corner (wide clearance!)
      const lockIn = easeOutCubic(seg(p, 0.52, 0.64));
      const lockOut = easeInCubic(seg(p, 0.74, 0.82));
      const lockVis = lockIn * (1 - lockOut);
      if (lockVis > 0.005) {
        const pulse = 1 + 0.08 * Math.sin(seg(p, 0.54, 0.78) * Math.PI * 4);
        const tx = cx + s * 0.44;
        const ty = cy - s * 0.44;
        ctx.save();
        ctx.globalAlpha *= lockVis;
        drawDiamond(tx, ty, s * 0.062 * lockVis * pulse, s * 0.062 * lockVis * pulse, COLORS.sandGold);
        drawDiamond(tx, ty, s * 0.026 * lockVis, s * 0.026 * lockVis, COLORS.tealRecess);
        ctx.restore();
      }

      ctx.restore();
    }

    // Seamless Handoff: Scene 3 Horizontal Milestone Plinth extending cleanly at y = cy + 0.48*s (p = 0.85 -> 1.00)!
    if (toPlinthU > 0.005) {
      drawMilestonePlinth(cx, cy + s * 0.48, s * 1.32 * toPlinthU, s * 0.052, toPlinthU);
    }
  }

  function drawMilestonePlinth(x, y, w, h, alpha) {
    if (alpha <= 0.005 || w <= 2) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    roundRectPath(x - w * 0.5, y - h * 0.5, w, h, h * 0.5);
    ctx.fillStyle = COLORS.tealCard;
    ctx.fill();

    ctx.save();
    roundRectPath(x - w * 0.5, y - h * 0.5, w, h, h * 0.5);
    ctx.clip();
    ctx.fillStyle = COLORS.copper;
    ctx.fillRect(x - w * 0.5, y - h * 0.5, w, h * 0.36);
    ctx.restore();
    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10s - 15s): ASCENDING MILESTONES (4 STEPPING PILLARS & PARABOLIC HOPS)
  // =========================================================================
  function drawScene3(p) {
    const plinthY = cy + s * 0.48;
    const plinthH = s * 0.052;
    const baseY = plinthY - plinthH * 0.5 - s * 0.032;

    const exitSceneU = easeInCubic(seg(p, 0.79, 0.90));
    const toBaseU = easeOutCubic(seg(p, 0.85, 1.00));
    const vis = 1 - exitSceneU;

    drawStageShadow(lerp(1.32, 0.86, toBaseU), 1);

    if (vis > 0.005) {
      drawMilestonePlinth(cx, plinthY, s * 1.32 * lerp(0.5, 1, vis), plinthH, vis);
    }

    const xs = [-0.45, -0.15, 0.15, 0.45];
    const hs = [0.20, 0.34, 0.50, 0.68];
    const pW = s * 0.21;
    const pFills = [COLORS.tealCard, COLORS.sageMuted, COLORS.sandGold, COLORS.copper];

    const hop1 = easeInOutCubic(seg(p, 0.26, 0.41));
    const hop2 = easeInOutCubic(seg(p, 0.41, 0.56));
    const hop3 = easeInOutCubic(seg(p, 0.56, 0.71));

    const beaconPts = [];
    for (let i = 0; i < 4; i++) {
      const growU = easeOutCubic(seg(p, 0.02 + i * 0.055, 0.20 + i * 0.055));
      const curH = hs[i] * s * growU * vis;
      const px = cx + xs[i] * s;
      const topY = baseY - hs[i] * s;
      beaconPts.push({ x: px, y: topY - s * 0.125 });

      if (curH > 2) {
        const curTop = baseY - curH;
        const rad = Math.min(s * 0.036, curH * 0.4);

        ctx.save();
        ctx.globalAlpha = vis;
        roundRectPath(px - pW * 0.5, curTop, pW, curH, rad);
        ctx.fillStyle = pFills[i];
        ctx.fill();

        ctx.save();
        roundRectPath(px - pW * 0.5, curTop, pW, curH, rad);
        ctx.clip();
        ctx.fillStyle = 'rgba(5, 18, 21, 0.16)';
        ctx.fillRect(px + pW * 0.12, curTop, pW * 0.42, curH);

        const capLit = (i === 0 && p >= 0.22) || (i === 1 && hop1 > 0.85) || (i === 2 && hop2 > 0.85) || (i === 3 && hop3 > 0.85);
        ctx.fillStyle = capLit ? COLORS.creamSage : COLORS.sandGold;
        ctx.fillRect(px - pW * 0.5, curTop, pW, Math.min(s * 0.044, curH * 0.3));
        ctx.restore();
        ctx.restore();
      }
    }

    const arcVis = easeOutCubic(seg(p, 0.22, 0.30)) * (1 - easeInCubic(seg(p, 0.76, 0.84)));
    if (arcVis > 0.005) {
      function evalArc(i0, i1, u) {
        const a = beaconPts[i0];
        const b = beaconPts[i1];
        const mx = (a.x + b.x) * 0.5;
        const peakY = Math.min(a.y, b.y) - s * 0.145;
        const inv = 1 - u;
        return {
          x: inv * inv * a.x + 2 * inv * u * mx + u * u * b.x,
          y: inv * inv * a.y + 2 * inv * u * peakY + u * u * b.y
        };
      }

      const hops = [hop1, hop2, hop3];
      ctx.save();
      ctx.globalAlpha = arcVis;

      for (let h = 0; h < 3; h++) {
        const hu = hops[h];
        if (hu <= 0.01) continue;
        ctx.beginPath();
        const stCount = 20;
        for (let k = 0; k <= stCount; k++) {
          const pt = evalArc(h, h + 1, (k / stCount) * hu);
          if (k === 0) ctx.moveTo(pt.x, pt.y);
          else ctx.lineTo(pt.x, pt.y);
        }
        ctx.strokeStyle = COLORS.sandGold;
        ctx.lineWidth = s * 0.026;
        ctx.lineCap = 'round';
        ctx.stroke();
      }

      let bPos = beaconPts[0];
      if (hop3 > 0) bPos = evalArc(2, 3, hop3);
      else if (hop2 > 0) bPos = evalArc(1, 2, hop2);
      else if (hop1 > 0) bPos = evalArc(0, 1, hop1);

      ctx.beginPath();
      ctx.arc(bPos.x, bPos.y, s * 0.044, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.creamSage;
      ctx.fill();
      ctx.beginPath();
      ctx.arc(bPos.x, bPos.y, s * 0.022, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.copper;
      ctx.fill();

      ctx.restore();
    }

    if (toBaseU > 0.005) {
      drawTrophyPedestalBase(toBaseU, toBaseU);
    }
  }

  function drawTrophyPedestalBase(scale, alpha) {
    if (alpha <= 0.005 || scale <= 0.01) return;
    ctx.save();
    ctx.globalAlpha = alpha;

    const lW = s * 0.56 * scale;
    const lH = s * 0.092;
    const lY = cy + s * 0.425;
    roundRectPath(cx - lW * 0.5, lY - lH * 0.5, lW, lH, s * 0.028);
    ctx.fillStyle = COLORS.copper;
    ctx.fill();

    ctx.save();
    roundRectPath(cx - lW * 0.5, lY - lH * 0.5, lW, lH, s * 0.028);
    ctx.clip();
    ctx.fillStyle = COLORS.copperDeep;
    ctx.fillRect(cx, lY - lH * 0.55, lW * 0.55, lH * 1.1);
    ctx.restore();

    const uW = s * 0.36 * scale;
    const uH = s * 0.068;
    const uY = lY - lH * 0.5 - uH * 0.5 - s * 0.018;
    roundRectPath(cx - uW * 0.5, uY - uH * 0.5, uW, uH, s * 0.024);
    ctx.fillStyle = COLORS.sandGold;
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15s - 20s): HORIZON TROPHY CREST -> SEAMLESS LOOP TO HOURGLASS
  // =========================================================================
  function drawScene4(p) {
    const buildU = easeOutCubic(seg(p, 0.02, 0.24));
    const exitTrophyU = easeInCubic(seg(p, 0.79, 0.90));
    const toHgU = easeOutCubic(seg(p, 0.85, 1.00));
    const vis = 1 - exitTrophyU;

    drawStageShadow(0.86, 1);

    if (vis > 0.005) {
      const sc = lerp(1, 0.62, exitTrophyU);
      ctx.save();
      ctx.globalAlpha = vis;
      ctx.translate(cx, cy + s * 0.08);
      ctx.scale(sc, sc);
      ctx.translate(-cx, -(cy + s * 0.08));

      drawTrophyPedestalBase(1, 1);

      if (buildU > 0.01) {
        const stemBot = cy + s * 0.28;
        const stemTop = lerp(stemBot, cy + s * 0.14, buildU);
        const cupTop = lerp(stemBot, cy - s * 0.34, buildU);
        const cupBot = stemTop + s * 0.03;
        const cupHalfW = s * 0.31 * buildU;

        const hIn = easeOutCubic(seg(p, 0.10, 0.26));
        if (hIn > 0.01) {
          const hThick = s * 0.054;
          const hTop = cupTop + s * 0.075;
          const hBot = cupTop + s * 0.30;
          const hOut = cupHalfW + s * 0.145 * hIn;

          ctx.save();
          ctx.globalAlpha *= hIn;
          for (let side = -1; side <= 1; side += 2) {
            ctx.beginPath();
            ctx.moveTo(cx + side * (cupHalfW - s * 0.03), hTop);
            ctx.bezierCurveTo(
              cx + side * (hOut + s * 0.03), hTop,
              cx + side * (hOut + s * 0.03), hBot,
              cx + side * (cupHalfW * 0.68), hBot
            );
            ctx.strokeStyle = side < 0 ? COLORS.copper : COLORS.copperDeep;
            ctx.lineWidth = hThick;
            ctx.lineCap = 'round';
            ctx.stroke();
          }
          ctx.restore();
        }

        const stemW = s * 0.115;
        roundRectPath(cx - stemW * 0.5, stemTop, stemW, stemBot - stemTop + s * 0.02, s * 0.02);
        ctx.fillStyle = COLORS.sandShade;
        ctx.fill();

        function cupPath() {
          ctx.beginPath();
          ctx.moveTo(cx - cupHalfW, cupTop);
          ctx.lineTo(cx + cupHalfW, cupTop);
          ctx.bezierCurveTo(cx + cupHalfW, cupBot - s * 0.04, cx + cupHalfW * 0.54, cupBot, cx, cupBot);
          ctx.bezierCurveTo(cx - cupHalfW * 0.54, cupBot, cx - cupHalfW, cupBot - s * 0.04, cx - cupHalfW, cupTop);
          ctx.closePath();
        }

        cupPath();
        ctx.fillStyle = COLORS.sandGold;
        ctx.fill();

        ctx.save();
        cupPath();
        ctx.clip();

        ctx.fillStyle = COLORS.sandShade;
        ctx.fillRect(cx, cupTop - 2, cupHalfW + 4, cupBot - cupTop + 6);

        ctx.fillStyle = COLORS.creamSage;
        ctx.fillRect(cx - cupHalfW - 2, cupTop, cupHalfW * 2 + 4, s * 0.054 * buildU);

        const sheenP = seg(p, 0.46, 0.68);
        if (sheenP > 0 && sheenP < 1) {
          drawClippedSheen(cx - cupHalfW, cupTop, cupHalfW * 2, cupBot - cupTop, sheenP, 0.92);
        }
        ctx.restore();

        const crestIn = easeOutCubic(seg(p, 0.18, 0.34));
        if (crestIn > 0.01) {
          const crestY = lerp(cupTop, cupBot, 0.48);
          const cr = s * 0.105 * crestIn;
          drawDiamond(cx, crestY, cr, cr, COLORS.copper);
          drawDiamond(cx, crestY, cr * 0.46, cr * 0.46, COLORS.creamSage);
        }
      }

      const spIn = easeOutCubic(seg(p, 0.28, 0.42));
      const spOut = easeInCubic(seg(p, 0.72, 0.80));
      const spVis = spIn * (1 - spOut);
      if (spVis > 0.005) {
        const w1 = 0.78 + 0.22 * Math.sin(seg(p, 0.30, 0.76) * Math.PI * 4);
        const w2 = 0.78 + 0.22 * Math.cos(seg(p, 0.30, 0.76) * Math.PI * 4);
        drawSparkle4(cx, cy - s * 0.50, s * 0.062 * spVis * w1, COLORS.creamSage, spVis);
        drawSparkle4(cx - s * 0.44, cy - s * 0.40, s * 0.044 * spVis * w2, COLORS.sandGold, spVis);
        drawSparkle4(cx + s * 0.44, cy - s * 0.40, s * 0.044 * spVis * w2, COLORS.sandGold, spVis);
      }

      ctx.restore();
    }

    if (toHgU > 0.005) {
      drawHourglass(lerp(0.55, 1.0, toHgU), 0, 0, 0, toHgU);
    }
  }

  // Render Frame
  ctx.save();
  drawBackground();

  if (currentScene === 0) {
    drawScene1(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3(sceneProgress);
  } else {
    drawScene4(sceneProgress);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide * 0.42;
  const phase = (loopT / duration) * Math.PI * 2;

  const COLORS = {
    bgTop: '#060D1A',
    bgMid: '#0D192E',
    bgBot: '#152540',
    ruby: '#F43F5E',
    rubyDeep: '#BE123C',
    rubyBright: '#FB7185',
    platinum: '#E2E8F0',
    platinumShade: '#CBD5E1',
    softSky: '#7DD3FC',
    skyBright: '#38BDF8',
    sapphireMid: '#23447A',
    sapphireDark: '#17305A',
    sapphireRecess: '#0E1F3D',
    stageShadow: 'rgba(3, 7, 16, 0.48)',
    sheen: 'rgba(241, 245, 249, 0.20)',
    ambientMark: '#2B426B'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function seg(p, a, b) {
    return clamp01((p - a) / (b - a));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp01(u);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fill) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function drawClippedSheen(x, y, w, h, progress, alpha) {
    if (progress <= 0 || progress >= 1) return;
    const bandW = w * 0.22;
    const travel = w + h * 0.65 + bandW * 2;
    const startX = x - h * 0.35 - bandW + progress * travel;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.beginPath();
    ctx.moveTo(startX, y - h * 0.1);
    ctx.lineTo(startX + bandW, y - h * 0.1);
    ctx.lineTo(startX + bandW - h * 0.45, y + h * 1.1);
    ctx.lineTo(startX - h * 0.45, y + h * 1.1);
    ctx.closePath();
    ctx.fillStyle = COLORS.sheen;
    ctx.fill();
    ctx.restore();
  }

  function drawStageShadow(widthFactor, alpha) {
    if (alpha <= 0.001 || widthFactor <= 0.001) return;
    const sw = s * 0.54 * widthFactor;
    const sh = s * 0.044;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.ellipse(cx, cy + s * 0.68, sw, sh, 0, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.stageShadow;
    ctx.fill();
    ctx.restore();
  }

  // Clean Modern Dark Sapphire Slate Gradient Background (Zero Glow, Zero Edge Frames, Zero Corner Brackets)
  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, COLORS.bgTop);
    bgGrad.addColorStop(0.5, COLORS.bgMid);
    bgGrad.addColorStop(1, COLORS.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle crisp flat vector micro-accents strictly in outer margins far from hero icon
    const marks = [
      { nx: 0.10, ny: 0.25, type: 0, sz: 0.011, ph: 0.3, amp: 0.013, op: 0.22 },
      { nx: 0.16, ny: 0.72, type: 1, sz: 0.010, ph: 1.9, amp: 0.012, op: 0.18 },
      { nx: 0.08, ny: 0.54, type: 2, sz: 0.008, ph: 3.4, amp: 0.010, op: 0.16 },
      { nx: 0.20, ny: 0.35, type: 0, sz: 0.008, ph: 4.8, amp: 0.011, op: 0.15 },
      { nx: 0.90, ny: 0.26, type: 1, sz: 0.011, ph: 1.0, amp: 0.013, op: 0.20 },
      { nx: 0.84, ny: 0.74, type: 0, sz: 0.011, ph: 2.7, amp: 0.012, op: 0.22 },
      { nx: 0.92, ny: 0.55, type: 2, sz: 0.008, ph: 4.2, amp: 0.010, op: 0.16 },
      { nx: 0.80, ny: 0.36, type: 1, sz: 0.008, ph: 5.5, amp: 0.011, op: 0.15 }
    ];

    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      const mx = width * m.nx + Math.cos(phase + m.ph) * minSide * (m.amp * 0.45);
      const my = height * m.ny + Math.sin(phase + m.ph) * minSide * m.amp;
      const r = minSide * m.sz;
      const pulse = 0.78 + 0.22 * Math.sin(phase * 2 + m.ph);

      ctx.save();
      ctx.globalAlpha = m.op * pulse;
      ctx.fillStyle = COLORS.ambientMark;
      if (m.type === 0) {
        drawDiamond(mx, my, r, r, COLORS.ambientMark);
      } else if (m.type === 1) {
        roundRectPath(mx - r * 1.45, my - r * 0.36, r * 2.9, r * 0.72, r * 0.36);
        ctx.fill();
      } else {
        ctx.beginPath();
        ctx.arc(mx, my, r * 0.76, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  // Shared 2D Flat Solid Cartographic Globe (Exact Match between Scene 1 Start and Scene 4 End!)
  function drawCartographicGlobe(radius, meridianScroll, flowProgress, sheenP, alpha) {
    if (alpha <= 0.005 || radius <= 2) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(cx, cy);

    // Solid Filled Sapphire Globe Disc (NOT a thin HUD circle!)
    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.sapphireMid;
    ctx.fill();

    // Clipped Cartographic Interior (Duotone Right Half, Latitudes, Scrolling Meridians, Ruby Capital Arcs)
    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, Math.PI * 2);
    ctx.clip();

    // Crisp right-half flat shade
    ctx.fillStyle = COLORS.sapphireDark;
    ctx.fillRect(0, -radius * 1.1, radius * 1.1, radius * 2.2);

    // 3 Clean Horizontal Latitude Lines
    ctx.strokeStyle = 'rgba(125, 211, 252, 0.36)';
    ctx.lineWidth = Math.max(1.5, radius * 0.036);
    const latYs = [-0.46, 0, 0.46];
    for (let l = 0; l < latYs.length; l++) {
      ctx.beginPath();
      ctx.moveTo(-radius * 1.05, radius * latYs[l]);
      ctx.lineTo(radius * 1.05, radius * latYs[l]);
      ctx.stroke();
    }

    // Smoothly Scrolling 2D Elliptical Meridians (4 evenly phased meridians scrolling left-to-right!)
    for (let m = 0; m < 4; m++) {
      const u = ((meridianScroll + m * 0.25) % 1); // 0..1 across hemisphere
      const rx = Math.abs(Math.cos(u * Math.PI)) * radius * 0.96;
      const sideSign = u < 0.5 ? -1 : 1;
      ctx.beginPath();
      if (rx < 1.5) {
        ctx.moveTo(0, -radius);
        ctx.lineTo(0, radius);
      } else {
        ctx.ellipse(0, 0, rx, radius, 0, sideSign < 0 ? Math.PI * 0.5 : -Math.PI * 0.5, sideSign < 0 ? Math.PI * 1.5 : Math.PI * 0.5, false);
      }
      ctx.stroke();
    }

    // 3 Global Capital Hub Nodes & 2 Curved Ruby Capital Flow Arcs cleanly inside globe
    const h1 = { x: -radius * 0.46, y: -radius * 0.22 };
    const h2 = { x: radius * 0.04, y: radius * 0.14 };
    const h3 = { x: radius * 0.48, y: -radius * 0.28 };

    function evalQuad(a, b, cX, cY, u) {
      const inv = 1 - u;
      return {
        x: inv * inv * a.x + 2 * inv * u * cX + u * u * b.x,
        y: inv * inv * a.y + 2 * inv * u * cY + u * u * b.y
      };
    }

    // Subtle Ruby Capital Flow Arcs
    ctx.strokeStyle = COLORS.ruby;
    ctx.lineWidth = Math.max(2, radius * 0.052);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(h1.x, h1.y);
    ctx.quadraticCurveTo(-radius * 0.18, -radius * 0.42, h2.x, h2.y);
    ctx.quadraticCurveTo(radius * 0.30, -radius * 0.38, h3.x, h3.y);
    ctx.stroke();

    // Animated Platinum Capital Flow Pulse Dot gliding smoothly along the 2 global arcs
    if (flowProgress > 0.01 && flowProgress < 0.99) {
      const pt = flowProgress < 0.5
        ? evalQuad(h1, h2, -radius * 0.18, -radius * 0.42, flowProgress * 2)
        : evalQuad(h2, h3, radius * 0.30, -radius * 0.38, (flowProgress - 0.5) * 2);
      ctx.beginPath();
      ctx.arc(pt.x, pt.y, radius * 0.072, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.platinum;
      ctx.fill();
    }

    // Hub Nodes
    const hubs = [h1, h2, h3];
    for (let i = 0; i < hubs.length; i++) {
      ctx.beginPath();
      ctx.arc(hubs[i].x, hubs[i].y, radius * 0.095, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.ruby;
      ctx.fill();
      ctx.beginPath();
      ctx.arc(hubs[i].x, hubs[i].y, radius * 0.044, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.platinum;
      ctx.fill();
    }

    // Clipped Diagonal Light Sheen
    if (sheenP > 0 && sheenP < 1) {
      drawClippedSheen(-radius, -radius, radius * 2, radius * 2, sheenP, 0.9);
    }

    ctx.restore();

    // Clean Solid Platinum Outer Rim Border
    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, Math.PI * 2);
    ctx.strokeStyle = COLORS.platinum;
    ctx.lineWidth = Math.max(2.5, radius * 0.068);
    ctx.stroke();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 1 (0s - 5s): GLOBAL MERIDIAN HUB
  // =========================================================================
  function drawScene1(p) {
    // 0.00 - 0.78: Smooth 2D cartographic meridian scroll + 2 waves of Ruby global capital flow + sheen
    // 0.78 - 1.00: Globe retracts smoothly while Scene 2's Sovereign Bond Document unfolds cleanly at center!

    const globeOut = easeInCubic(seg(p, 0.79, 0.90));
    const toScrollU = easeOutCubic(seg(p, 0.85, 1.00));
    const vis = 1 - globeOut;

    drawStageShadow(lerp(0.96, 1.02, toScrollU), 1);

    if (vis > 0.005) {
      const merScroll = seg(p, 0.0, 0.86) * 0.65;
      const flowCycle = (seg(p, 0.08, 0.76) * 2) % 1;
      const flowP = p > 0.08 && p < 0.76 ? flowCycle : 0;
      const sheenP = seg(p, 0.42, 0.66);

      drawCartographicGlobe(s * 0.48 * lerp(1, 0.58, globeOut), merScroll, flowP, sheenP, vis);
    }

    // Seamless Handoff: Scene 2 Sovereign Bond Sheet unfolding cleanly at center (p = 0.85 -> 1.00)!
    if (toScrollU > 0.005) {
      const bw = lerp(s * 0.34, s * 0.84, toScrollU);
      const bh = lerp(s * 0.40, s * 0.86, toScrollU);
      ctx.save();
      ctx.globalAlpha = toScrollU;
      drawBondSheetBase(bw, bh);
      ctx.restore();
    }
  }

  function drawBondSheetBase(w, h) {
    const left = cx - w * 0.5;
    const top = cy - h * 0.5;
    roundRectPath(left, top, w, h, s * 0.045);
    ctx.fillStyle = COLORS.platinum;
    ctx.fill();

    ctx.save();
    roundRectPath(left, top, w, h, s * 0.045);
    ctx.clip();
    ctx.fillStyle = COLORS.platinumShade;
    ctx.fillRect(cx, top, w * 0.55, h);
    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5s - 10s): SOVEREIGN BOND SCROLL & CRIMSON RUBY SEAL
  // =========================================================================
  function drawScene2(p) {
    const sheetW = s * 0.84;
    const sheetH = s * 0.86;

    // 0.00 - 0.18: Top & bottom Sapphire scroll rolls expand smoothly; 3 bond clause lines draw left-to-right
    // 0.24 - 0.44: Crimson Ruby Wax Seal stamps cleanly on lower-right with twin short ribbons + Sky coupon bar on left
    // 0.52 - 0.74: Diagonal sheen sweep across sovereign bond scroll
    // 0.78 - 1.00: Scroll retracts cleanly; Scene 3's Center Platinum Currency Card ($) unfolds cleanly!

    const introU = easeOutCubic(seg(p, 0.02, 0.18));
    const exitScrollU = easeInCubic(seg(p, 0.79, 0.90));
    const toCardU = easeOutCubic(seg(p, 0.85, 1.00));
    const vis = 1 - exitScrollU;

    drawStageShadow(lerp(1.02, 0.80, toCardU), 1);

    if (vis > 0.005) {
      const sc = lerp(1, 0.64, exitScrollU);
      ctx.save();
      ctx.globalAlpha = vis;
      ctx.translate(cx, cy);
      ctx.scale(sc, sc);
      ctx.translate(-cx, -cy);

      // 1. Platinum Bond Sheet Body (Matches Scene 1 p = 1.00 EXACTLY!)
      drawBondSheetBase(sheetW, sheetH);

      // Clipped diagonal sheen across sheet
      const sheenP = seg(p, 0.52, 0.72);
      if (sheenP > 0 && sheenP < 1) {
        ctx.save();
        roundRectPath(cx - sheetW * 0.5, cy - sheetH * 0.5, sheetW, sheetH, s * 0.045);
        ctx.clip();
        drawClippedSheen(cx - sheetW * 0.5, cy - sheetH * 0.5, sheetW, sheetH, sheenP, 0.85);
        ctx.restore();
      }

      // 2. Top & Bottom Sapphire Scroll Cylinders cleanly capping sheet ends
      if (introU > 0.005) {
        const rollW = lerp(sheetW * 0.65, s * 0.96, introU);
        const rollH = s * 0.105 * introU;
        const rollsY = [cy - sheetH * 0.5, cy + sheetH * 0.5];

        ctx.save();
        ctx.globalAlpha *= introU;
        for (let i = 0; i < 2; i++) {
          const ry = rollsY[i];
          roundRectPath(cx - rollW * 0.5, ry - rollH * 0.5, rollW, rollH, rollH * 0.5);
          ctx.fillStyle = COLORS.sapphireMid;
          ctx.fill();

          ctx.save();
          roundRectPath(cx - rollW * 0.5, ry - rollH * 0.5, rollW, rollH, rollH * 0.5);
          ctx.clip();
          ctx.fillStyle = COLORS.softSky;
          ctx.fillRect(cx - rollW * 0.5, ry - rollH * 0.5, rollW, rollH * 0.28);
          ctx.restore();
        }
        ctx.restore();
      }

      // 3. Upper 3 Structured Bond Text Lines (y: cy - 0.25*s, -0.14*s, -0.03*s -> clear 0.10*s below top roll!)
      if (introU > 0.01) {
        const lineL = cx - s * 0.30;
        const maxW = s * 0.60;
        const lineH = s * 0.046;
        const ratios = [1.0, 0.78, 0.88];

        ctx.save();
        ctx.globalAlpha *= introU;
        for (let i = 0; i < 3; i++) {
          const ly = cy - s * 0.24 + i * s * 0.105;
          const drawU = easeOutCubic(seg(p, 0.08 + i * 0.07, 0.28 + i * 0.07));
          const curW = maxW * ratios[i] * drawU;
          if (curW > lineH * 0.5) {
            roundRectPath(lineL, ly - lineH * 0.5, curW, lineH, lineH * 0.5);
            ctx.fillStyle = i === 0 ? COLORS.sapphireDark : COLORS.sapphireMid;
            ctx.fill();
          }
        }

        // Lower-Left Bond Yield Coupon Tag (strictly x: cx - 0.30*s to cx - 0.04*s -> clear 0.10*s gap from Ruby seal!)
        const tagIn = easeOutCubic(seg(p, 0.20, 0.36));
        if (tagIn > 0.01) {
          const tagY = cy + s * 0.18;
          roundRectPath(lineL, tagY - s * 0.032, s * 0.26 * tagIn, s * 0.064, s * 0.032);
          ctx.fillStyle = COLORS.skyBright;
          ctx.fill();

          roundRectPath(lineL, tagY + s * 0.075 - s * 0.020, s * 0.18 * tagIn, s * 0.040, s * 0.020);
          ctx.fillStyle = COLORS.sapphireMid;
          ctx.fill();
        }
        ctx.restore();
      }

      // 4. Lower-Right Sovereign Crimson Ruby Seal & Twin Short Ribbons (strictly above bottom scroll roll!)
      // Center (cx + 0.19*s, cy + 0.19*s), r = 0.115*s -> ribbons end at cy + 0.36*s, bottom roll top is cy + 0.38*s!
      const sealIn = easeOutCubic(seg(p, 0.26, 0.42));
      if (sealIn > 0.01) {
        const sx = cx + s * 0.19;
        const sy = cy + s * 0.185;
        const sealScale = lerp(1.16, 1.0, sealIn);
        const sr = s * 0.112 * sealScale;

        ctx.save();
        ctx.globalAlpha *= clamp01(sealIn * 1.5);

        // Twin Crisp Short Ruby Ribbons extending downward strictly inside sheet clearance
        const ribIn = easeOutCubic(seg(p, 0.34, 0.46));
        if (ribIn > 0.01) {
          const ribH = s * 0.165 * ribIn;
          const ribW = s * 0.056;
          for (let side = -1; side <= 1; side += 2) {
            const rx = sx + side * s * 0.042;
            ctx.beginPath();
            ctx.moveTo(rx - ribW * 0.5, sy + sr * 0.45);
            ctx.lineTo(rx + ribW * 0.5, sy + sr * 0.45);
            ctx.lineTo(rx + ribW * 0.5, sy + sr * 0.45 + ribH);
            ctx.lineTo(rx, sy + sr * 0.45 + ribH - s * 0.035 * ribIn);
            ctx.lineTo(rx - ribW * 0.5, sy + sr * 0.45 + ribH);
            ctx.closePath();
            ctx.fillStyle = COLORS.rubyDeep;
            ctx.fill();
          }
        }

        // Bold Circular Crimson Ruby Seal Disc
        ctx.beginPath();
        ctx.arc(sx, sy, sr, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.ruby;
        ctx.fill();

        // Crisp Inner Platinum Diamond Hallmark
        drawDiamond(sx, sy, sr * 0.44, sr * 0.44, COLORS.platinum);

        ctx.restore();
      }

      ctx.restore();
    }

    // Seamless Handoff: Scene 3 Center Currency Card ($) emerging cleanly at (cx, cy) (p = 0.85 -> 1.00)!
    if (toCardU > 0.005) {
      drawCurrencyCard(cx, cy, s * 0.36 * toCardU, s * 0.46 * toCardU, 0, toCardU);
    }
  }

  // Shared 2D Flat Multi-Currency Tile (idx: 0 = '$', 1 = '€', 2 = '£')
  function drawCurrencyCard(x, y, w, h, idx, alpha) {
    if (alpha <= 0.005 || w <= 2 || h <= 2) return;
    const rad = Math.min(w, h) * 0.16;
    const left = x - w * 0.5;
    const top = y - h * 0.5;
    const accents = [COLORS.ruby, COLORS.skyBright, COLORS.sapphireMid];
    const symbols = ['$', '\u20AC', '\u00A3'];

    ctx.save();
    ctx.globalAlpha = alpha;

    // Platinum Card Body
    roundRectPath(left, top, w, h, rad);
    ctx.fillStyle = COLORS.platinum;
    ctx.fill();

    // Clipped Right Shade & Colored Top Accent Band
    ctx.save();
    roundRectPath(left, top, w, h, rad);
    ctx.clip();

    ctx.fillStyle = COLORS.platinumShade;
    ctx.fillRect(x, top, w * 0.55, h);

    ctx.fillStyle = accents[idx];
    ctx.fillRect(left, top, w, h * 0.22);

    // Subtle bottom grounding bar
    ctx.fillStyle = COLORS.sapphireRecess;
    ctx.fillRect(left + w * 0.22, top + h * 0.82, w * 0.56, h * 0.055);
    ctx.restore();

    // Crisp Centered Universal Currency Symbol (Non-Brand)
    ctx.fillStyle = COLORS.sapphireRecess;
    ctx.font = '700 ' + Math.round(h * 0.42) + 'px system-ui, -apple-system, Segoe UI, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(symbols[idx], x, y + h * 0.06);

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10s - 15s): MULTI-CURRENCY SHUFFLE (3 GLOBAL CURRENCY TILES)
  // =========================================================================
  function drawScene3(p) {
    // 0.00 - 0.18: Euro (€) & Pound (£) cards glide smoothly out from behind Dollar ($) into wide flanking slots!
    // 0.22 - 0.46: Synchronized Shuffle Beat 1 (smoothly rotates slots: € moves to Hero Center!)
    // 0.50 - 0.74: Synchronized Shuffle Beat 2 (smoothly rotates slots: £ moves to Hero Center!)
    // 0.78 - 1.00: Cards converge & retract smoothly; Scene 4's Crown Base Band extends cleanly!

    const spreadU = easeOutCubic(seg(p, 0.02, 0.18));
    const exitCardsU = easeInCubic(seg(p, 0.79, 0.90));
    const toCrownU = easeOutCubic(seg(p, 0.85, 1.00));
    const vis = 1 - exitCardsU;

    drawStageShadow(lerp(0.80, 1.32, spreadU * vis), 1);

    if (vis > 0.005) {
      // 3 Wide Non-Overlapping Slot Coordinates (Center halfW=0.19*s, Side inner=0.28*s -> 0.09*s crystal clear gap!)
      const slots = [
        { x: cx - s * 0.44 * spreadU, y: cy + s * 0.03, sc: 0.88, z: 0 }, // Slot 0: Left
        { x: cx, y: cy - s * 0.03 * spreadU, sc: lerp(1.0, 1.06, spreadU), z: 1 }, // Slot 1: Center Hero
        { x: cx + s * 0.44 * spreadU, y: cy + s * 0.03, sc: 0.88, z: 0 } // Slot 2: Right
      ];

      const sh1 = easeInOutCubic(seg(p, 0.22, 0.44));
      const sh2 = easeInOutCubic(seg(p, 0.50, 0.72));

      function evalCardState(cardIdx) {
        // Initial slots: Card 0 ($) -> Center (1), Card 1 (€) -> Left (0), Card 2 (£) -> Right (2)
        const initSlot = cardIdx === 0 ? 1 : (cardIdx === 1 ? 0 : 2);
        let sA = initSlot;
        let sB = initSlot;
        let u = 0;

        if (p < 0.47) {
          // Beat 1: 0 -> 1, 1 -> 2, 2 -> 0
          sA = initSlot;
          sB = (initSlot + 1) % 3;
          u = sh1;
        } else {
          // Beat 2: advance one more step
          sA = (initSlot + 1) % 3;
          sB = (initSlot + 2) % 3;
          u = sh2;
        }

        const from = slots[sA];
        const to = slots[sB];
        // Clean slight vertical pass arc only on the card wrapping back (2 -> 0) so cards pass cleanly behind!
        const isWrap = (sA === 2 && sB === 0);
        const arcY = isWrap ? Math.sin(u * Math.PI) * s * 0.08 : -Math.sin(u * Math.PI) * s * 0.03;
        const curX = lerp(from.x, to.x, u);
        const curY = lerp(from.y, to.y, u) + arcY;
        const curSc = lerp(from.sc, to.sc, u) * (isWrap ? (1 - Math.sin(u * Math.PI) * 0.14) : 1);
        const zOrder = isWrap ? -1 : lerp(from.z, to.z, u);
        const cardAlpha = cardIdx === 0 ? vis : clamp01(spreadU * 1.4) * vis;

        return { idx: cardIdx, x: lerp(curX, cx, exitCardsU * 0.6), y: curY, sc: curSc * lerp(1, 0.62, exitCardsU), z: zOrder, alpha: cardAlpha };
      }

      const items = [evalCardState(0), evalCardState(1), evalCardState(2)];
      // Strict deterministic z-sort so Center Hero card is always crisp on top!
      items.sort(function (a, b) { return a.z - b.z; });

      for (let i = 0; i < items.length; i++) {
        const it = items[i];
        drawCurrencyCard(it.x, it.y, s * 0.36 * it.sc, s * 0.46 * it.sc, it.idx, it.alpha);
      }

      // Clean Horizontal Accent Dots below the 3 slots showing active spotlight card
      const dotVis = easeOutCubic(seg(p, 0.16, 0.26)) * (1 - easeInCubic(seg(p, 0.74, 0.82)));
      if (dotVis > 0.005) {
        const activeIdx = p < 0.33 ? 0 : (p < 0.61 ? 1 : 2);
        const dotY = cy + s * 0.38;
        ctx.save();
        ctx.globalAlpha = dotVis;
        for (let k = 0; k < 3; k++) {
          const dx = cx + (k - 1) * s * 0.11;
          const isAct = k === activeIdx;
          const dw = isAct ? s * 0.068 : s * 0.028;
          const dh = s * 0.028;
          roundRectPath(dx - dw * 0.5, dotY - dh * 0.5, dw, dh, dh * 0.5);
          ctx.fillStyle = isAct ? COLORS.ruby : COLORS.sapphireMid;
          ctx.fill();
        }
        ctx.restore();
      }
    }

    // Seamless Handoff: Scene 4 Platinum Crown Base Band extending cleanly at y = cy + 0.30*s (p = 0.85 -> 1.00)!
    if (toCrownU > 0.005) {
      drawCrownBaseBand(s * 0.88 * toCrownU, toCrownU);
    }
  }

  // Shared Crown Base Band (Scene 3 -> Scene 4 Exact Handoff)
  function drawCrownBaseBand(w, alpha) {
    if (alpha <= 0.005 || w <= 2) return;
    const h = s * 0.135;
    const y = cy + s * 0.30;
    ctx.save();
    ctx.globalAlpha = alpha;
    roundRectPath(cx - w * 0.5, y - h * 0.5, w, h, s * 0.038);
    ctx.fillStyle = COLORS.sapphireMid;
    ctx.fill();

    ctx.save();
    roundRectPath(cx - w * 0.5, y - h * 0.5, w, h, s * 0.038);
    ctx.clip();
    ctx.fillStyle = COLORS.sapphireDark;
    ctx.fillRect(cx, y - h * 0.55, w * 0.55, h * 1.1);
    ctx.fillStyle = COLORS.softSky;
    ctx.fillRect(cx - w * 0.5, y - h * 0.5, w, h * 0.24);
    ctx.restore();

    // 3 Crisp Centered Platinum Inlay Gems inside band
    const inlayR = s * 0.026 * clamp01(w / (s * 0.6));
    for (let k = -1; k <= 1; k++) {
      drawDiamond(cx + k * s * 0.20 * (w / (s * 0.88)), y + s * 0.012, inlayR, inlayR, k === 0 ? COLORS.ruby : COLORS.platinum);
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15s - 20s): GLOBAL CAPITAL CROWN -> SEAMLESS LOOP TO GLOBE
  // =========================================================================
  function drawScene4(p) {
    // 0.00 - 0.24: 3-point Platinum Silver Capital Crown rises cleanly above base band; 3 Ruby jewels bloom above peaks!
    // 0.24 - 0.76: Diagonal sheen sweeps across Platinum crown while 3 Crimson Ruby jewels shimmer in sequence!
    // 0.78 - 1.00: Crown & jewels retract cleanly; Scene 1 Global Meridian Hub Globe expands seamlessly -> EXACT t = 0.0!

    const buildU = easeOutCubic(seg(p, 0.02, 0.24));
    const exitCrownU = easeInCubic(seg(p, 0.79, 0.90));
    const toGlobeU = easeOutCubic(seg(p, 0.85, 1.00));
    const vis = 1 - exitCrownU;

    drawStageShadow(lerp(1.02, 0.96, toGlobeU), 1);

    if (vis > 0.005) {
      const sc = lerp(1, 0.62, exitCrownU);
      ctx.save();
      ctx.globalAlpha = vis;
      ctx.translate(cx, cy + s * 0.06);
      ctx.scale(sc, sc);
      ctx.translate(-cx, -(cy + s * 0.06));

      // 1. Crown Base Band (Continuous from Scene 3 p = 1.00!)
      drawCrownBaseBand(s * 0.88, 1);

      // 2. Architectural 3-Peak Platinum Crown Body (strictly 0.028*s clean architectural seam above base band!)
      if (buildU > 0.01) {
        const botY = cy + s * 0.205;
        const sidePeakY = lerp(botY, cy - s * 0.16, buildU);
        const midPeakY = lerp(botY, cy - s * 0.30, buildU);
        const valleyY = lerp(botY, cy + s * 0.02, buildU);

        const baseHalfW = s * 0.42;
        const topHalfW = s * 0.46;

        function crownBodyPath() {
          ctx.beginPath();
          ctx.moveTo(cx - baseHalfW, botY);
          ctx.lineTo(cx - topHalfW, sidePeakY);
          ctx.lineTo(cx - s * 0.20, valleyY);
          ctx.lineTo(cx, midPeakY);
          ctx.lineTo(cx + s * 0.20, valleyY);
          ctx.lineTo(cx + topHalfW, sidePeakY);
          ctx.lineTo(cx + baseHalfW, botY);
          ctx.closePath();
        }

        crownBodyPath();
        ctx.fillStyle = COLORS.platinum;
        ctx.fill();

        // Clipped Right-Half Flat Silver Shade, Lower Soft Sky Accent Band & Diagonal Sheen
        ctx.save();
        crownBodyPath();
        ctx.clip();

        ctx.fillStyle = COLORS.platinumShade;
        ctx.fillRect(cx, midPeakY - 4, topHalfW + 6, botY - midPeakY + 10);

        ctx.fillStyle = COLORS.softSky;
        ctx.fillRect(cx - topHalfW, botY - s * 0.055 * buildU, topHalfW * 2, s * 0.06);

        const sheenP = seg(p, 0.46, 0.68);
        if (sheenP > 0 && sheenP < 1) {
          drawClippedSheen(cx - topHalfW, midPeakY, topHalfW * 2, botY - midPeakY, sheenP, 0.92);
        }
        ctx.restore();

        // 3. Three Crimson Ruby Jewels strictly perched in clean open air ABOVE the 3 crown tips (wide clearance!)
        const jewels = [
          { x: cx - topHalfW, y: cy - s * 0.275, r: s * 0.064, delay: 0.14 },
          { x: cx, y: cy - s * 0.435, r: s * 0.082, delay: 0.20 },
          { x: cx + topHalfW, y: cy - s * 0.275, r: s * 0.064, delay: 0.26 }
        ];

        for (let j = 0; j < 3; j++) {
          const jw = jewels[j];
          const jIn = easeOutCubic(seg(p, jw.delay, jw.delay + 0.14));
          if (jIn <= 0.01) continue;
          const shimmer = 1 + 0.10 * Math.sin(seg(p, 0.30, 0.78) * Math.PI * 4 - j * 1.1);
          const jr = jw.r * jIn * shimmer;
          const jy = jw.y + lerp(s * 0.04, 0, jIn);

          drawDiamond(jw.x, jy, jr, jr * 1.12, COLORS.ruby);
          drawDiamond(jw.x, jy, jr * 0.44, jr * 0.50, COLORS.rubyBright);
        }
      }

      ctx.restore();
    }

    // Seamless Loop Return: Scene 1 Global Meridian Hub Globe expanding cleanly at (cx, cy) (p = 0.85 -> 1.00) -> EXACT t = 0.0!
    if (toGlobeU > 0.005) {
      drawCartographicGlobe(s * 0.48 * toGlobeU, 0, 0, 0, toGlobeU);
    }
  }

  // Render Frame
  ctx.save();
  drawBackground();

  if (currentScene === 0) {
    drawScene1(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3(sceneProgress);
  } else {
    drawScene4(sceneProgress);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide * 0.42;
  const phase = (loopT / duration) * Math.PI * 2;

  const COLORS = {
    bgTop: '#050B1C',
    bgMid: '#0B1736',
    bgBot: '#11224D',
    tangerine: '#FF6B35',
    tangerineDeep: '#E04F1F',
    solarYellow: '#FACC15',
    solarBright: '#FDE047',
    crispWhite: '#F8FAFC',
    silverShade: '#CBD5E1',
    cobaltCard: '#152A5E',
    cobaltShade: '#10214B',
    cobaltRecess: '#0A1533',
    cobaltAccent: '#2563EB',
    cobaltMid: '#1D4ED8',
    stageShadow: 'rgba(2, 5, 16, 0.48)',
    sheen: 'rgba(248, 250, 252, 0.19)',
    ambientMark: '#233B73'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function seg(p, a, b) {
    return clamp01((p - a) / (b - a));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp01(u);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fill) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function drawClippedSheen(x, y, w, h, progress, alpha) {
    if (progress <= 0 || progress >= 1) return;
    const bandW = w * 0.22;
    const travel = w + h * 0.65 + bandW * 2;
    const startX = x - h * 0.35 - bandW + progress * travel;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.beginPath();
    ctx.moveTo(startX, y - h * 0.1);
    ctx.lineTo(startX + bandW, y - h * 0.1);
    ctx.lineTo(startX + bandW - h * 0.45, y + h * 1.1);
    ctx.lineTo(startX - h * 0.45, y + h * 1.1);
    ctx.closePath();
    ctx.fillStyle = COLORS.sheen;
    ctx.fill();
    ctx.restore();
  }

  function drawStageShadow(widthFactor, alpha) {
    if (alpha <= 0.001 || widthFactor <= 0.001) return;
    const sw = s * 0.56 * widthFactor;
    const sh = s * 0.044;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.ellipse(cx, cy + s * 0.68, sw, sh, 0, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.stageShadow;
    ctx.fill();
    ctx.restore();
  }

  // Clean Modern Void Cobalt Navy Gradient Background (Zero Glow, Zero Edge Frames, Zero Corner Brackets)
  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, COLORS.bgTop);
    bgGrad.addColorStop(0.5, COLORS.bgMid);
    bgGrad.addColorStop(1, COLORS.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle crisp flat vector micro-accents strictly in outer margins far from hero icon
    const marks = [
      { nx: 0.10, ny: 0.25, type: 0, sz: 0.011, ph: 0.2, amp: 0.013, op: 0.22 },
      { nx: 0.16, ny: 0.72, type: 1, sz: 0.010, ph: 1.7, amp: 0.012, op: 0.18 },
      { nx: 0.08, ny: 0.53, type: 2, sz: 0.008, ph: 3.2, amp: 0.010, op: 0.16 },
      { nx: 0.20, ny: 0.34, type: 0, sz: 0.008, ph: 4.6, amp: 0.011, op: 0.15 },
      { nx: 0.90, ny: 0.26, type: 1, sz: 0.011, ph: 0.8, amp: 0.013, op: 0.20 },
      { nx: 0.84, ny: 0.74, type: 0, sz: 0.011, ph: 2.5, amp: 0.012, op: 0.22 },
      { nx: 0.92, ny: 0.56, type: 2, sz: 0.008, ph: 4.1, amp: 0.010, op: 0.16 },
      { nx: 0.80, ny: 0.36, type: 1, sz: 0.008, ph: 5.4, amp: 0.011, op: 0.15 }
    ];

    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      const mx = width * m.nx + Math.cos(phase + m.ph) * minSide * (m.amp * 0.45);
      const my = height * m.ny + Math.sin(phase + m.ph) * minSide * m.amp;
      const r = minSide * m.sz;
      const pulse = 0.78 + 0.22 * Math.sin(phase * 2 + m.ph);

      ctx.save();
      ctx.globalAlpha = m.op * pulse;
      ctx.fillStyle = COLORS.ambientMark;
      if (m.type === 0) {
        drawDiamond(mx, my, r, r, COLORS.ambientMark);
      } else if (m.type === 1) {
        roundRectPath(mx - r * 1.4, my - r * 0.38, r * 2.8, r * 0.76, r * 0.38);
        ctx.fill();
      } else {
        roundRectPath(mx - r, my - r, r * 2, r * 2, r * 0.36);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  // Shared 2D Flat Market Terminal Panel (Exact Match between Scene 1 Start and Scene 4 End!)
  function drawTerminalPanel(panelW, panelH, breakoutU, candlePhase, innerVis, sheenP, alpha) {
    if (alpha <= 0.005 || panelW <= 2 || panelH <= 2) return;
    const rad = s * 0.105;
    const left = cx - panelW * 0.5;
    const top = cy - panelH * 0.5;
    const headH = panelH * 0.15;

    ctx.save();
    ctx.globalAlpha = alpha;

    // Outer Cobalt Terminal Chassis
    roundRectPath(left, top, panelW, panelH, rad);
    ctx.fillStyle = COLORS.cobaltCard;
    ctx.fill();

    // Clipped right shade, top header bar & sheen
    ctx.save();
    roundRectPath(left, top, panelW, panelH, rad);
    ctx.clip();

    ctx.fillStyle = COLORS.cobaltShade;
    ctx.fillRect(cx, top, panelW * 0.55, panelH);

    ctx.fillStyle = COLORS.cobaltMid;
    ctx.fillRect(left, top, panelW, headH);

    if (sheenP > 0 && sheenP < 1) {
      drawClippedSheen(left, top, panelW, panelH, sheenP, 0.9);
    }
    ctx.restore();

    // 3 Crisp Header Status Dots cleanly spaced in top-left header
    const dotColors = [COLORS.tangerine, COLORS.solarYellow, COLORS.crispWhite];
    const dotY = top + headH * 0.5;
    const dotR = Math.max(2, s * 0.022);
    for (let d = 0; d < 3; d++) {
      ctx.beginPath();
      ctx.arc(left + s * 0.11 + d * s * 0.072, dotY, dotR, 0, Math.PI * 2);
      ctx.fillStyle = dotColors[d];
      ctx.fill();
    }

    // Recessed Dark Navy Chart Viewport + 5 Candlesticks
    if (innerVis > 0.005) {
      const padX = s * 0.085;
      const vpL = left + padX;
      const vpT = top + headH + s * 0.055;
      const vpW = panelW - padX * 2;
      const vpH = panelH - headH - s * 0.125;

      ctx.save();
      ctx.globalAlpha *= innerVis;

      roundRectPath(vpL, vpT, vpW, vpH, s * 0.055);
      ctx.fillStyle = COLORS.cobaltRecess;
      ctx.fill();

      // Clean Horizontal Resistance / Breakout Line strictly inside viewport
      const resY = vpT + vpH * 0.34;
      ctx.beginPath();
      ctx.moveTo(vpL + s * 0.05, resY);
      ctx.lineTo(vpL + vpW - s * 0.05, resY);
      ctx.strokeStyle = breakoutU > 0.55 ? 'rgba(250, 204, 21, 0.55)' : 'rgba(248, 250, 252, 0.20)';
      ctx.lineWidth = Math.max(1.5, s * 0.012);
      ctx.stroke();

      // 5 Evenly Spaced Flat Vector Candlesticks (clear wide horizontal gaps!)
      const candles = [
        { bTop: 0.62, bBot: 0.80, wTop: 0.53, wBot: 0.87, col: COLORS.cobaltAccent },
        { bTop: 0.52, bBot: 0.72, wTop: 0.44, wBot: 0.80, col: COLORS.tangerine },
        { bTop: 0.56, bBot: 0.74, wTop: 0.47, wBot: 0.82, col: COLORS.cobaltAccent },
        { bTop: 0.42, bBot: 0.62, wTop: 0.36, wBot: 0.70, col: COLORS.tangerine },
        { bTop: 0.40, bBot: 0.58, wTop: 0.35, wBot: 0.66, col: COLORS.solarYellow }
      ];

      const pitch = vpW / 5.4;
      const bodyW = Math.min(s * 0.088, pitch * 0.48);
      const wickW = Math.max(2, s * 0.020);

      for (let i = 0; i < 5; i++) {
        const c = candles[i];
        const x = cx + (i - 2) * pitch;
        const liveShift = Math.sin(candlePhase + i * 1.1) * 0.032 * (i === 4 ? (1 - breakoutU) : 1);

        // Candle 4 surges cleanly ABOVE the resistance line during breakoutU!
        const surgeTop = i === 4 ? lerp(c.bTop, 0.14, breakoutU) : c.bTop + liveShift;
        const surgeBot = i === 4 ? lerp(c.bBot, 0.46, breakoutU) : c.bBot + liveShift * 0.6;
        const wTop = i === 4 ? lerp(c.wTop, 0.08, breakoutU) : c.wTop + liveShift;
        const wBot = i === 4 ? lerp(c.wBot, 0.54, breakoutU) : c.wBot + liveShift * 0.6;

        const yWT = vpT + vpH * wTop;
        const yWB = vpT + vpH * wBot;
        const yBT = vpT + vpH * surgeTop;
        const yBB = vpT + vpH * surgeBot;

        // Vertical Wick
        roundRectPath(x - wickW * 0.5, yWT, wickW, yWB - yWT, wickW * 0.5);
        ctx.fillStyle = i === 4 && breakoutU > 0.35 ? COLORS.solarBright : COLORS.crispWhite;
        ctx.fill();

        // Solid Candle Body
        roundRectPath(x - bodyW * 0.5, yBT, bodyW, Math.max(4, yBB - yBT), s * 0.020);
        ctx.fillStyle = c.col;
        ctx.fill();
      }

      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 1 (0s - 5s): CANDLESTICK BREAKOUT TERMINAL
  // =========================================================================
  function drawScene1(p) {
    // 0.00 - 0.22: 5 candlesticks breathe smoothly inside terminal panel
    // 0.24 - 0.64: Rightmost candle performs clean Solar Yellow Breakout Surge above resistance line
    // 0.60 - 0.78: Diagonal light sheen sweep across terminal
    // 0.80 - 1.00: Terminal retracts smoothly while Scene 2's Bold White Optical Lens Bezel emerges at center!

    const breakoutU = easeInOutCubic(seg(p, 0.24, 0.62));
    const candlePhase = p * Math.PI * 2.2;
    const panelOut = easeInCubic(seg(p, 0.80, 0.91));
    const toLensU = easeOutCubic(seg(p, 0.86, 1.00));

    drawStageShadow(lerp(1.18, 0.88, toLensU), 1);

    if (panelOut < 0.995) {
      const sc = lerp(1, 0.68, panelOut);
      drawTerminalPanel(
        s * 1.18 * sc,
        s * 0.84 * sc,
        breakoutU,
        candlePhase,
        1 - easeInCubic(seg(p, 0.78, 0.86)),
        seg(p, 0.58, 0.76),
        1 - panelOut
      );
    }

    // Seamless Handoff: Bold Solid Optical Lens Frame emerging at (cx, cy) (p = 0.86 -> 1.00)!
    if (toLensU > 0.005) {
      drawLensBezelOnly(cx, cy, s * 0.31 * toLensU, toLensU);
    }
  }

  // Shared Bold Optical Lens Frame (Scene 1 -> Scene 2 Exact Handoff; Thick Solid Bezel, NOT Thin HUD!)
  function drawLensBezelOnly(x, y, rOut, alpha) {
    if (alpha <= 0.005 || rOut <= 2) return;
    const rIn = rOut * 0.75;
    ctx.save();
    ctx.globalAlpha = alpha;

    // Dark tinted optical glass disc inside
    ctx.beginPath();
    ctx.arc(x, y, rIn, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.cobaltRecess;
    ctx.fill();

    // Thick solid Crisp White circular bezel ring
    ctx.beginPath();
    ctx.arc(x, y, rOut, 0, Math.PI * 2);
    ctx.arc(x, y, rIn, 0, Math.PI * 2, true);
    ctx.fillStyle = COLORS.crispWhite;
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5s - 10s): ANALYTICAL LENS ZOOM (TRUE CLIPPED OPTICAL MAGNIFICATION)
  // =========================================================================
  function drawScene2(p) {
    // 0.00 - 0.18: Chart track card reveals behind lens; Tangerine handle extends at 45 deg; lens moves to left
    // 0.18 - 0.74: Magnifying glass smoothly scans ascending trend left -> right with 1.48x optical clip magnification!
    // 0.78 - 1.00: Track & handle retract; lens centers & morphs into Scene 3's Rocket Cabin Porthole Core!

    const introU = easeOutCubic(seg(p, 0.02, 0.18));
    const exitSceneU = easeInCubic(seg(p, 0.80, 0.91));
    const toCoreU = easeOutCubic(seg(p, 0.86, 1.00));
    const scanU = easeInOutCubic(seg(p, 0.18, 0.74));
    const vis = 1 - exitSceneU;

    drawStageShadow(lerp(0.88, 0.64, toCoreU), 1);

    // Trend Curve Waypoints across the horizontal chart card
    const trackW = s * 1.18;
    const trackH = s * 0.42;
    const trackL = cx - trackW * 0.5;
    const trackT = cy - trackH * 0.5;
    const pts = [
      { x: cx - s * 0.46, y: cy + s * 0.10 },
      { x: cx - s * 0.22, y: cy + s * 0.02 },
      { x: cx - s * 0.04, y: cy + s * 0.08 },
      { x: cx + s * 0.20, y: cy - s * 0.06 },
      { x: cx + s * 0.46, y: cy - s * 0.14 }
    ];

    function drawTrendChart(scaleAroundX, scaleAroundY, zoom, strokeColor, nodeColor, lw) {
      ctx.save();
      if (zoom !== 1) {
        ctx.translate(scaleAroundX, scaleAroundY);
        ctx.scale(zoom, zoom);
        ctx.translate(-scaleAroundX, -scaleAroundY);
      }

      // Subtle reference horizontal lines
      for (let g = -1; g <= 1; g++) {
        ctx.beginPath();
        ctx.moveTo(trackL + s * 0.06, cy + g * s * 0.11);
        ctx.lineTo(trackL + trackW - s * 0.06, cy + g * s * 0.11);
        ctx.strokeStyle = 'rgba(248, 250, 252, 0.10)';
        ctx.lineWidth = Math.max(1.2, s * 0.008);
        ctx.stroke();
      }

      // Ascending Trend Line
      ctx.beginPath();
      for (let i = 0; i < pts.length; i++) {
        if (i === 0) ctx.moveTo(pts[i].x, pts[i].y);
        else ctx.lineTo(pts[i].x, pts[i].y);
      }
      ctx.strokeStyle = strokeColor;
      ctx.lineWidth = lw;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.stroke();

      // Clean Data Point Nodes
      for (let i = 0; i < pts.length; i++) {
        ctx.beginPath();
        ctx.arc(pts[i].x, pts[i].y, lw * 0.92, 0, Math.PI * 2);
        ctx.fillStyle = nodeColor;
        ctx.fill();
      }
      ctx.restore();
    }

    // 1. Background Chart Track Card (strictly un-magnified 1x view)
    const cardVis = introU * vis;
    if (cardVis > 0.005) {
      ctx.save();
      ctx.globalAlpha = cardVis;
      roundRectPath(trackL, trackT, trackW, trackH, s * 0.075);
      ctx.fillStyle = COLORS.cobaltCard;
      ctx.fill();

      ctx.save();
      roundRectPath(trackL, trackT, trackW, trackH, s * 0.075);
      ctx.clip();
      drawTrendChart(cx, cy, 1, COLORS.tangerine, COLORS.crispWhite, s * 0.028);
      ctx.restore();
      ctx.restore();
    }

    // 2. Scanning Analytical Magnifying Glass (continuous from Scene 1 p = 1.00!)
    if (vis > 0.005) {
      const startLensX = lerp(cx, cx - s * 0.24, introU);
      const startLensY = lerp(cy, cy + s * 0.04, introU);
      const scanX = lerp(startLensX, cx + s * 0.22, scanU);
      const scanY = lerp(startLensY, cy - s * 0.08, scanU);

      const lensX = lerp(scanX, cx, exitSceneU);
      const lensY = lerp(scanY, cy, exitSceneU);
      const rOut = s * 0.31 * lerp(1, 0.52, exitSceneU);
      const rIn = rOut * 0.75;

      ctx.save();
      ctx.globalAlpha = vis;

      // Angled Tangerine Handle extending cleanly down-right at +45 deg from rim (never overlaps glass!)
      const handleExt = introU * (1 - easeInCubic(seg(p, 0.76, 0.86)));
      if (handleExt > 0.01) {
        const ang = Math.PI * 0.25;
        const hLen = s * 0.32 * handleExt;
        const hThick = s * 0.092;

        ctx.save();
        ctx.translate(lensX, lensY);
        ctx.rotate(ang);

        // Solar Yellow ferrule collar cleanly joining rim & handle
        roundRectPath(rOut - s * 0.02, -hThick * 0.44, s * 0.075 * handleExt, hThick * 0.88, s * 0.02);
        ctx.fillStyle = COLORS.solarYellow;
        ctx.fill();

        // Main Tangerine Flame Handle Grip
        roundRectPath(rOut + s * 0.035, -hThick * 0.5, hLen, hThick, hThick * 0.5);
        ctx.fillStyle = COLORS.tangerine;
        ctx.fill();

        ctx.restore();
      }

      // Clipped Optical Glass Aperture (1.48x real-time magnified chart!)
      ctx.save();
      ctx.beginPath();
      ctx.arc(lensX, lensY, rIn, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.cobaltRecess;
      ctx.fill();
      ctx.clip();

      if (cardVis > 0.02) {
        ctx.save();
        ctx.globalAlpha *= cardVis;
        drawTrendChart(lensX, lensY, 1.48, COLORS.solarYellow, COLORS.crispWhite, s * 0.032);
        ctx.restore();
      }

      // Subtle crisp flat diagonal glass reflection highlight inside lens (fades in smoothly with introU)
      if (introU > 0.01) {
        ctx.beginPath();
        ctx.moveTo(lensX - rIn * 0.68, lensY - rIn * 0.15);
        ctx.lineTo(lensX - rIn * 0.15, lensY - rIn * 0.68);
        ctx.lineTo(lensX + rIn * 0.08, lensY - rIn * 0.45);
        ctx.lineTo(lensX - rIn * 0.45, lensY + rIn * 0.08);
        ctx.closePath();
        ctx.fillStyle = 'rgba(248, 250, 252, ' + (0.16 * introU).toFixed(3) + ')';
        ctx.fill();
      }
      ctx.restore();

      // Thick Solid Crisp White Circular Lens Bezel
      ctx.beginPath();
      ctx.arc(lensX, lensY, rOut, 0, Math.PI * 2);
      ctx.arc(lensX, lensY, rIn, 0, Math.PI * 2, true);
      ctx.fillStyle = COLORS.crispWhite;
      ctx.fill();

      ctx.restore();
    }

    // Seamless Handoff: Scene 3 Rocket Cabin Porthole Core emerging cleanly at (cx, cy) (p = 0.86 -> 1.00)!
    if (toCoreU > 0.005) {
      drawRocketPorthole(cx, cy, s * 0.125 * toCoreU, toCoreU);
    }
  }

  // Shared Rocket Cabin Porthole Core (Scene 2 -> Scene 3 Exact Handoff)
  function drawRocketPorthole(x, y, r, alpha) {
    if (alpha <= 0.005 || r <= 1) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.cobaltCard;
    ctx.fill();
    ctx.beginPath();
    ctx.arc(x, y, r * 0.64, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.solarYellow;
    ctx.fill();
    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10s - 15s): MOMENTUM ROCKET VECTOR (45-DEGREE BREAKOUT FLIGHT)
  // =========================================================================
  function drawScene3(p) {
    // 0.00 - 0.22: Sleek 2D flat rocket fuselage, nose cone, twin fins & layered thrust unfold at 45 deg around porthole
    // 0.22 - 0.78: Smooth controlled diagonal ascent glide + harmonic thrust pulse + trailing momentum pills
    // 0.78 - 1.00: Rocket retracts cleanly while Scene 4's Summit Peak Mountain Triangle emerges cleanly!

    const buildU = easeOutCubic(seg(p, 0.02, 0.22));
    const exitRocketU = easeInCubic(seg(p, 0.79, 0.90));
    const toPeakU = easeOutCubic(seg(p, 0.85, 1.00));
    const vis = 1 - exitRocketU;

    drawStageShadow(lerp(0.64, 1.18, toPeakU), 1);

    if (vis > 0.005) {
      const tilt = Math.PI * 0.25; // Clean 45 degrees up-right flight angle
      const backEase = easeInOutCubic(seg(p, 0.04, 0.22));
      const surgeEase = easeInOutCubic(seg(p, 0.22, 0.78));
      const glide = lerp(lerp(0, -s * 0.065, backEase), s * 0.085, surgeEase);
      const rx = cx + Math.sin(tilt) * glide;
      const ry = cy - Math.cos(tilt) * glide;
      const sc = lerp(1, 0.62, exitRocketU);

      ctx.save();
      ctx.globalAlpha = vis;
      ctx.translate(rx, ry);
      ctx.rotate(tilt);
      ctx.scale(sc, sc);

      const bodyW = s * 0.30 * buildU;
      const bodyH = s * 0.68 * buildU;
      const noseY = -bodyH * 0.54;
      const tailY = bodyH * 0.46;

      // 1. Clean Momentum Trajectory Trail Pills strictly BEHIND thrust plume (zero overlap!)
      const trailIn = easeOutCubic(seg(p, 0.20, 0.34)) * (1 - exitRocketU);
      if (trailIn > 0.01) {
        const pillW = s * 0.052;
        const pillH = s * 0.095;
        for (let k = 0; k < 3; k++) {
          const cycle = ((p * 2.2 + k * 0.33) % 1);
          const py = tailY + s * 0.34 + cycle * s * 0.34;
          const pAlpha = Math.sin(cycle * Math.PI) * trailIn * 0.85;
          if (pAlpha <= 0.01) continue;
          ctx.save();
          ctx.globalAlpha *= pAlpha;
          roundRectPath(-pillW * 0.5, py - pillH * 0.5, pillW, pillH * (1 - cycle * 0.35), pillW * 0.5);
          ctx.fillStyle = k % 2 === 0 ? COLORS.solarYellow : COLORS.tangerine;
          ctx.fill();
          ctx.restore();
        }
      }

      // 2. Layered 2-Tone Thrust Plume cleanly below engine nozzle
      const thrustIn = easeOutCubic(seg(p, 0.14, 0.28));
      if (thrustIn > 0.01 && buildU > 0.2) {
        const pulse = 1 + 0.11 * Math.sin(p * Math.PI * 16);
        const fLen = s * 0.26 * thrustIn * pulse;
        const fW = s * 0.11 * thrustIn;
        const fTop = tailY + s * 0.055;

        // Outer Tangerine Flame Teardrop
        ctx.beginPath();
        ctx.moveTo(-fW, fTop);
        ctx.quadraticCurveTo(-fW * 0.85, fTop + fLen * 0.65, 0, fTop + fLen);
        ctx.quadraticCurveTo(fW * 0.85, fTop + fLen * 0.65, fW, fTop);
        ctx.closePath();
        ctx.fillStyle = COLORS.tangerine;
        ctx.fill();

        // Inner Solar Yellow Bright Core
        ctx.beginPath();
        ctx.moveTo(-fW * 0.54, fTop);
        ctx.quadraticCurveTo(-fW * 0.45, fTop + fLen * 0.45, 0, fTop + fLen * 0.66);
        ctx.quadraticCurveTo(fW * 0.45, fTop + fLen * 0.45, fW * 0.54, fTop);
        ctx.closePath();
        ctx.fillStyle = COLORS.solarBright;
        ctx.fill();
      }

      // 3. Symmetrical Swept Side Fins (drawn cleanly flanking lower fuselage)
      if (buildU > 0.05) {
        const finW = s * 0.16 * buildU;
        const finTop = tailY - s * 0.22 * buildU;
        const finBot = tailY + s * 0.05 * buildU;

        for (let side = -1; side <= 1; side += 2) {
          ctx.beginPath();
          ctx.moveTo(side * (bodyW * 0.42), finTop);
          ctx.lineTo(side * (bodyW * 0.46 + finW), finBot);
          ctx.lineTo(side * (bodyW * 0.36), finBot - s * 0.05 * buildU);
          ctx.closePath();
          ctx.fillStyle = side < 0 ? COLORS.tangerine : COLORS.tangerineDeep;
          ctx.fill();
        }

        // Engine Nozzle Base
        const nozW = bodyW * 0.62;
        const nozH = s * 0.065 * buildU;
        roundRectPath(-nozW * 0.5, tailY - s * 0.01, nozW, nozH, s * 0.02);
        ctx.fillStyle = COLORS.cobaltCard;
        ctx.fill();

        // 4. Main Aerodynamic Rocket Fuselage Silhouette
        ctx.beginPath();
        ctx.moveTo(0, noseY);
        ctx.bezierCurveTo(bodyW * 0.58, noseY + bodyH * 0.24, bodyW * 0.54, tailY - bodyH * 0.16, bodyW * 0.38, tailY);
        ctx.lineTo(-bodyW * 0.38, tailY);
        ctx.bezierCurveTo(-bodyW * 0.54, tailY - bodyH * 0.16, -bodyW * 0.58, noseY + bodyH * 0.24, 0, noseY);
        ctx.closePath();
        ctx.fillStyle = COLORS.crispWhite;
        ctx.fill();

        // Clipped right-half subtle shade + Tangerine Nose Cone Cap + sheen
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(0, noseY);
        ctx.bezierCurveTo(bodyW * 0.58, noseY + bodyH * 0.24, bodyW * 0.54, tailY - bodyH * 0.16, bodyW * 0.38, tailY);
        ctx.lineTo(-bodyW * 0.38, tailY);
        ctx.bezierCurveTo(-bodyW * 0.54, tailY - bodyH * 0.16, -bodyW * 0.58, noseY + bodyH * 0.24, 0, noseY);
        ctx.closePath();
        ctx.clip();

        ctx.fillStyle = COLORS.silverShade;
        ctx.fillRect(0, noseY, bodyW * 0.6, bodyH * 1.1);

        // Tangerine Nose Cone Cap
        ctx.fillStyle = COLORS.tangerine;
        ctx.fillRect(-bodyW * 0.6, noseY, bodyW * 1.2, bodyH * 0.28);
        ctx.fillStyle = COLORS.tangerineDeep;
        ctx.fillRect(0, noseY, bodyW * 0.6, bodyH * 0.28);

        ctx.restore();
      }

      // 5. Centered Cabin Porthole (Continuous from Scene 2 p = 1.00!)
      drawRocketPorthole(0, -s * 0.02 * buildU, s * 0.105 * lerp(1.19, 1.0, buildU), 1);

      ctx.restore();
    }

    // Seamless Handoff: Scene 4 Summit Mountain Peak emerging cleanly at center (p = 0.85 -> 1.00)!
    if (toPeakU > 0.005) {
      const baseY = cy + s * 0.435;
      const apexY = lerp(baseY - s * 0.20, cy - s * 0.24, toPeakU);
      const halfW = lerp(s * 0.24, s * 0.46, toPeakU);
      ctx.save();
      ctx.globalAlpha = toPeakU;
      drawMainSummitPeak(cx, apexY, baseY, halfW, toPeakU);
      ctx.restore();
    }
  }

  // Shared Primary Financial Mountain Peak (Scene 3 -> Scene 4 Exact Handoff)
  function drawMainSummitPeak(x, apexY, baseY, halfW, capAlpha) {
    // Left Lit Slope
    ctx.beginPath();
    ctx.moveTo(x, apexY);
    ctx.lineTo(x, baseY);
    ctx.lineTo(x - halfW, baseY);
    ctx.closePath();
    ctx.fillStyle = COLORS.cobaltAccent;
    ctx.fill();

    // Right Shaded Slope
    ctx.beginPath();
    ctx.moveTo(x, apexY);
    ctx.lineTo(x + halfW, baseY);
    ctx.lineTo(x, baseY);
    ctx.closePath();
    ctx.fillStyle = COLORS.cobaltCard;
    ctx.fill();

    // Crisp White Geometric Summit Cap (strictly clipped inside peak triangle)
    if (capAlpha > 0.05) {
      const capY = lerp(apexY, baseY, 0.30);
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(x, apexY);
      ctx.lineTo(x + halfW, baseY);
      ctx.lineTo(x - halfW, baseY);
      ctx.closePath();
      ctx.clip();

      ctx.globalAlpha *= capAlpha;
      ctx.beginPath();
      ctx.moveTo(x - halfW, apexY);
      ctx.lineTo(x + halfW, apexY);
      ctx.lineTo(x + halfW, capY + s * 0.02);
      ctx.lineTo(x + halfW * 0.14, capY - s * 0.03);
      ctx.lineTo(x, capY + s * 0.035);
      ctx.lineTo(x - halfW * 0.14, capY - s * 0.025);
      ctx.lineTo(x - halfW, capY + s * 0.02);
      ctx.closePath();
      ctx.fillStyle = COLORS.crispWhite;
      ctx.fill();
      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 4 (15s - 20s): SUMMIT PEAK FLAG -> SEAMLESS LOOP TO TERMINAL PANEL
  // =========================================================================
  function drawScene4(p) {
    const plinthY = cy + s * 0.48;
    const plinthH = s * 0.052;
    const baseY = cy + s * 0.435;
    const apexY = cy - s * 0.24;

    // 0.00 - 0.22: Base plinth, secondary left shoulder peak, flagpole & Tangerine flag unfurl cleanly
    // 0.22 - 0.76: Smooth analytical sine-wave cloth flag animation + flanking Solar Yellow diamonds
    // 0.78 - 1.00: Mountain & flag retract cleanly; Scene 1 Market Terminal Panel expands seamlessly -> EXACT t = 0.0!

    const introU = easeOutCubic(seg(p, 0.02, 0.20));
    const exitMtnU = easeInCubic(seg(p, 0.78, 0.89));
    const toTermU = easeOutCubic(seg(p, 0.85, 1.00));
    const mtnVis = 1 - exitMtnU;

    drawStageShadow(1.18, 1);

    if (mtnVis > 0.005) {
      const sc = lerp(1, 0.72, exitMtnU);
      ctx.save();
      ctx.globalAlpha = mtnVis;
      ctx.translate(cx, cy + s * 0.12);
      ctx.scale(sc, sc);
      ctx.translate(-cx, -(cy + s * 0.12));

      // 1. Secondary Left Shoulder Peak (drawn cleanly behind primary peak)
      if (introU > 0.005) {
        const sApexX = cx - s * 0.36;
        const sApexY = lerp(baseY, cy + s * 0.02, introU);
        ctx.save();
        ctx.globalAlpha *= introU;
        ctx.beginPath();
        ctx.moveTo(sApexX, sApexY);
        ctx.lineTo(cx - s * 0.10, baseY);
        ctx.lineTo(cx - s * 0.62, baseY);
        ctx.closePath();
        ctx.fillStyle = COLORS.cobaltMid;
        ctx.fill();
        ctx.restore();
      }

      // 2. Primary Summit Peak (Continuous from Scene 3 p = 1.00!)
      drawMainSummitPeak(cx, apexY, baseY, s * 0.46, 1);

      // 3. Base Plinth Bar
      if (introU > 0.005) {
        const pw = s * 1.24 * introU;
        ctx.save();
        ctx.globalAlpha *= introU;
        roundRectPath(cx - pw * 0.5, plinthY - plinthH * 0.5, pw, plinthH, plinthH * 0.5);
        ctx.fillStyle = COLORS.cobaltCard;
        ctx.fill();

        ctx.save();
        roundRectPath(cx - pw * 0.5, plinthY - plinthH * 0.5, pw, plinthH, plinthH * 0.5);
        ctx.clip();
        ctx.fillStyle = COLORS.tangerine;
        ctx.fillRect(cx - pw * 0.5, plinthY - plinthH * 0.5, pw, plinthH * 0.35);
        ctx.restore();
        ctx.restore();
      }

      // 4. Summit Flagpole & Analytical Sine-Wave Cloth Flag strictly ABOVE apexY (100% open air!)
      const poleIn = easeOutCubic(seg(p, 0.06, 0.22));
      const flagIn = easeOutCubic(seg(p, 0.14, 0.32));
      if (poleIn > 0.01) {
        const poleTop = lerp(apexY, cy - s * 0.57, poleIn);
        const poleW = s * 0.030;

        // Solar Yellow Flagpole
        roundRectPath(cx - poleW * 0.5, poleTop, poleW, apexY - poleTop + s * 0.02, poleW * 0.5);
        ctx.fillStyle = COLORS.solarYellow;
        ctx.fill();

        // Crisp Finial Cap Ball
        ctx.beginPath();
        ctx.arc(cx, poleTop, poleW * 0.72, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.crispWhite;
        ctx.fill();

        // Analytical Sine-Wave Waving Tangerine Flag flying cleanly rightward
        if (flagIn > 0.01) {
          const fLeft = cx + poleW * 0.45;
          const fW = s * 0.30 * flagIn;
          const fH = s * 0.175;
          const fTop = poleTop + s * 0.025;
          const wavePhase = p * Math.PI * 6.0;
          const segs = 16;

          ctx.beginPath();
          for (let i = 0; i <= segs; i++) {
            const u = i / segs;
            const fx = fLeft + u * fW;
            const wy = Math.sin(u * Math.PI * 1.9 - wavePhase) * s * 0.022 * u;
            if (i === 0) ctx.moveTo(fx, fTop + wy);
            else ctx.lineTo(fx, fTop + wy);
          }
          for (let i = segs; i >= 0; i--) {
            const u = i / segs;
            const fx = fLeft + u * fW;
            const wy = Math.sin(u * Math.PI * 1.9 - wavePhase) * s * 0.022 * u;
            ctx.lineTo(fx, fTop + fH + wy);
          }
          ctx.closePath();
          ctx.fillStyle = COLORS.tangerine;
          ctx.fill();

          // Clean Solar Yellow horizontal accent stripe along center of waving flag
          ctx.beginPath();
          for (let i = 0; i <= segs; i++) {
            const u = i / segs;
            const fx = fLeft + u * fW;
            const wy = Math.sin(u * Math.PI * 1.9 - wavePhase) * s * 0.022 * u;
            if (i === 0) ctx.moveTo(fx, fTop + fH * 0.38 + wy);
            else ctx.lineTo(fx, fTop + fH * 0.38 + wy);
          }
          for (let i = segs; i >= 0; i--) {
            const u = i / segs;
            const fx = fLeft + u * fW;
            const wy = Math.sin(u * Math.PI * 1.9 - wavePhase) * s * 0.022 * u;
            ctx.lineTo(fx, fTop + fH * 0.62 + wy);
          }
          ctx.closePath();
          ctx.fillStyle = COLORS.solarYellow;
          ctx.fill();
        }
      }

      // Subtle Flanking Solar Yellow Achievement Diamonds cleanly in upper outer open air
      const accVis = easeOutCubic(seg(p, 0.28, 0.42)) * (1 - easeInCubic(seg(p, 0.70, 0.78)));
      if (accVis > 0.005) {
        const pulse = 0.78 + 0.22 * Math.sin(seg(p, 0.30, 0.76) * Math.PI * 4);
        ctx.save();
        ctx.globalAlpha *= accVis;
        drawDiamond(cx - s * 0.50, cy - s * 0.34, s * 0.044 * pulse, s * 0.044 * pulse, COLORS.solarYellow);
        drawDiamond(cx + s * 0.52, cy - s * 0.26, s * 0.038 * pulse, s * 0.038 * pulse, COLORS.crispWhite);
        ctx.restore();
      }

      ctx.restore();
    }

    // Seamless Loop Return: Scene 1 Market Terminal Panel expanding cleanly at center (p = 0.85 -> 1.00) -> EXACT t = 0.0!
    if (toTermU > 0.005) {
      const curW = lerp(s * 0.52, s * 1.18, toTermU);
      const curH = lerp(s * 0.38, s * 0.84, toTermU);
      const innerIn = easeOutCubic(seg(p, 0.90, 1.00));
      drawTerminalPanel(curW, curH, 0, 0, innerIn, 0, toTermU);
    }
  }

  // Render Frame
  ctx.save();
  drawBackground();

  if (currentScene === 0) {
    drawScene1(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3(sceneProgress);
  } else {
    drawScene4(sceneProgress);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide * 0.42;
  const phase = (loopT / duration) * Math.PI * 2;

  const COLORS = {
    bgTop: '#0C0C12',
    bgMid: '#151321',
    bgBot: '#1E1A30',
    ultraNeon: '#A855F7',
    violetMain: '#7C3AED',
    violetDeep: '#5B21B6',
    lavender: '#E9D5FF',
    lavenderBright: '#F3E8FF',
    graphiteCard: '#261F3B',
    graphiteShade: '#1D172E',
    graphiteRecess: '#130F21',
    stageShadow: 'rgba(6, 4, 14, 0.48)',
    sheen: 'rgba(243, 232, 255, 0.20)',
    ambientMark: '#3E335C'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function seg(p, a, b) {
    return clamp01((p - a) / (b - a));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp01(u);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  // Pointy-Top Regular Hexagon Path
  function pointyHexPath(x, y, r) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = (i * Math.PI) / 3 - Math.PI * 0.5;
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fill) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function drawClippedSheen(x, y, w, h, progress, alpha) {
    if (progress <= 0 || progress >= 1) return;
    const bandW = w * 0.22;
    const travel = w + h * 0.65 + bandW * 2;
    const startX = x - h * 0.35 - bandW + progress * travel;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.beginPath();
    ctx.moveTo(startX, y - h * 0.1);
    ctx.lineTo(startX + bandW, y - h * 0.1);
    ctx.lineTo(startX + bandW - h * 0.45, y + h * 1.1);
    ctx.lineTo(startX - h * 0.45, y + h * 1.1);
    ctx.closePath();
    ctx.fillStyle = COLORS.sheen;
    ctx.fill();
    ctx.restore();
  }

  function drawStageShadow(widthFactor, alpha) {
    if (alpha <= 0.001 || widthFactor <= 0.001) return;
    const sw = s * 0.54 * widthFactor;
    const sh = s * 0.044;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.ellipse(cx, cy + s * 0.68, sw, sh, 0, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.stageShadow;
    ctx.fill();
    ctx.restore();
  }

  // Clean Modern Smoked Graphite Gradient Background (Zero Glow, Zero Edge Frames, Zero Corner Brackets)
  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, COLORS.bgTop);
    bgGrad.addColorStop(0.5, COLORS.bgMid);
    bgGrad.addColorStop(1, COLORS.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle crisp flat vector micro-accents strictly in outer margins far from hero icon
    const marks = [
      { nx: 0.10, ny: 0.25, type: 0, sz: 0.011, ph: 0.3, amp: 0.013, op: 0.22 },
      { nx: 0.16, ny: 0.72, type: 1, sz: 0.010, ph: 1.9, amp: 0.012, op: 0.18 },
      { nx: 0.08, ny: 0.54, type: 2, sz: 0.008, ph: 3.4, amp: 0.010, op: 0.16 },
      { nx: 0.20, ny: 0.35, type: 0, sz: 0.008, ph: 4.8, amp: 0.011, op: 0.15 },
      { nx: 0.90, ny: 0.26, type: 1, sz: 0.011, ph: 1.0, amp: 0.013, op: 0.20 },
      { nx: 0.84, ny: 0.74, type: 0, sz: 0.011, ph: 2.7, amp: 0.012, op: 0.22 },
      { nx: 0.92, ny: 0.55, type: 2, sz: 0.008, ph: 4.2, amp: 0.010, op: 0.16 },
      { nx: 0.80, ny: 0.36, type: 1, sz: 0.008, ph: 5.5, amp: 0.011, op: 0.15 }
    ];

    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      const mx = width * m.nx + Math.cos(phase + m.ph) * minSide * (m.amp * 0.45);
      const my = height * m.ny + Math.sin(phase + m.ph) * minSide * m.amp;
      const r = minSide * m.sz;
      const pulse = 0.78 + 0.22 * Math.sin(phase * 2 + m.ph);

      ctx.save();
      ctx.globalAlpha = m.op * pulse;
      ctx.fillStyle = COLORS.ambientMark;
      if (m.type === 0) {
        pointyHexPath(mx, my, r);
        ctx.fill();
      } else if (m.type === 1) {
        drawDiamond(mx, my, r, r, COLORS.ambientMark);
      } else {
        roundRectPath(mx - r * 1.45, my - r * 0.35, r * 2.9, r * 0.70, r * 0.35);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  // Shared 2D Flat Hexagonal Asset Token (Exact Match between Scene 1 Start and Scene 4 End!)
  function drawHexAssetToken(x, y, radius, prismRot, prismSplit, sheenP, alpha) {
    if (alpha <= 0.005 || radius <= 2) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(x, y);

    // Outer Ultraviolet Hexagon
    pointyHexPath(0, 0, radius);
    ctx.fillStyle = COLORS.ultraNeon;
    ctx.fill();

    // Right-half flat Electric Violet split-tone bevel
    ctx.save();
    pointyHexPath(0, 0, radius);
    ctx.clip();
    ctx.fillStyle = COLORS.violetMain;
    ctx.fillRect(0, -radius * 1.1, radius * 1.1, radius * 2.2);
    ctx.restore();

    // Inner Recessed Dark Graphite Hexagon
    const inR = radius * 0.78;
    pointyHexPath(0, 0, inR);
    ctx.fillStyle = COLORS.graphiteRecess;
    ctx.fill();

    // Clean Abstract Symmetric Double-Prism Digital Emblem (100% Original, Non-Brand!)
    const pW = inR * 0.50;
    const pH = inR * 0.48;
    const gap = inR * (0.055 + 0.045 * prismSplit);

    ctx.save();
    ctx.rotate(prismRot);

    // Upper Lavender Prism Chevron-Triangle
    ctx.beginPath();
    ctx.moveTo(0, -pH - gap);
    ctx.lineTo(pW, -gap);
    ctx.lineTo(0, -gap - pH * 0.28);
    ctx.lineTo(-pW, -gap);
    ctx.closePath();
    ctx.fillStyle = COLORS.lavender;
    ctx.fill();

    // Lower Ultraviolet Mirror Prism
    ctx.beginPath();
    ctx.moveTo(0, pH + gap);
    ctx.lineTo(pW, gap);
    ctx.lineTo(0, gap + pH * 0.28);
    ctx.lineTo(-pW, gap);
    ctx.closePath();
    ctx.fillStyle = COLORS.ultraNeon;
    ctx.fill();

    // Center Micro-Diamond Core cleanly centered in the prism gap
    drawDiamond(0, 0, inR * 0.14, inR * 0.14, COLORS.lavenderBright);

    ctx.restore();

    // Clipped Diagonal Light Sheen across entire token
    if (sheenP > 0 && sheenP < 1) {
      ctx.save();
      pointyHexPath(0, 0, radius);
      ctx.clip();
      drawClippedSheen(-radius, -radius, radius * 2, radius * 2, sheenP, 0.92);
      ctx.restore();
    }

    ctx.restore();
  }

  // Shared Ledger Block Tile (Used in Scene 1 -> Scene 2 Exact Handoff & Scene 2 Linked Nodes)
  function drawLedgerTile(x, y, size, isCenter, activeGlow, alpha) {
    if (alpha <= 0.005 || size <= 2) return;
    const rad = size * 0.20;
    const left = x - size * 0.5;
    const top = y - size * 0.5;

    ctx.save();
    ctx.globalAlpha = alpha;

    // Outer Rounded Tile Housing
    roundRectPath(left, top, size, size, rad);
    ctx.fillStyle = isCenter ? COLORS.ultraNeon : COLORS.violetMain;
    ctx.fill();

    // Right-half flat shade
    ctx.save();
    roundRectPath(left, top, size, size, rad);
    ctx.clip();
    ctx.fillStyle = isCenter ? COLORS.violetMain : COLORS.violetDeep;
    ctx.fillRect(x, top, size * 0.55, size);
    ctx.restore();

    // Recessed Dark Graphite Inner Square
    const inSz = size * 0.72;
    roundRectPath(x - inSz * 0.5, y - inSz * 0.5, inSz, inSz, rad * 0.65);
    ctx.fillStyle = COLORS.graphiteRecess;
    ctx.fill();

    // Center Core Diamond (illuminates cleanly in Lavender Bright when data packet arrives!)
    const dR = inSz * lerp(0.26, 0.34, activeGlow);
    drawDiamond(x, y, dR, dR, activeGlow > 0.35 ? COLORS.lavenderBright : (isCenter ? COLORS.ultraNeon : COLORS.lavender));

    ctx.restore();
  }

  // =========================================================================
  // SCENE 1 (0s - 5s): HEXAGONAL ASSET TOKEN
  // =========================================================================
  function drawScene1(p) {
    // 0.00 - 0.22: Bold Hexagonal Asset Token shines cleanly with diagonal sheen
    // 0.20 - 0.74: Inner dual-prism performs calm precision 180 deg turn while 3 outer micro-hex nodes breathe cleanly
    // 0.78 - 1.00: Token condenses smoothly into Scene 2's Centered Primary Ledger Block Tile!

    const tokOut = easeInCubic(seg(p, 0.79, 0.90));
    const toTileU = easeOutCubic(seg(p, 0.85, 1.00));
    const tokVis = 1 - tokOut;

    drawStageShadow(lerp(0.92, 0.68, toTileU), 1);

    if (tokVis > 0.005) {
      const floatY = Math.sin(seg(p, 0.14, 0.80) * Math.PI * 2) * s * 0.018 * tokVis;
      const prismRot = easeInOutCubic(seg(p, 0.26, 0.66)) * Math.PI;
      const prismSplit = Math.sin(seg(p, 0.20, 0.74) * Math.PI);
      const sheenP = p < 0.42 ? seg(p, 0.06, 0.28) : seg(p, 0.58, 0.76);
      const curR = s * 0.48 * lerp(1, 0.58, tokOut);

      drawHexAssetToken(cx, cy + floatY, curR, prismRot, prismSplit, sheenP, tokVis);

      // 3 Crisp Satellite Micro-Hexagons cleanly outside token perimeter (r = 0.63*s -> 0.15*s wide clear gap!)
      const satIn = easeOutCubic(seg(p, 0.18, 0.32));
      const satOut = easeInCubic(seg(p, 0.72, 0.80));
      const satVis = satIn * (1 - satOut);
      if (satVis > 0.005) {
        const satOrbit = s * 0.63;
        const satBaseAng = -Math.PI * 0.5 + seg(p, 0.18, 0.80) * 0.45;
        ctx.save();
        ctx.globalAlpha = satVis;
        for (let k = 0; k < 3; k++) {
          const a = satBaseAng + (k * Math.PI * 2) / 3;
          const sx = cx + Math.cos(a) * satOrbit;
          const sy = cy + floatY + Math.sin(a) * satOrbit;
          const sr = s * 0.048 * (0.82 + 0.18 * Math.sin(seg(p, 0.20, 0.80) * Math.PI * 4 - k * 1.4));
          pointyHexPath(sx, sy, sr);
          ctx.fillStyle = k === 0 ? COLORS.lavender : COLORS.ultraNeon;
          ctx.fill();
        }
        ctx.restore();
      }
    }

    // Seamless Handoff: Scene 2 Center Ledger Tile expanding cleanly at (cx, cy) (p = 0.85 -> 1.00)!
    if (toTileU > 0.005) {
      drawLedgerTile(cx, cy, s * 0.30 * toTileU, true, 0, toTileU);
    }
  }

  // =========================================================================
  // SCENE 2 (5s - 10s): SYNCHRONIZED LEDGER TILES & DATA PACKET STREAM
  // =========================================================================
  function drawScene2(p) {
    // 0.00 - 0.20: Left & Right ledger tiles glide cleanly outward to cx +/- 0.50*s while link channels appear
    // 0.20 - 0.78: Synchronized Lavender data packets travel cleanly across Gap 1 & Gap 2, lighting each node in turn!
    // 0.78 - 1.00: Channels retract, side tiles converge cleanly behind center, center expands into Scene 3 Vault Chip!

    const spreadU = easeOutCubic(seg(p, 0.02, 0.20));
    const convergeU = easeInOutCubic(seg(p, 0.78, 0.90));
    const toChipU = easeInOutCubic(seg(p, 0.86, 1.00));
    const chanVis = easeOutCubic(seg(p, 0.12, 0.24)) * (1 - easeInCubic(seg(p, 0.74, 0.82)));

    const sideDist = s * 0.50 * spreadU * (1 - convergeU);
    const centerSz = s * 0.30;
    const sideSz = s * 0.27;
    const hoverPhase = seg(p, 0.18, 0.80) * Math.PI * 2;
    const hoverAmp = s * 0.015 * (1 - convergeU);

    drawStageShadow(lerp(0.68, 1.32, spreadU * (1 - convergeU)), 1);

    // 1. Horizontal Data Link Channels strictly spanning clear gaps between Center & Side Tiles (ZERO overlap!)
    if (chanVis > 0.005) {
      const chH = s * 0.044;
      const gap1L = cx - s * 0.50 + sideSz * 0.5 + s * 0.01;
      const gap1R = cx - centerSz * 0.5 - s * 0.01;
      const gap2L = cx + centerSz * 0.5 + s * 0.01;
      const gap2R = cx + s * 0.50 - sideSz * 0.5 - s * 0.01;

      ctx.save();
      ctx.globalAlpha = chanVis;

      // Channel 1 Track & Channel 2 Track
      roundRectPath(gap1L, cy - chH * 0.5, gap1R - gap1L, chH, chH * 0.5);
      ctx.fillStyle = COLORS.graphiteCard;
      ctx.fill();

      roundRectPath(gap2L, cy - chH * 0.5, gap2R - gap2L, chH, chH * 0.5);
      ctx.fillStyle = COLORS.graphiteCard;
      ctx.fill();

      // Traveling Bright Lavender Data Packets strictly clipped inside each channel gap!
      const packetW = s * 0.072;
      const wave1 = seg(p, 0.22, 0.48);
      const wave2 = seg(p, 0.48, 0.74);

      function drawPacketOnGap(gL, gR, progress) {
        if (progress <= 0 || progress >= 1) return;
        const px = lerp(gL - packetW * 0.5, gR + packetW * 0.5, progress);
        ctx.save();
        roundRectPath(gL, cy - chH * 0.5, gR - gL, chH, chH * 0.5);
        ctx.clip();
        roundRectPath(px - packetW * 0.5, cy - chH * 0.5, packetW, chH, chH * 0.5);
        ctx.fillStyle = COLORS.lavenderBright;
        ctx.fill();
        ctx.restore();
      }

      // First half of each wave traverses Gap 1 (Left -> Center), second half traverses Gap 2 (Center -> Right)
      drawPacketOnGap(gap1L, gap1R, clamp01(wave1 * 2));
      drawPacketOnGap(gap2L, gap2R, clamp01((wave1 - 0.5) * 2));
      drawPacketOnGap(gap1L, gap1R, clamp01(wave2 * 2));
      drawPacketOnGap(gap2L, gap2R, clamp01((wave2 - 0.5) * 2));

      ctx.restore();
    }

    // Node illumination synchronized with packet arrivals
    const gL = Math.max(Math.sin(clamp01(seg(p, 0.20, 0.30)) * Math.PI), Math.sin(clamp01(seg(p, 0.46, 0.56)) * Math.PI));
    const gC = Math.max(Math.sin(clamp01(seg(p, 0.32, 0.42)) * Math.PI), Math.sin(clamp01(seg(p, 0.58, 0.68)) * Math.PI));
    const gR = Math.max(Math.sin(clamp01(seg(p, 0.42, 0.52)) * Math.PI), Math.sin(clamp01(seg(p, 0.68, 0.78)) * Math.PI));

    // 2. Left & Right Ledger Tiles (drawn behind center tile so emergence/convergence is razor-clean)
    const sideAlpha = clamp01(spreadU * 1.5) * (1 - convergeU);
    if (sideAlpha > 0.005) {
      drawLedgerTile(cx - sideDist, cy + Math.sin(hoverPhase) * hoverAmp, sideSz, false, gL, sideAlpha);
      drawLedgerTile(cx + sideDist, cy + Math.sin(hoverPhase + 2.0) * hoverAmp, sideSz, false, gR, sideAlpha);
    }

    // 3. Center Tile -> Seamlessly expands into Scene 3 Hardware Vault Chip Housing (0.64*s x 0.64*s)!
    if (toChipU <= 0.001) {
      drawLedgerTile(cx, cy + Math.sin(hoverPhase + 1.0) * hoverAmp, centerSz, true, gC, 1);
    } else {
      const curSz = lerp(centerSz, s * 0.64, toChipU);
      const curR = lerp(centerSz * 0.20, s * 0.095, toChipU);
      const tileFade = 1 - easeOutCubic(clamp01(toChipU * 1.8));

      // Expanding Dark Graphite-Violet Chip Body
      roundRectPath(cx - curSz * 0.5, cy - curSz * 0.5, curSz, curSz, curR);
      ctx.fillStyle = COLORS.graphiteCard;
      ctx.fill();

      ctx.save();
      roundRectPath(cx - curSz * 0.5, cy - curSz * 0.5, curSz, curSz, curR);
      ctx.clip();
      ctx.fillStyle = COLORS.graphiteShade;
      ctx.fillRect(cx, cy - curSz * 0.55, curSz * 0.55, curSz * 1.1);
      ctx.restore();

      if (tileFade > 0.005) {
        drawLedgerTile(cx, cy, curSz, true, 0, tileFade);
      }
    }
  }

  // =========================================================================
  // SCENE 3 (10s - 15s): HARDWARE VAULT CHIP (12 PINS & INTERNAL CIRCUITS)
  // =========================================================================
  function drawScene3(p) {
    const chipSz = s * 0.64;
    const chipR = s * 0.095;

    // 0.00 - 0.22: 12 connector pins extend cleanly outward on all 4 sides; inner bezel, 4 traces & core reveal
    // 0.22 - 0.74: Energy pulses flow smoothly inward along 4 orthogonal traces energizing the core diamond + sheen
    // 0.78 - 1.00: Pins & circuits retract cleanly; square chip housing rotates 45 deg into Scene 4 Diamond Swap Frame!

    const pinsIn = easeOutCubic(seg(p, 0.02, 0.20));
    const pinsOut = easeInCubic(seg(p, 0.76, 0.86));
    const pinExt = pinsIn * (1 - pinsOut);
    const innerVis = easeOutCubic(seg(p, 0.04, 0.18)) * (1 - easeInCubic(seg(p, 0.76, 0.86)));
    const toDiamondU = easeInOutCubic(seg(p, 0.84, 1.00));

    drawStageShadow(lerp(0.96, 1.02, toDiamondU), 1);

    const curSz = lerp(chipSz, s * 0.72, toDiamondU);
    const curR = lerp(chipR, s * 0.10, toDiamondU);
    const curRot = toDiamondU * (Math.PI * 0.25); // Smoothly rotates exact 45 degrees into Scene 4 Diamond!

    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(curRot);

    // 1. 12 Exterior Connector Pins (3 evenly spaced on each of the 4 sides, strictly outside housing!)
    if (pinExt > 0.01) {
      const pinOffsets = [-s * 0.16, 0, s * 0.16];
      const pinThick = s * 0.056;
      const pinLen = s * 0.155 * pinExt;
      const half = chipSz * 0.5;

      ctx.save();
      ctx.globalAlpha = clamp01(pinExt * 1.4);
      for (let side = 0; side < 4; side++) {
        ctx.save();
        ctx.rotate((side * Math.PI) / 2);
        for (let k = 0; k < 3; k++) {
          const py = pinOffsets[k];
          // Pin shaft
          roundRectPath(half - s * 0.02, py - pinThick * 0.5, pinLen + s * 0.02, pinThick, pinThick * 0.42);
          ctx.fillStyle = k === 1 ? COLORS.lavender : COLORS.ultraNeon;
          ctx.fill();
        }
        ctx.restore();
      }
      ctx.restore();
    }

    // 2. Main Square Vault Chip Body (Continuous from Scene 2 p = 1.00 -> Rotates into Scene 4 p = 0.00!)
    roundRectPath(-curSz * 0.5, -curSz * 0.5, curSz, curSz, curR);
    ctx.fillStyle = COLORS.graphiteCard;
    ctx.fill();

    // Clipped right-half shade & sheen
    ctx.save();
    roundRectPath(-curSz * 0.5, -curSz * 0.5, curSz, curSz, curR);
    ctx.clip();
    ctx.fillStyle = COLORS.graphiteShade;
    ctx.fillRect(0, -curSz * 0.55, curSz * 0.55, curSz * 1.1);

    const sheenP = seg(p, 0.52, 0.72);
    if (sheenP > 0 && sheenP < 1) {
      drawClippedSheen(-curSz * 0.5, -curSz * 0.5, curSz, curSz, sheenP, 0.9);
    }
    ctx.restore();

    // 3. Recessed Inner Circuit Cavity, 4 Orthogonal Trace Bars & Central Vault Core
    if (innerVis > 0.005) {
      const cavSz = s * 0.48;
      const coreSz = s * 0.21;
      const traceW = s * 0.042;
      const traceLen = (cavSz - coreSz) * 0.5;

      ctx.save();
      ctx.globalAlpha = innerVis;

      // Recessed Dark Cavity
      roundRectPath(-cavSz * 0.5, -cavSz * 0.5, cavSz, cavSz, s * 0.062);
      ctx.fillStyle = COLORS.graphiteRecess;
      ctx.fill();

      // 4 Clean Orthogonal Circuit Traces connecting cavity walls strictly to core edges
      const pulsePhase = seg(p, 0.20, 0.74);
      const p1 = clamp01(pulsePhase * 2);
      const p2 = clamp01((pulsePhase - 0.5) * 2);
      const activeP = pulsePhase < 0.5 ? p1 : p2;

      for (let d = 0; d < 4; d++) {
        ctx.save();
        ctx.rotate((d * Math.PI) / 2);

        // Static violet trace channel
        roundRectPath(coreSz * 0.5 - s * 0.005, -traceW * 0.5, traceLen + s * 0.005, traceW, traceW * 0.4);
        ctx.fillStyle = COLORS.violetDeep;
        ctx.fill();

        // Inward flowing bright Lavender signal pulse strictly along trace length
        if (activeP > 0.02 && activeP < 0.98) {
          const sigLen = traceLen * 0.45;
          const sigX = lerp(cavSz * 0.5 - sigLen, coreSz * 0.5, activeP);
          ctx.save();
          roundRectPath(coreSz * 0.5, -traceW * 0.5, traceLen, traceW, traceW * 0.4);
          ctx.clip();
          roundRectPath(sigX, -traceW * 0.5, sigLen, traceW, traceW * 0.4);
          ctx.fillStyle = COLORS.lavenderBright;
          ctx.fill();
          ctx.restore();
        }
        ctx.restore();
      }

      // Centered Ultraviolet Vault Core Square + Energized Lavender Diamond
      roundRectPath(-coreSz * 0.5, -coreSz * 0.5, coreSz, coreSz, s * 0.042);
      ctx.fillStyle = COLORS.ultraNeon;
      ctx.fill();

      const coreBoost = 1 + 0.12 * Math.sin(activeP * Math.PI);
      drawDiamond(0, 0, coreSz * 0.28 * coreBoost, coreSz * 0.28 * coreBoost, COLORS.lavenderBright);

      ctx.restore();
    }

    ctx.restore();
  }

  // Helper: Clean Solid Horizontal Arrow (dir = +1 Right, -1 Left)
  function drawSwapArrow(x, y, totalW, thick, dir, fill, alpha) {
    if (alpha <= 0.005 || totalW <= 2) return;
    const headW = thick * 1.45;
    const headHalfH = thick * 1.15;
    const shaftW = Math.max(2, totalW - headW * 0.72);

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(x, y);
    if (dir < 0) ctx.scale(-1, 1);

    // Shaft strictly left of arrowhead
    roundRectPath(-totalW * 0.5, -thick * 0.5, shaftW, thick, thick * 0.5);
    ctx.fillStyle = fill;
    ctx.fill();

    // Sharp Solid Arrowhead
    ctx.beginPath();
    ctx.moveTo(totalW * 0.5, 0);
    ctx.lineTo(totalW * 0.5 - headW, -headHalfH);
    ctx.lineTo(totalW * 0.5 - headW * 0.72, 0);
    ctx.lineTo(totalW * 0.5 - headW, headHalfH);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15s - 20s): INSTANT SWAP PRISM -> SEAMLESS LOOP TO HEX TOKEN
  // =========================================================================
  function drawScene4(p) {
    const frameSz = s * 0.72;
    const frameR = s * 0.10;

    // 0.00 - 0.18: Inner dark diamond cavity & twin parallel bidirectional swap arrows reveal cleanly
    // 0.18 - 0.76: Upper & lower swap arrows perform 2 smooth synchronized opposite-direction transfer glides!
    // 0.78 - 1.00: Diamond prism retracts smoothly; Scene 1 Hexagonal Asset Token expands cleanly -> EXACT t = 0.0!

    const introU = easeOutCubic(seg(p, 0.02, 0.18));
    const exitSwapU = easeInCubic(seg(p, 0.79, 0.90));
    const toHexU = easeOutCubic(seg(p, 0.85, 1.00));
    const vis = 1 - exitSwapU;

    drawStageShadow(lerp(1.02, 0.92, toHexU), 1);

    if (vis > 0.005) {
      const sc = lerp(1, 0.62, exitSwapU);
      const curSz = frameSz * sc;

      ctx.save();
      ctx.globalAlpha = vis;

      // 1. Rotated 45-degree Diamond Swap Frame (Matches Scene 3 p = 1.00 EXACTLY!)
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(Math.PI * 0.25);

      roundRectPath(-curSz * 0.5, -curSz * 0.5, curSz, curSz, frameR * sc);
      ctx.fillStyle = COLORS.graphiteCard;
      ctx.fill();

      ctx.save();
      roundRectPath(-curSz * 0.5, -curSz * 0.5, curSz, curSz, frameR * sc);
      ctx.clip();
      ctx.fillStyle = COLORS.graphiteShade;
      ctx.fillRect(0, -curSz * 0.55, curSz * 0.55, curSz * 1.1);

      const sheenP = seg(p, 0.52, 0.72);
      if (sheenP > 0 && sheenP < 1) {
        drawClippedSheen(-curSz * 0.5, -curSz * 0.5, curSz, curSz, sheenP, 0.9);
      }
      ctx.restore();

      // Inner Recessed Dark Diamond Cavity
      if (introU > 0.005) {
        const inSz = curSz * 0.78;
        ctx.save();
        ctx.globalAlpha *= introU;
        roundRectPath(-inSz * 0.5, -inSz * 0.5, inSz, inSz, s * 0.072 * sc);
        ctx.fillStyle = COLORS.graphiteRecess;
        ctx.fill();
        ctx.restore();
      }
      ctx.restore();

      // 2. Twin Parallel Bidirectional Swap Arrows strictly on separated tracks (y = cy +/- 0.115*s -> wide 0.13*s gap!)
      if (introU > 0.01) {
        const glideCycle = Math.sin(seg(p, 0.18, 0.76) * Math.PI * 4);
        const shiftX = glideCycle * s * 0.055;
        const arrW = s * 0.35 * introU * sc;
        const arrThick = s * 0.058 * sc;
        const trackOffY = s * 0.115 * sc;

        // Upper Arrow (Points Right ->)
        drawSwapArrow(cx + shiftX, cy - trackOffY, arrW, arrThick, 1, COLORS.lavender, introU);
        // Lower Arrow (Points Left <-)
        drawSwapArrow(cx - shiftX, cy + trackOffY, arrW, arrThick, -1, COLORS.ultraNeon, introU);
      }

      // 3. Flanking Accent Diamonds strictly outside Left & Right Diamond Tips (cx +/- 0.62*s -> 0.11*s clear gap!)
      const dotVis = easeOutCubic(seg(p, 0.22, 0.34)) * (1 - easeInCubic(seg(p, 0.72, 0.80)));
      if (dotVis > 0.005) {
        const pulse = 0.8 + 0.2 * Math.sin(seg(p, 0.22, 0.76) * Math.PI * 4);
        const dr = s * 0.048 * dotVis * pulse;
        ctx.save();
        ctx.globalAlpha *= dotVis;
        drawDiamond(cx - s * 0.62, cy, dr, dr, COLORS.ultraNeon);
        drawDiamond(cx + s * 0.62, cy, dr, dr, COLORS.lavender);
        ctx.restore();
      }

      ctx.restore();
    }

    // Seamless Loop Return: Scene 1 Hexagonal Asset Token expanding cleanly at center (p = 0.85 -> 1.00) -> EXACT t = 0.0!
    if (toHexU > 0.005) {
      drawHexAssetToken(cx, cy, s * 0.48 * toHexU, 0, 0, 0, toHexU);
    }
  }

  // Render Frame
  ctx.save();
  drawBackground();

  if (currentScene === 0) {
    drawScene1(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3(sceneProgress);
  } else {
    drawScene4(sceneProgress);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide * 0.42;
  const phase = (loopT / duration) * Math.PI * 2;

  const COLORS = {
    bgTop: '#16060C',
    bgMid: '#230A13',
    bgBot: '#310F1B',
    roseGold: '#F4A28C',
    roseShade: '#DF816E',
    roseDeep: '#C46355',
    ivory: '#FFF1E6',
    ivoryShade: '#F2DDD0',
    crimson: '#E11D48',
    crimsonBright: '#FB7185',
    burgundyCard: '#3E1423',
    burgundyShade: '#310F1B',
    burgundyRecess: '#220912',
    stageShadow: 'rgba(12, 3, 7, 0.48)',
    sheen: 'rgba(255, 241, 230, 0.20)',
    ambientMark: '#63273B'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function seg(p, a, b) {
    return clamp01((p - a) / (b - a));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp01(u);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fill) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function drawClippedSheen(x, y, w, h, progress, alpha) {
    if (progress <= 0 || progress >= 1) return;
    const bandW = w * 0.22;
    const travel = w + h * 0.65 + bandW * 2;
    const startX = x - h * 0.35 - bandW + progress * travel;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.beginPath();
    ctx.moveTo(startX, y - h * 0.1);
    ctx.lineTo(startX + bandW, y - h * 0.1);
    ctx.lineTo(startX + bandW - h * 0.45, y + h * 1.1);
    ctx.lineTo(startX - h * 0.45, y + h * 1.1);
    ctx.closePath();
    ctx.fillStyle = COLORS.sheen;
    ctx.fill();
    ctx.restore();
  }

  function drawStageShadow(widthFactor, alpha) {
    if (alpha <= 0.001 || widthFactor <= 0.001) return;
    const sw = s * 0.54 * widthFactor;
    const sh = s * 0.044;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.ellipse(cx, cy + s * 0.68, sw, sh, 0, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.stageShadow;
    ctx.fill();
    ctx.restore();
  }

  // Clean Modern Dark Burgundy Velvet Gradient Background (Zero Glow, Zero Edge Frames, Zero Corner Brackets)
  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, COLORS.bgTop);
    bgGrad.addColorStop(0.5, COLORS.bgMid);
    bgGrad.addColorStop(1, COLORS.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle crisp flat micro-accents strictly in outer margins far from hero icon
    const marks = [
      { nx: 0.10, ny: 0.25, type: 0, sz: 0.011, ph: 0.3, amp: 0.013, op: 0.22 },
      { nx: 0.16, ny: 0.72, type: 1, sz: 0.010, ph: 1.9, amp: 0.012, op: 0.18 },
      { nx: 0.08, ny: 0.54, type: 2, sz: 0.008, ph: 3.4, amp: 0.010, op: 0.16 },
      { nx: 0.20, ny: 0.35, type: 0, sz: 0.008, ph: 4.8, amp: 0.011, op: 0.15 },
      { nx: 0.90, ny: 0.26, type: 1, sz: 0.011, ph: 1.0, amp: 0.013, op: 0.20 },
      { nx: 0.84, ny: 0.74, type: 0, sz: 0.011, ph: 2.7, amp: 0.012, op: 0.22 },
      { nx: 0.92, ny: 0.55, type: 2, sz: 0.008, ph: 4.2, amp: 0.010, op: 0.16 },
      { nx: 0.80, ny: 0.36, type: 1, sz: 0.008, ph: 5.5, amp: 0.011, op: 0.15 }
    ];

    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      const mx = width * m.nx + Math.cos(phase + m.ph) * minSide * (m.amp * 0.45);
      const my = height * m.ny + Math.sin(phase + m.ph) * minSide * m.amp;
      const r = minSide * m.sz;
      const pulse = 0.78 + 0.22 * Math.sin(phase * 2 + m.ph);

      ctx.save();
      ctx.globalAlpha = m.op * pulse;
      ctx.fillStyle = COLORS.ambientMark;
      if (m.type === 0) {
        drawDiamond(mx, my, r, r, COLORS.ambientMark);
      } else if (m.type === 1) {
        roundRectPath(mx - r * 1.4, my - r * 0.4, r * 2.8, r * 0.8, r * 0.4);
        ctx.fill();
      } else {
        ctx.beginPath();
        ctx.arc(mx, my, r * 0.75, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  // Crisp Modern Heraldic Flat Vector Shield Path (Symmetrical, Smooth Curves, Zero Artifacts)
  function shieldPath(x, y, w, h) {
    const hw = w * 0.5;
    const hh = h * 0.5;
    const topY = y - hh;
    const shY = y - hh + h * 0.13;
    const waistY = y + h * 0.06;
    const tipY = y + hh;

    ctx.beginPath();
    ctx.moveTo(x, topY);
    ctx.quadraticCurveTo(x + hw * 0.52, topY + h * 0.03, x + hw, shY);
    ctx.lineTo(x + hw, waistY);
    ctx.bezierCurveTo(x + hw, y + hh * 0.56, x + hw * 0.50, y + hh * 0.84, x, tipY);
    ctx.bezierCurveTo(x - hw * 0.50, y + hh * 0.84, x - hw, y + hh * 0.56, x - hw, waistY);
    ctx.lineTo(x - hw, shY);
    ctx.quadraticCurveTo(x - hw * 0.52, topY + h * 0.03, x, topY);
    ctx.closePath();
  }

  // Shared Risk Monitor Card (Exact Match between Scene 1 Start and Scene 4 End!)
  function drawRiskMonitorCard(cardW, cardH, sweepP, wavePhase, innerVis, alpha) {
    if (alpha <= 0.005 || cardW <= 2 || cardH <= 2) return;
    const rad = s * 0.11;
    const left = cx - cardW * 0.5;
    const top = cy - cardH * 0.5;

    ctx.save();
    ctx.globalAlpha = alpha;

    // Outer Burgundy Card Frame
    roundRectPath(left, top, cardW, cardH, rad);
    ctx.fillStyle = COLORS.burgundyCard;
    ctx.fill();

    // Clipped right shade & crisp top Rose Gold trim
    ctx.save();
    roundRectPath(left, top, cardW, cardH, rad);
    ctx.clip();
    ctx.fillStyle = COLORS.burgundyShade;
    ctx.fillRect(cx, top, cardW * 0.55, cardH);

    ctx.fillStyle = COLORS.roseGold;
    ctx.fillRect(left, top, cardW, s * 0.062);
    ctx.restore();

    // Recessed Chart Window & Active Volatility-to-Stability Wave
    if (innerVis > 0.005) {
      const padX = s * 0.085;
      const winL = left + padX;
      const winT = top + s * 0.125;
      const winW = cardW - padX * 2;
      const winH = cardH - s * 0.21;
      const winCy = winT + winH * 0.52;

      ctx.save();
      ctx.globalAlpha *= innerVis;

      roundRectPath(winL, winT, winW, winH, s * 0.055);
      ctx.fillStyle = COLORS.burgundyRecess;
      ctx.fill();

      // Subtle clean center equilibrium reference line inside window (dashed-free calm hairline)
      ctx.beginPath();
      ctx.moveTo(winL + s * 0.05, winCy);
      ctx.lineTo(winL + winW - s * 0.05, winCy);
      ctx.strokeStyle = 'rgba(244, 162, 140, 0.14)';
      ctx.lineWidth = Math.max(1.5, s * 0.009);
      ctx.stroke();

      // Analytical Volatility Wave damped smoothly behind Rose Gold Sweeper!
      const plotL = winL + s * 0.06;
      const plotW = winW - s * 0.12;
      const sweepX = plotL + plotW * sweepP;
      const steps = 64;

      function evalWaveY(u) {
        // Controlled high-frequency volatility before sweeper vs smooth gently rising stability behind sweeper
        const dampZone = clamp01((sweepP - u) / 0.09);
        const damp = easeInOutCubic(dampZone);
        const volatileVal =
          Math.sin(u * Math.PI * 7.5 + wavePhase) * 0.55 +
          Math.sin(u * Math.PI * 13.0 - wavePhase * 0.6) * 0.35;
        const stableVal = -0.14 * (u - 0.5) * 2.0 + Math.sin(u * Math.PI * 2.0) * 0.05;
        const amp = winH * 0.34;
        return winCy + lerp(volatileVal, stableVal, damp) * amp;
      }

      ctx.save();
      roundRectPath(winL, winT, winW, winH, s * 0.055);
      ctx.clip();

      // Draw Crimson Volatile Segment (right of sweeper)
      if (sweepP < 0.995) {
        ctx.beginPath();
        let started = false;
        for (let i = 0; i <= steps; i++) {
          const u = i / steps;
          if (u < Math.max(0, sweepP - 0.015)) continue;
          const wx = plotL + u * plotW;
          const wy = evalWaveY(u);
          if (!started) { ctx.moveTo(wx, wy); started = true; }
          else ctx.lineTo(wx, wy);
        }
        ctx.strokeStyle = COLORS.crimson;
        ctx.lineWidth = s * 0.032;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.stroke();
      }

      // Draw Stabilized Rose Gold / Ivory Segment (left of sweeper)
      if (sweepP > 0.005) {
        ctx.beginPath();
        for (let i = 0; i <= steps; i++) {
          const u = i / steps;
          if (u > sweepP) break;
          const wx = plotL + u * plotW;
          const wy = evalWaveY(u);
          if (i === 0) ctx.moveTo(wx, wy);
          else ctx.lineTo(wx, wy);
        }
        ctx.lineTo(sweepX, evalWaveY(sweepP));
        ctx.strokeStyle = COLORS.roseGold;
        ctx.lineWidth = s * 0.036;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.stroke();
      }

      // Crisp Stabilization Sweeper Bar (glides cleanly while damping is active)
      if (sweepP > 0.01 && sweepP < 0.99) {
        const barAlpha = clamp01(Math.min(sweepP, 1 - sweepP) * 10);
        ctx.save();
        ctx.globalAlpha *= barAlpha;
        roundRectPath(sweepX - s * 0.016, winT + s * 0.035, s * 0.032, winH - s * 0.07, s * 0.016);
        ctx.fillStyle = COLORS.ivory;
        ctx.fill();
        ctx.restore();
      }

      // Clean Terminal Confirmation Dot once fully stabilized
      if (sweepP >= 0.98) {
        const dotX = plotL + plotW;
        const dotY = evalWaveY(1.0);
        ctx.beginPath();
        ctx.arc(dotX, dotY, s * 0.036, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.ivory;
        ctx.fill();
      }

      ctx.restore();
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 1 (0s - 5s): VOLATILITY DAMPING MONITOR
  // =========================================================================
  function drawScene1(p) {
    // 0.00 - 0.18: Crimson volatility wave breathes dynamically inside Risk Monitor Card
    // 0.18 - 0.66: Warm Ivory Sweeper glides left-to-right, damping volatility smoothly into calm Rose Gold trend
    // 0.66 - 0.80: Stabilized trend holds with crisp terminal dot
    // 0.80 - 1.00: Card retracts smoothly while Scene 2's Split-Tone Protection Shield expands cleanly from center!

    const sweepP = easeInOutCubic(seg(p, 0.18, 0.66));
    const wavePhase = p * Math.PI * 2.4;
    const cardOut = easeInCubic(seg(p, 0.80, 0.91));
    const toShieldU = easeOutCubic(seg(p, 0.86, 1.00));

    drawStageShadow(lerp(1.16, 0.90, toShieldU), 1);

    if (cardOut < 0.995) {
      const sc = lerp(1, 0.68, cardOut);
      drawRiskMonitorCard(
        s * 1.16 * sc,
        s * 0.78 * sc,
        sweepP,
        wavePhase,
        1 - easeInCubic(seg(p, 0.78, 0.86)),
        1 - cardOut
      );
    }

    // Seamless Handoff: Scene 2 Split-Tone Shield Silhouette expanding cleanly at center (p = 0.86 -> 1.00)!
    if (toShieldU > 0.005) {
      const sw = lerp(s * 0.36, s * 0.88, toShieldU);
      const sh = lerp(s * 0.42, s * 1.02, toShieldU);
      ctx.save();
      ctx.globalAlpha = toShieldU;
      drawSplitShieldBase(cx, cy, sw, sh, 1);
      ctx.restore();
    }
  }

  // Shared 2D Split-Tone Vector Shield Base (Scene 1 -> Scene 2 Exact Handoff)
  function drawSplitShieldBase(x, y, w, h, alpha) {
    ctx.save();
    ctx.globalAlpha *= alpha;

    // Left Half: Rose Gold
    shieldPath(x, y, w, h);
    ctx.fillStyle = COLORS.roseGold;
    ctx.fill();

    // Right Half: Copper-Rose Split Tone clipped strictly inside shield
    ctx.save();
    shieldPath(x, y, w, h);
    ctx.clip();
    ctx.fillStyle = COLORS.roseShade;
    ctx.fillRect(x, y - h * 0.55, w * 0.55, h * 1.1);
    ctx.restore();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5s - 10s): SPLIT-TONE VECTOR SHIELD & RISK DEFLECTION
  // =========================================================================
  function drawScene2(p) {
    // 0.00 - 0.16: Recessed burgundy inner shield & Warm Ivory protection crest reveal cleanly
    // 0.18 - 0.74: 3 Crimson risk darts approach from left, stop STRICTLY at outer shield boundary & deflect away!
    // 0.78 - 1.00: Inner crest retracts; shield smoothly transitions into Scene 3 Padlock Body!

    const introU = easeOutCubic(seg(p, 0.02, 0.16));
    const exitShieldU = easeInCubic(seg(p, 0.80, 0.91));
    const toLockU = easeOutCubic(seg(p, 0.86, 1.00));
    const shieldVis = 1 - exitShieldU;

    drawStageShadow(lerp(0.90, 0.92, toLockU), 1);

    // 3 Crimson Risk Darts approaching cleanly from left & deflecting STRICTLY OUTSIDE shield left edge (cx - 0.44*s)!
    const dartTimes = [0.18, 0.36, 0.54];
    const dartYs = [cy - s * 0.20, cy + s * 0.02, cy + s * 0.22];
    let shieldRecoil = 0;

    for (let i = 0; i < 3; i++) {
      const dt = (p - dartTimes[i]) / 0.22;
      if (dt <= 0 || dt >= 1) continue;

      const impactX = cx - s * 0.48; // 0.04*s clear boundary margin outside shield left edge (cx - 0.44*s)!
      const startX = cx - s * 1.02;
      const baseY = dartYs[i];

      if (dt < 0.45) {
        // Smooth clean approach toward shield defense perimeter
        const u = easeOutCubic(dt / 0.45);
        const dx = lerp(startX, impactX, u);
        const alpha = clamp01(u * 2.5);
        drawRiskDart(dx, baseY, 0, alpha);
      } else {
        // Crisp controlled deflection backward/diagonally away from shield (ZERO penetration!)
        const u = easeOutCubic((dt - 0.45) / 0.55);
        const dirY = i === 0 ? -1 : (i === 2 ? 1 : -0.8);
        const dx = impactX - u * s * 0.34;
        const dy = baseY + dirY * u * s * 0.24;
        const rot = Math.PI + dirY * 0.65;
        const alpha = 1 - easeInCubic(u);
        drawRiskDart(dx, dy, rot, alpha);

        // Crisp Warm Ivory deflection diamond spark strictly at boundary gap (impactX + 0.01*s)
        if (u < 0.55) {
          const spA = 1 - u / 0.55;
          const spR = s * 0.055 * (0.5 + 0.7 * u);
          ctx.save();
          ctx.globalAlpha = spA;
          drawDiamond(impactX + s * 0.01, baseY, spR, spR, COLORS.ivory);
          ctx.restore();
        }

        // Subtle elastic shield confirmation pulse (max +2.4%, calm and solid!)
        if (u < 0.6) {
          shieldRecoil = Math.max(shieldRecoil, Math.sin((u / 0.6) * Math.PI) * 0.024);
        }
      }
    }

    // Center Split-Tone Protection Shield
    if (shieldVis > 0.005) {
      const sc = (1 + shieldRecoil) * lerp(1, 0.72, exitShieldU);
      const sw = s * 0.88 * sc;
      const sh = s * 1.02 * sc;

      ctx.save();
      ctx.globalAlpha = shieldVis;

      // Outer Split-Tone Shield (matches Scene 1 p = 1.00 EXACTLY!)
      drawSplitShieldBase(cx, cy, sw, sh, 1);

      // Inner Recessed Burgundy Shield Panel
      if (introU > 0.005) {
        ctx.save();
        ctx.globalAlpha *= introU;
        shieldPath(cx, cy + s * 0.01, sw * 0.74, sh * 0.74);
        ctx.fillStyle = COLORS.burgundyRecess;
        ctx.fill();

        // Crisp Warm Ivory Protection Crest Diamond + Horizontal Bar Core
        const cSz = s * 0.16 * introU * sc;
        drawDiamond(cx, cy - s * 0.02, cSz, cSz * 1.15, COLORS.ivory);
        drawDiamond(cx, cy - s * 0.02, cSz * 0.44, cSz * 0.52, COLORS.roseGold);
        ctx.restore();
      }

      // Clipped diagonal sheen sweep after 3rd deflection
      const sheenP = seg(p, 0.64, 0.80);
      if (sheenP > 0 && sheenP < 1) {
        ctx.save();
        shieldPath(cx, cy, sw, sh);
        ctx.clip();
        drawClippedSheen(cx - sw * 0.5, cy - sh * 0.5, sw, sh, sheenP, 0.9);
        ctx.restore();
      }

      ctx.restore();
    }

    // Seamless Handoff: Scene 3 Padlock Body expanding cleanly at (cx, cy + 0.14*s) (p = 0.86 -> 1.00)!
    if (toLockU > 0.005) {
      const lw = lerp(s * 0.36, s * 0.84, toLockU);
      const lh = lerp(s * 0.30, s * 0.66, toLockU);
      const ly = lerp(cy, cy + s * 0.14, toLockU);
      ctx.save();
      ctx.globalAlpha = toLockU;
      drawPadlockBodyBase(cx, ly, lw, lh, s * 0.11);
      ctx.restore();
    }
  }

  function drawRiskDart(tipX, tipY, rot, alpha) {
    if (alpha <= 0.005) return;
    const len = s * 0.22;
    const headLen = s * 0.085;
    const headHalfW = s * 0.048;
    const shaftH = s * 0.028;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(tipX, tipY);
    ctx.rotate(rot);

    // Shaft cleanly behind arrowhead
    roundRectPath(-len, -shaftH * 0.5, len - headLen * 0.7, shaftH, shaftH * 0.5);
    ctx.fillStyle = COLORS.crimson;
    ctx.fill();

    // Sharp Arrowhead pointing to (0, 0)
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(-headLen, -headHalfW);
    ctx.lineTo(-headLen * 0.72, 0);
    ctx.lineTo(-headLen, headHalfW);
    ctx.closePath();
    ctx.fillStyle = COLORS.crimsonBright;
    ctx.fill();

    ctx.restore();
  }

  function drawPadlockBodyBase(x, y, w, h, rad) {
    const left = x - w * 0.5;
    const top = y - h * 0.5;
    roundRectPath(left, top, w, h, rad);
    ctx.fillStyle = COLORS.roseGold;
    ctx.fill();

    ctx.save();
    roundRectPath(left, top, w, h, rad);
    ctx.clip();
    ctx.fillStyle = COLORS.roseShade;
    ctx.fillRect(x, top, w * 0.55, h);
    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10s - 15s): SECURITY PADLOCK CORE
  // =========================================================================
  function drawScene3(p) {
    const bodyW = s * 0.84;
    const bodyH = s * 0.66;
    const bodyY = cy + s * 0.14;
    const bodyTop = bodyY - bodyH * 0.5;

    // 0.00 - 0.16: Shackle emerges cleanly in ready state; dark center panel & keyhole reveal
    // 0.18 - 0.36: Shackle glides smoothly & firmly downward to lock into padlock body
    // 0.36 - 0.72: 3 horizontal protection level pills light up sequentially below keyhole + sheen sweep
    // 0.78 - 1.00: Padlock retracts smoothly while Scene 4's Top Anchor Ring & Shaft emerge cleanly!

    const introU = easeOutCubic(seg(p, 0.02, 0.16));
    const lockDropU = easeInOutQuart(seg(p, 0.18, 0.36));
    const lockOut = easeInCubic(seg(p, 0.78, 0.90));
    const toAnchorU = easeOutCubic(seg(p, 0.85, 1.00));
    const lockVis = 1 - lockOut;

    drawStageShadow(lerp(0.92, 0.86, toAnchorU), 1);

    if (lockVis > 0.005) {
      const sc = lerp(1, 0.66, lockOut);
      ctx.save();
      ctx.globalAlpha = lockVis;
      ctx.translate(cx, cy);
      ctx.scale(sc, sc);
      ctx.translate(-cx, -cy);

      // 1. Warm Ivory Padlock Shackle (drawn cleanly behind padlock body top edge)
      if (introU > 0.005) {
        const shackleW = s * 0.44;
        const shackleR = shackleW * 0.5;
        const thick = s * 0.088;
        const dropOffset = lerp(s * 0.095, 0, lockDropU);
        const archCy = bodyTop - s * 0.11 - dropOffset + lerp(s * 0.14, 0, introU);

        ctx.save();
        ctx.globalAlpha *= introU;
        ctx.beginPath();
        ctx.moveTo(cx - shackleR, bodyTop + s * 0.06);
        ctx.lineTo(cx - shackleR, archCy);
        ctx.arc(cx, archCy, shackleR, Math.PI, 0, false);
        ctx.lineTo(cx + shackleR, bodyTop + s * 0.06);
        ctx.strokeStyle = COLORS.ivory;
        ctx.lineWidth = thick;
        ctx.lineCap = 'round';
        ctx.stroke();
        ctx.restore();
      }

      // 2. Main Split-Tone Rose Gold Padlock Body (Matches Scene 2 p = 1.00 EXACTLY!)
      drawPadlockBodyBase(cx, bodyY, bodyW, bodyH, s * 0.11);

      // Clipped diagonal sheen across locked body
      const sheenP = seg(p, 0.54, 0.74);
      if (sheenP > 0 && sheenP < 1) {
        ctx.save();
        roundRectPath(cx - bodyW * 0.5, bodyTop, bodyW, bodyH, s * 0.11);
        ctx.clip();
        drawClippedSheen(cx - bodyW * 0.5, bodyTop, bodyW, bodyH, sheenP, 0.9);
        ctx.restore();
      }

      // 3. Recessed Dark Burgundy Center Slot Panel + Keyhole + 3 Protection Pills
      if (introU > 0.005) {
        const panW = s * 0.64;
        const panH = s * 0.46;
        ctx.save();
        ctx.globalAlpha *= introU;

        roundRectPath(cx - panW * 0.5, bodyY - panH * 0.5, panW, panH, s * 0.068);
        ctx.fillStyle = COLORS.burgundyRecess;
        ctx.fill();

        // Crisp Warm Ivory Keyhole centered cleanly in upper half of panel (y = bodyY - 0.07*s)
        const khY = bodyY - s * 0.075;
        const khR = s * 0.064;
        ctx.beginPath();
        ctx.arc(cx, khY, khR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.ivory;
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(cx - khR * 0.45, khY + khR * 0.55);
        ctx.lineTo(cx + khR * 0.45, khY + khR * 0.55);
        ctx.lineTo(cx + khR * 0.68, khY + s * 0.135);
        ctx.lineTo(cx - khR * 0.68, khY + s * 0.135);
        ctx.closePath();
        ctx.fillStyle = COLORS.ivory;
        ctx.fill();

        // 3 Protection Level Pills strictly BELOW keyhole (y = bodyY + 0.145*s -> 0.085*s clear vertical gap!)
        const pillW = s * 0.145;
        const pillH = s * 0.044;
        const pillGap = s * 0.045;
        const pillY = bodyY + s * 0.145;

        for (let k = 0; k < 3; k++) {
          const px = cx + (k - 1) * (pillW + pillGap);
          const lit = easeOutCubic(seg(p, 0.36 + k * 0.09, 0.46 + k * 0.09));
          roundRectPath(px - pillW * 0.5, pillY - pillH * 0.5, pillW, pillH, pillH * 0.5);
          ctx.fillStyle = lit > 0.4 ? (k === 2 ? COLORS.ivory : COLORS.roseGold) : COLORS.burgundyCard;
          ctx.fill();
        }

        ctx.restore();
      }

      ctx.restore();
    }

    // Seamless Handoff: Scene 4 Warm Ivory Top Anchor Ring emerging cleanly at (cx, cy - 0.36*s) (p = 0.85 -> 1.00)!
    if (toAnchorU > 0.005) {
      const ringY = lerp(cy - s * 0.10, cy - s * 0.36, toAnchorU);
      drawAnchorTopRing(cx, ringY, s * 0.115 * toAnchorU, toAnchorU);
    }
  }

  // Shared Anchor Top Ring (Scene 3 -> Scene 4 Exact Handoff)
  function drawAnchorTopRing(x, y, outerR, alpha) {
    if (alpha <= 0.005 || outerR <= 1) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.arc(x, y, outerR, 0, Math.PI * 2);
    ctx.arc(x, y, outerR * 0.48, 0, Math.PI * 2, true);
    ctx.fillStyle = COLORS.ivory;
    ctx.fill();
    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15s - 20s): ANCHORED STABILITY -> SEAMLESS LOOP TO RISK MONITOR
  // =========================================================================
  function drawScene4(p) {
    // 0.00 - 0.22: Anchor shaft, crossbar, curved fluke arc & twin arrowheads build cleanly below top ring
    // 0.22 - 0.74: Calm serene harmonic micro-sway (+/-2.2 deg) + flanking Ivory upward stability chevrons
    // 0.78 - 1.00: Anchor retracts cleanly; Scene 1's Risk Monitor Card expands seamlessly -> EXACT t = 0.0!

    const buildU = easeOutCubic(seg(p, 0.02, 0.24));
    const anchorOut = easeInCubic(seg(p, 0.78, 0.89));
    const toCardU = easeOutCubic(seg(p, 0.85, 1.00));
    const anchorVis = 1 - anchorOut;

    drawStageShadow(lerp(0.86, 1.16, toCardU), 1);

    const ringY = cy - s * 0.36;

    // Gentle dignified harmonic micro-sway around Top Ring Pivot
    let sway = 0;
    if (p > 0.18 && p < 0.78) {
      const swT = seg(p, 0.18, 0.78);
      sway = Math.sin(swT * Math.PI * 2.0) * 0.042 * Math.sin(swT * Math.PI);
    }

    if (anchorVis > 0.005) {
      const sc = lerp(1, 0.62, anchorOut);

      ctx.save();
      ctx.globalAlpha = anchorVis;
      ctx.translate(cx, ringY);
      ctx.rotate(sway);
      ctx.scale(sc, sc);
      ctx.translate(-cx, -ringY);

      // 1. Vertical Stability Pillar Shaft (extends smoothly down from ring bottom)
      const shaftW = s * 0.092;
      const shaftTop = ringY + s * 0.095;
      const shaftBot = lerp(shaftTop, cy + s * 0.42, buildU);
      if (shaftBot > shaftTop + 2) {
        roundRectPath(cx - shaftW * 0.5, shaftTop, shaftW, shaftBot - shaftTop, shaftW * 0.45);
        ctx.fillStyle = COLORS.roseGold;
        ctx.fill();

        // Clean right-half duotone shade on shaft
        ctx.save();
        roundRectPath(cx - shaftW * 0.5, shaftTop, shaftW, shaftBot - shaftTop, shaftW * 0.45);
        ctx.clip();
        ctx.fillStyle = COLORS.roseShade;
        ctx.fillRect(cx, shaftTop, shaftW * 0.6, shaftBot - shaftTop);
        ctx.restore();
      }

      // 2. Horizontal Crossbar (y = cy - 0.12*s -> clear 0.10*s below top ring!)
      const crossIn = easeOutCubic(seg(p, 0.06, 0.22));
      if (crossIn > 0.005) {
        const cw = s * 0.44 * crossIn;
        const ch = s * 0.068;
        const cY = cy - s * 0.12;
        roundRectPath(cx - cw * 0.5, cY - ch * 0.5, cw, ch, ch * 0.5);
        ctx.fillStyle = COLORS.ivory;
        ctx.fill();
      }

      // 3. Symmetrical Curved Anchor Fluke Arc & Twin Fluke Arrowheads
      const arcIn = easeOutCubic(seg(p, 0.10, 0.28));
      if (arcIn > 0.01) {
        const arcCy = cy + s * 0.02;
        const arcR = s * 0.39;
        const halfSweep = (Math.PI * 0.39) * arcIn; // sweeps cleanly up to ~70 deg each side of bottom
        const aStart = Math.PI * 0.5 - halfSweep;
        const aEnd = Math.PI * 0.5 + halfSweep;

        ctx.beginPath();
        ctx.arc(cx, arcCy, arcR, aStart, aEnd, false);
        ctx.strokeStyle = COLORS.roseGold;
        ctx.lineWidth = s * 0.088;
        ctx.lineCap = 'round';
        ctx.stroke();

        // Twin Crisp Triangular Fluke Arrowheads at Left & Right Arc Tips
        const tipScale = easeOutCubic(seg(p, 0.18, 0.32));
        if (tipScale > 0.01) {
          for (let side = -1; side <= 1; side += 2) {
            const ang = Math.PI * 0.5 - side * halfSweep;
            const tx = cx + Math.cos(ang) * arcR;
            const ty = arcCy + Math.sin(ang) * arcR;
            // Tangent direction pointing outward & upward along the fluke tip
            const tangAng = ang - side * (Math.PI * 0.5);
            const flLen = s * 0.145 * tipScale;
            const flHalfW = s * 0.088 * tipScale;

            ctx.save();
            ctx.translate(tx, ty);
            ctx.rotate(tangAng);
            ctx.beginPath();
            ctx.moveTo(flLen * 0.72, 0);
            ctx.lineTo(-flLen * 0.35, -flHalfW);
            ctx.lineTo(-flLen * 0.12, 0);
            ctx.lineTo(-flLen * 0.35, flHalfW);
            ctx.closePath();
            ctx.fillStyle = COLORS.ivory;
            ctx.fill();
            ctx.restore();
          }
        }
      }

      // 4. Top Ring (Continuous from Scene 3 p = 1.00!)
      drawAnchorTopRing(cx, ringY, s * 0.115, 1);

      ctx.restore();
    }

    // Flanking Calm Upward Stability Chevrons strictly in upper outer open air (cx +/- 0.44*s, cy - 0.32*s)
    // Guaranteed wide clearance from top ring (cx +/- 0.115*s) & crossbar (y = cy - 0.12*s)!
    const chIn = easeOutCubic(seg(p, 0.28, 0.42));
    const chOut = easeInCubic(seg(p, 0.72, 0.80));
    const chVis = chIn * (1 - chOut);
    if (chVis > 0.005) {
      const liftY = -Math.sin(seg(p, 0.30, 0.76) * Math.PI * 2) * s * 0.018;
      ctx.save();
      ctx.globalAlpha = chVis;
      for (let side = -1; side <= 1; side += 2) {
        const kx = cx + side * s * 0.44;
        const ky = cy - s * 0.32 + liftY;
        const cSz = s * 0.068;
        ctx.beginPath();
        ctx.moveTo(kx - cSz, ky + cSz * 0.45);
        ctx.lineTo(kx, ky - cSz * 0.45);
        ctx.lineTo(kx + cSz, ky + cSz * 0.45);
        ctx.strokeStyle = COLORS.ivory;
        ctx.lineWidth = s * 0.028;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.stroke();
      }
      ctx.restore();
    }

    // Seamless Loop Return: Scene 1 Risk Monitor Card expanding cleanly at center (p = 0.85 -> 1.00) -> EXACT t = 0.0!
    if (toCardU > 0.005) {
      const curW = lerp(s * 0.48, s * 1.16, toCardU);
      const curH = lerp(s * 0.32, s * 0.78, toCardU);
      const innerIn = easeOutCubic(seg(p, 0.90, 1.00));
      drawRiskMonitorCard(curW, curH, 0, 0, innerIn, toCardU);
    }
  }

  // Render Frame
  ctx.save();
  drawBackground();

  if (currentScene === 0) {
    drawScene1(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3(sceneProgress);
  } else {
    drawScene4(sceneProgress);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide * 0.42;
  const phase = (loopT / duration) * Math.PI * 2;

  const COLORS = {
    bgTop: '#061418',
    bgMid: '#0B232A',
    bgBot: '#10323B',
    turqBright: '#2DD4BF',
    turqMain: '#14B8A6',
    turqDeep: '#0D9488',
    limeVolt: '#A3E635',
    limeDeep: '#84CC16',
    mistWhite: '#F0FDFA',
    mistShade: '#CCFBF1',
    petrolWall: '#144854',
    petrolShade: '#0F3842',
    petrolRecess: '#0A252C',
    stageShadow: 'rgba(3, 12, 15, 0.46)',
    sheen: 'rgba(240, 253, 250, 0.19)',
    ambientMark: '#225966'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function seg(p, a, b) {
    return clamp01((p - a) / (b - a));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp01(u);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function hexPath(x, y, r) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = (i * Math.PI) / 3;
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fill) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function drawClippedSheen(x, y, w, h, progress, alpha) {
    if (progress <= 0 || progress >= 1) return;
    const bandW = w * 0.22;
    const travel = w + h * 0.65 + bandW * 2;
    const startX = x - h * 0.35 - bandW + progress * travel;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.beginPath();
    ctx.moveTo(startX, y - h * 0.1);
    ctx.lineTo(startX + bandW, y - h * 0.1);
    ctx.lineTo(startX + bandW - h * 0.45, y + h * 1.1);
    ctx.lineTo(startX - h * 0.45, y + h * 1.1);
    ctx.closePath();
    ctx.fillStyle = COLORS.sheen;
    ctx.fill();
    ctx.restore();
  }

  function drawStageShadow(widthFactor, alpha) {
    if (alpha <= 0.001 || widthFactor <= 0.001) return;
    const sw = s * 0.56 * widthFactor;
    const sh = s * 0.044;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.ellipse(cx, cy + s * 0.68, sw, sh, 0, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.stageShadow;
    ctx.fill();
    ctx.restore();
  }

  // Clean Modern Dark Slate Petrol Gradient Background (Zero Glow, Zero Edge Frames, Zero Corner Brackets)
  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, COLORS.bgTop);
    bgGrad.addColorStop(0.5, COLORS.bgMid);
    bgGrad.addColorStop(1, COLORS.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle crisp flat architectural micro-accents strictly in outer margins far from hero icon
    const marks = [
      { nx: 0.10, ny: 0.25, type: 0, sz: 0.011, ph: 0.2, amp: 0.013, op: 0.22 },
      { nx: 0.16, ny: 0.72, type: 1, sz: 0.010, ph: 1.8, amp: 0.012, op: 0.18 },
      { nx: 0.08, ny: 0.53, type: 2, sz: 0.008, ph: 3.3, amp: 0.010, op: 0.16 },
      { nx: 0.20, ny: 0.34, type: 0, sz: 0.008, ph: 4.7, amp: 0.011, op: 0.15 },
      { nx: 0.90, ny: 0.27, type: 1, sz: 0.011, ph: 0.9, amp: 0.013, op: 0.20 },
      { nx: 0.84, ny: 0.73, type: 0, sz: 0.011, ph: 2.6, amp: 0.012, op: 0.22 },
      { nx: 0.92, ny: 0.56, type: 2, sz: 0.008, ph: 4.1, amp: 0.010, op: 0.16 },
      { nx: 0.80, ny: 0.36, type: 1, sz: 0.008, ph: 5.4, amp: 0.011, op: 0.15 }
    ];

    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      const mx = width * m.nx + Math.cos(phase + m.ph) * minSide * (m.amp * 0.45);
      const my = height * m.ny + Math.sin(phase + m.ph) * minSide * m.amp;
      const r = minSide * m.sz;
      const pulse = 0.78 + 0.22 * Math.sin(phase * 2 + m.ph);

      ctx.save();
      ctx.globalAlpha = m.op * pulse;
      ctx.fillStyle = COLORS.ambientMark;
      if (m.type === 0) {
        roundRectPath(mx - r, my - r, r * 2, r * 2, r * 0.35);
        ctx.fill();
      } else if (m.type === 1) {
        drawDiamond(mx, my, r, r, COLORS.ambientMark);
      } else {
        roundRectPath(mx - r * 1.5, my - r * 0.32, r * 3.0, r * 0.64, r * 0.32);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  function drawGroundPlinth(x, y, w, h, alpha) {
    if (alpha <= 0.005 || w <= 1) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    roundRectPath(x - w * 0.5, y - h * 0.5, w, h, h * 0.5);
    ctx.fillStyle = COLORS.petrolWall;
    ctx.fill();

    ctx.save();
    roundRectPath(x - w * 0.5, y - h * 0.5, w, h, h * 0.5);
    ctx.clip();
    ctx.fillStyle = COLORS.turqMain;
    ctx.fillRect(x - w * 0.5, y - h * 0.5, w, h * 0.36);
    ctx.restore();
    ctx.restore();
  }

  // Shared 2D Flat Residential Property House (Exact Match between Scene 1 Start and Scene 4 End!)
  function drawResidentialHouse(wallW, wallH, baseY, roofVis, detailsVis, winLights, sheenP) {
    const wallTop = baseY - wallH;
    const wallLeft = cx - wallW * 0.5;
    const rad = s * 0.04;

    // House Wall Body
    roundRectPath(wallLeft, wallTop, wallW, wallH, rad);
    ctx.fillStyle = COLORS.petrolWall;
    ctx.fill();

    // Clipped right-half shade & diagonal sheen
    ctx.save();
    roundRectPath(wallLeft, wallTop, wallW, wallH, rad);
    ctx.clip();
    ctx.fillStyle = COLORS.petrolShade;
    ctx.fillRect(cx, wallTop, wallW * 0.55, wallH);

    if (sheenP > 0 && sheenP < 1) {
      drawClippedSheen(wallLeft, wallTop, wallW, wallH, sheenP, 0.9);
    }
    ctx.restore();

    // Door & Symmetrical Windows (strictly clear of each other & outer walls)
    if (detailsVis > 0.005) {
      ctx.save();
      ctx.globalAlpha = detailsVis;

      // Centered Lime Volt Door
      const doorW = s * 0.18;
      const doorH = s * 0.25;
      const doorTop = baseY - doorH;
      roundRectPath(cx - doorW * 0.5, doorTop, doorW, doorH, s * 0.028);
      ctx.fillStyle = COLORS.limeVolt;
      ctx.fill();

      // Door handle dot
      ctx.beginPath();
      ctx.arc(cx + doorW * 0.24, doorTop + doorH * 0.54, s * 0.017, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.petrolRecess;
      ctx.fill();

      // Left & Right Windows (x = cx +/- 0.24*s, size 0.13*s -> 0.085*s clear gap from door!)
      const winSz = s * 0.13;
      const winY = wallTop + wallH * 0.38;
      for (let i = 0; i < 2; i++) {
        const wx = cx + (i === 0 ? -0.24 : 0.24) * s;
        const lit = winLights[i] || 0;
        roundRectPath(wx - winSz * 0.5, winY - winSz * 0.5, winSz, winSz, s * 0.022);
        ctx.fillStyle = lit > 0.5 ? COLORS.mistWhite : COLORS.petrolRecess;
        ctx.fill();

        if (lit > 0.2) {
          ctx.save();
          ctx.globalAlpha *= clamp01(lit);
          const inSz = winSz * 0.56;
          roundRectPath(wx - inSz * 0.5, winY - inSz * 0.5, inSz, inSz, s * 0.012);
          ctx.fillStyle = COLORS.turqBright;
          ctx.fill();
          ctx.restore();
        }
      }
      ctx.restore();
    }

    // Crisp Pitched Gable Roof strictly capping top of walls
    if (roofVis > 0.005) {
      const roofBaseY = wallTop + s * 0.015;
      const roofApexY = lerp(roofBaseY, wallTop - s * 0.36, roofVis);
      const roofHalfW = lerp(wallW * 0.5, s * 0.48, roofVis);

      ctx.save();
      ctx.globalAlpha = roofVis;

      // Solid Turquoise Roof Triangle
      ctx.beginPath();
      ctx.moveTo(cx, roofApexY);
      ctx.lineTo(cx + roofHalfW, roofBaseY);
      ctx.lineTo(cx - roofHalfW, roofBaseY);
      ctx.closePath();
      ctx.fillStyle = COLORS.turqMain;
      ctx.fill();

      // Right-half roof duotone shade
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(cx, roofApexY);
      ctx.lineTo(cx + roofHalfW, roofBaseY);
      ctx.lineTo(cx - roofHalfW, roofBaseY);
      ctx.closePath();
      ctx.clip();
      ctx.fillStyle = COLORS.turqDeep;
      ctx.fillRect(cx, roofApexY, roofHalfW + 2, roofBaseY - roofApexY + 2);
      ctx.restore();

      // Crisp Mist White Roof Eaves Trim Stroke along top chevron
      ctx.beginPath();
      ctx.moveTo(cx - roofHalfW, roofBaseY);
      ctx.lineTo(cx, roofApexY);
      ctx.lineTo(cx + roofHalfW, roofBaseY);
      ctx.strokeStyle = COLORS.mistWhite;
      ctx.lineWidth = s * 0.044 * roofVis;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.stroke();

      // Centered Attic Diamond Accent inside gable (strictly clear of roof edges)
      const atticLit = winLights[2] || 0;
      const attY = lerp(roofBaseY, roofApexY, 0.38);
      drawDiamond(cx, attY, s * 0.052 * roofVis, s * 0.052 * roofVis, atticLit > 0.5 ? COLORS.limeVolt : COLORS.petrolRecess);

      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 1 (0s - 5s): BLUEPRINT FOUNDATION (RESIDENTIAL PROPERTY)
  // =========================================================================
  function drawScene1(p) {
    const plinthY = cy + s * 0.48;
    const plinthH = s * 0.052;
    const wallBaseY = plinthY - plinthH * 0.5 - s * 0.02;

    // 0.00 - 0.16: Residential house holds crisp and grounded with diagonal sheen
    // 0.16 - 0.72: Windows & attic diamond illuminate in sequence + crisp architectural dimension ticks flanking sides
    // 0.78 - 1.00: Roof & house details retract smoothly; wall rises vertically into Scene 2's Commercial Tower!

    const toTowerU = easeInOutCubic(seg(p, 0.84, 1.00));
    const roofVis = 1 - easeInCubic(seg(p, 0.78, 0.89));
    const detailsVis = 1 - easeInCubic(seg(p, 0.76, 0.86));

    const winLights = [
      easeOutCubic(seg(p, 0.18, 0.30)),
      easeOutCubic(seg(p, 0.32, 0.44)),
      easeOutCubic(seg(p, 0.46, 0.58))
    ];

    const curWallW = lerp(s * 0.78, s * 0.54, toTowerU);
    const curWallH = lerp(s * 0.50, s * 0.86, toTowerU);

    drawStageShadow(1.16, 1);
    drawGroundPlinth(cx, plinthY, s * 1.22, plinthH, 1);

    drawResidentialHouse(
      curWallW, curWallH, wallBaseY,
      roofVis, detailsVis, winLights,
      seg(p, 0.06, 0.28)
    );

    // Subtle crisp architectural height ticks cleanly flanking LEFT & RIGHT of house (wide 0.14*s clearance!)
    const tickIn = easeOutCubic(seg(p, 0.14, 0.28));
    const tickVis = tickIn * (1 - easeInCubic(seg(p, 0.72, 0.80)));
    if (tickVis > 0.005) {
      ctx.save();
      ctx.globalAlpha = tickVis * 0.78;
      for (let side = -1; side <= 1; side += 2) {
        const tx = cx + side * s * 0.62;
        for (let k = 0; k < 3; k++) {
          const ty = wallBaseY - s * (0.10 + k * 0.16);
          const tw = k === 2 ? s * 0.075 : s * 0.048;
          const xStart = side < 0 ? tx - tw : tx;
          roundRectPath(xStart, ty - s * 0.012, tw, s * 0.024, s * 0.012);
          ctx.fillStyle = k === 2 ? COLORS.limeVolt : COLORS.turqMain;
          ctx.fill();
        }
      }
      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 2 (5s - 10s): COMMERCIAL SKYLINE RISE & EQUITY APPRECIATION
  // =========================================================================
  function drawScene2(p) {
    const plinthY = cy + s * 0.48;
    const plinthH = s * 0.052;
    const baseY = plinthY - plinthH * 0.5 - s * 0.02;

    // 0.00 - 0.18: Tower glides cleanly left-of-center, angled roof caps top, side wing rises, appreciation arrow enters right
    // 0.18 - 0.78: 4 floors of windows illuminate bottom-to-top, Lime Volt appreciation arrow glides upward + sheen
    // 0.78 - 1.00: Tower, wing, arrow & plinth retract; centered Turquoise Hexagonal Key Core emerges for Scene 3!

    const introU = easeOutCubic(seg(p, 0.02, 0.20));
    const exitSkyU = easeInCubic(seg(p, 0.79, 0.90));
    const toHexU = easeOutCubic(seg(p, 0.86, 1.00));
    const skyVis = 1 - exitSkyU;

    drawStageShadow(lerp(1.16, 0.66, toHexU), 1);

    // Persistent Ground Plinth from Scene 1 (retracts smoothly before Scene 3)
    if (skyVis > 0.005) {
      drawGroundPlinth(cx, plinthY, s * 1.22 * lerp(0.5, 1, skyVis), plinthH, skyVis);
    }

    if (skyVis > 0.005) {
      // 1. Main Commercial Tower (continuous from Scene 1 p = 1.00 at cx -> glides cleanly to cx - 0.06*s!)
      const towerCx = lerp(cx, cx - s * 0.06, introU);
      const towerW = s * 0.54;
      const towerH = s * 0.86 * lerp(1, 0.45, exitSkyU);
      const tLeft = towerCx - towerW * 0.5;
      const tRight = towerCx + towerW * 0.5;
      const tTopL = baseY - towerH;
      const tTopR = baseY - towerH - s * 0.08 * introU * skyVis;

      ctx.save();
      ctx.globalAlpha = skyVis;

      // Architectural Slanted-Roof Tower Path
      ctx.beginPath();
      ctx.moveTo(tLeft, tTopL);
      ctx.lineTo(tRight, tTopR);
      ctx.lineTo(tRight, baseY);
      ctx.lineTo(tLeft, baseY);
      ctx.closePath();
      ctx.fillStyle = COLORS.petrolWall;
      ctx.fill();

      // Clipped right shade, angled roof cap, & sheen
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(tLeft, tTopL);
      ctx.lineTo(tRight, tTopR);
      ctx.lineTo(tRight, baseY);
      ctx.lineTo(tLeft, baseY);
      ctx.closePath();
      ctx.clip();

      ctx.fillStyle = COLORS.petrolShade;
      ctx.fillRect(towerCx, tTopR - 4, towerW * 0.55, towerH + s * 0.14);

      // Slanted Vivid Turquoise Roof Trim Band
      ctx.beginPath();
      ctx.moveTo(tLeft, tTopL);
      ctx.lineTo(tRight, tTopR);
      ctx.lineTo(tRight, tTopR + s * 0.065 * introU);
      ctx.lineTo(tLeft, tTopL + s * 0.065 * introU);
      ctx.closePath();
      ctx.fillStyle = COLORS.turqMain;
      ctx.fill();

      const sheenP = seg(p, 0.50, 0.72);
      if (sheenP > 0 && sheenP < 1) {
        drawClippedSheen(tLeft, tTopR, towerW, towerH + s * 0.1, sheenP, 0.9);
      }
      ctx.restore();

      // 2x4 Crisp Window Grid strictly inside tower walls (illuminates bottom-to-top!)
      const winVis = introU * skyVis;
      if (winVis > 0.05) {
        const winW = s * 0.145;
        const winH = s * 0.062;
        const gapX = s * 0.068;
        const gapY = s * 0.092;
        const startY = baseY - s * 0.13;

        ctx.save();
        ctx.globalAlpha *= winVis;
        for (let row = 0; row < 4; row++) {
          const wy = startY - row * (winH + gapY);
          const floorLit = easeOutCubic(seg(p, 0.16 + row * 0.09, 0.28 + row * 0.09));
          for (let col = 0; col < 2; col++) {
            const wx = towerCx + (col === 0 ? -(winW + gapX) * 0.5 : (winW + gapX) * 0.5);
            roundRectPath(wx - winW * 0.5, wy - winH * 0.5, winW, winH, s * 0.018);
            ctx.fillStyle = floorLit > 0.45 ? (row === 3 ? COLORS.limeVolt : COLORS.mistWhite) : COLORS.petrolRecess;
            ctx.fill();
          }
        }
        ctx.restore();
      }

      // 2. Left Adjacent Lower Commercial Wing (x = towerLeft - 0.045*s - wingW -> guaranteed 0.045*s clear gap!)
      const wingIn = easeOutCubic(seg(p, 0.08, 0.24));
      const wingVis = wingIn * skyVis;
      if (wingVis > 0.005) {
        const wingW = s * 0.21;
        const wingH = s * 0.44 * wingIn;
        const wingR = tLeft - s * 0.048;
        const wingL = wingR - wingW;

        ctx.save();
        ctx.globalAlpha = wingVis;
        roundRectPath(wingL, baseY - wingH, wingW, wingH, s * 0.025);
        ctx.fillStyle = COLORS.turqDeep;
        ctx.fill();

        // Top wing cap & 2 crisp windows
        ctx.fillStyle = COLORS.turqBright;
        ctx.fillRect(wingL, baseY - wingH, wingW, s * 0.032);
        const mw = s * 0.11;
        const mh = s * 0.048;
        for (let r = 0; r < 2; r++) {
          const my = baseY - s * (0.14 + r * 0.14);
          roundRectPath(wingL + (wingW - mw) * 0.5, my - mh * 0.5, mw, mh, s * 0.014);
          ctx.fillStyle = COLORS.mistShade;
          ctx.fill();
        }
        ctx.restore();
      }

      // 3. Rising Equity Appreciation Arrow strictly in clean open air RIGHT of main tower (0.13*s clear gap!)
      const arrIn = easeOutCubic(seg(p, 0.20, 0.44));
      const arrVis = arrIn * skyVis;
      if (arrVis > 0.005) {
        const arrX = tRight + s * 0.19;
        const arrBot = baseY - s * 0.06;
        const risePulse = Math.sin(seg(p, 0.44, 0.80) * Math.PI * 2) * s * 0.022;
        const arrTop = lerp(arrBot - s * 0.12, baseY - s * 0.72, arrIn) + risePulse;
        const shaftW = s * 0.062;
        const headW = s * 0.17;
        const headH = s * 0.14;

        ctx.save();
        ctx.globalAlpha = arrVis;

        // Vertical Arrow Shaft (stops cleanly at base of arrowhead)
        const shaftTop = arrTop + headH * 0.82;
        if (arrBot > shaftTop) {
          roundRectPath(arrX - shaftW * 0.5, shaftTop, shaftW, arrBot - shaftTop, shaftW * 0.5);
          ctx.fillStyle = COLORS.limeVolt;
          ctx.fill();
        }

        // Sharp Solid Arrowhead
        ctx.beginPath();
        ctx.moveTo(arrX, arrTop);
        ctx.lineTo(arrX + headW * 0.5, arrTop + headH);
        ctx.lineTo(arrX - headW * 0.5, arrTop + headH);
        ctx.closePath();
        ctx.fillStyle = COLORS.limeVolt;
        ctx.fill();

        ctx.restore();
      }

      ctx.restore();
    }

    // Seamless Handoff: Turquoise Hexagonal Key Core emerging cleanly at (cx, cy) (p = 0.86 -> 1.00)!
    if (toHexU > 0.005) {
      drawHexKeyHead(cx, cy, s * 0.25 * toHexU, toHexU);
    }
  }

  // Shared 2D Flat Hexagonal Property Key Head (Scene 2 -> Scene 3 Exact Handoff)
  function drawHexKeyHead(x, y, r, alpha) {
    if (alpha <= 0.005 || r <= 1) return;
    ctx.save();
    ctx.globalAlpha = alpha;

    // Outer Turquoise Hexagon
    hexPath(x, y, r);
    ctx.fillStyle = COLORS.turqMain;
    ctx.fill();

    // Inner Lime Volt Accent Hexagon
    hexPath(x, y, r * 0.68);
    ctx.fillStyle = COLORS.limeVolt;
    ctx.fill();

    // Clean Dark Keyhole Cutout
    ctx.beginPath();
    ctx.arc(x, y, r * 0.34, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.petrolRecess;
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10s - 15s): OWNERSHIP KEY TURN (PRECISION 90-DEGREE LOCK)
  // =========================================================================
  function drawScene3(p) {
    // 0.00 - 0.22: Hexagonal key head shifts cleanly left while sleek shaft & 2 precision teeth extend rightward
    // 0.26 - 0.56: Precision 90-degree clockwise mechanical lock-turn around exact center (cx, cy)
    // 0.54 - 0.78: 4 crisp symmetrical Lime Volt confirmation diamonds illuminate cleanly around locked key
    // 0.78 - 1.00: Key retracts smoothly; Scene 4's Equity Deed Certificate silhouette expands cleanly from center!

    const extendU = easeOutCubic(seg(p, 0.02, 0.22));
    const turnRot = easeInOutQuart(seg(p, 0.26, 0.56)) * (Math.PI * 0.5);
    const keyOut = easeInCubic(seg(p, 0.78, 0.89));
    const toDeedU = easeOutCubic(seg(p, 0.85, 1.00));
    const keyVis = 1 - keyOut;

    drawStageShadow(lerp(0.66, 0.94, Math.max(extendU * keyVis, toDeedU)), 1);

    if (keyVis > 0.005) {
      const headOffset = lerp(0, -s * 0.25, extendU);
      const shaftLen = s * 0.54 * extendU;
      const teethExt = easeOutCubic(seg(p, 0.12, 0.24));
      const keyScale = lerp(1, 0.58, keyOut);

      ctx.save();
      ctx.globalAlpha = keyVis;
      ctx.translate(cx, cy);
      ctx.rotate(turnRot);
      ctx.scale(keyScale, keyScale);

      // Key Shaft (extends cleanly rightward from right edge of hexagonal head)
      if (shaftLen > 2) {
        const shThick = s * 0.098;
        const shLeft = headOffset + s * 0.18;
        roundRectPath(shLeft, -shThick * 0.5, shaftLen, shThick, shThick * 0.45);
        ctx.fillStyle = COLORS.mistWhite;
        ctx.fill();

        // Crisp 2D bottom-half shade along shaft
        ctx.save();
        roundRectPath(shLeft, -shThick * 0.5, shaftLen, shThick, shThick * 0.45);
        ctx.clip();
        ctx.fillStyle = COLORS.turqBright;
        ctx.fillRect(shLeft, 0, shaftLen, shThick * 0.6);
        ctx.restore();

        // 2 Precision Key Teeth cleanly below shaft (clear 0.06*s gap between teeth!)
        if (teethExt > 0.01) {
          const toothW = s * 0.078;
          const t1X = shLeft + shaftLen - s * 0.24;
          const t2X = shLeft + shaftLen - s * 0.10;
          const t1H = s * 0.115 * teethExt;
          const t2H = s * 0.165 * teethExt;

          roundRectPath(t1X - toothW * 0.5, shThick * 0.35, toothW, t1H, s * 0.022);
          ctx.fillStyle = COLORS.turqMain;
          ctx.fill();

          roundRectPath(t2X - toothW * 0.5, shThick * 0.35, toothW, t2H, s * 0.022);
          ctx.fillStyle = COLORS.limeVolt;
          ctx.fill();
        }
      }

      // Hexagonal Key Head (drawn on top of shaft junction for crisp silhouette)
      drawHexKeyHead(headOffset, 0, s * 0.25, 1);

      ctx.restore();
    }

    // 4 Symmetrical Lock Confirmation Diamonds strictly in outer clear air (at +/-0.44*s, +/-0.24*s -> zero overlap!)
    const sparkIn = easeOutCubic(seg(p, 0.55, 0.66));
    const sparkOut = easeInCubic(seg(p, 0.74, 0.82));
    const sparkVis = sparkIn * (1 - sparkOut);
    if (sparkVis > 0.005) {
      const pts = [
        { dx: -0.42, dy: -0.22 },
        { dx: 0.42, dy: -0.22 },
        { dx: -0.42, dy: 0.22 },
        { dx: 0.42, dy: 0.22 }
      ];
      const push = lerp(0.84, 1.04, sparkIn);
      const dr = s * 0.048 * sparkVis;
      ctx.save();
      ctx.globalAlpha = sparkVis;
      for (let i = 0; i < pts.length; i++) {
        drawDiamond(cx + pts[i].dx * s * push, cy + pts[i].dy * s * push, dr, dr, i % 2 === 0 ? COLORS.limeVolt : COLORS.mistWhite);
      }
      ctx.restore();
    }

    // Seamless Handoff: Scene 4 Deed Certificate Silhouette expanding cleanly from center (p = 0.85 -> 1.00)!
    if (toDeedU > 0.005) {
      const dw = lerp(s * 0.36, s * 0.86, toDeedU);
      const dh = lerp(s * 0.44, s * 1.02, toDeedU);
      ctx.save();
      ctx.globalAlpha = toDeedU;
      roundRectPath(cx - dw * 0.5, cy - dh * 0.5, dw, dh, s * 0.10);
      ctx.fillStyle = COLORS.petrolWall;
      ctx.fill();
      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 4 (15s - 20s): EQUITY DEED CERTIFICATE -> SEAMLESS LOOP TO HOUSE
  // =========================================================================
  function drawScene4(p) {
    const deedW = s * 0.86;
    const deedH = s * 1.02;
    const deedR = s * 0.10;
    const plinthY = cy + s * 0.48;
    const plinthH = s * 0.052;
    const wallBaseY = plinthY - plinthH * 0.5 - s * 0.02;

    // 0.00 - 0.16: Deed header strip, duotone shade, clause bars & lower section reveal cleanly
    // 0.12 - 0.56: Clause bars fill left-to-right, mini equity bars grow, Lime Volt hexagonal seal stamps cleanly
    // 0.56 - 0.76: Clipped diagonal sheen sweep across deed
    // 0.78 - 1.00: Deed contents retract; body reshapes smoothly into EXACT Scene 1 Residential House + Plinth!

    const introU = easeOutCubic(seg(p, 0.02, 0.18));
    const contentOut = easeInCubic(seg(p, 0.76, 0.86));
    const toHouseU = easeInOutCubic(seg(p, 0.84, 1.00));
    const cVis = introU * (1 - contentOut);

    drawStageShadow(lerp(0.94, 1.16, toHouseU), 1);

    if (toHouseU <= 0.001) {
      const left = cx - deedW * 0.5;
      const top = cy - deedH * 0.5;

      // Base Deed Document Card (Matches Scene 3 p = 1.00 EXACTLY!)
      roundRectPath(left, top, deedW, deedH, deedR);
      ctx.fillStyle = COLORS.petrolWall;
      ctx.fill();

      // Clipped Interior Trim, Right-Half Shade & Diagonal Sheen
      ctx.save();
      roundRectPath(left, top, deedW, deedH, deedR);
      ctx.clip();

      ctx.globalAlpha = introU;
      ctx.fillStyle = COLORS.petrolShade;
      ctx.fillRect(cx, top, deedW * 0.55, deedH);

      // Crisp Top Vivid Turquoise Header Strip
      ctx.fillStyle = COLORS.turqMain;
      ctx.fillRect(left, top, deedW, s * 0.085 * introU);
      ctx.globalAlpha = 1;

      const sheenP = seg(p, 0.56, 0.75);
      if (sheenP > 0 && sheenP < 1) {
        drawClippedSheen(left, top, deedW, deedH, sheenP, 0.9);
      }
      ctx.restore();

      // Interior Structured Grid (Generous margins & clear separation between upper clauses & lower seal!)
      if (cVis > 0.005) {
        ctx.save();
        ctx.globalAlpha = cVis;

        // Upper Section: 3 Clean Horizontal Deed Clause Bars (y: cy - 0.30*s, -0.17*s, -0.04*s)
        const barLeft = cx - s * 0.31;
        const maxW = s * 0.62;
        const barH = s * 0.058;
        const widths = [1.0, 0.78, 0.88];

        for (let i = 0; i < 3; i++) {
          const by = cy - s * 0.28 + i * s * 0.125;
          const bIn = easeOutCubic(seg(p, 0.10 + i * 0.07, 0.30 + i * 0.07));
          roundRectPath(barLeft, by - barH * 0.5, maxW, barH, barH * 0.5);
          ctx.fillStyle = COLORS.petrolRecess;
          ctx.fill();

          const curW = maxW * widths[i] * bIn;
          if (curW > barH * 0.5) {
            roundRectPath(barLeft, by - barH * 0.5, curW, barH, barH * 0.5);
            ctx.fillStyle = i === 0 ? COLORS.mistWhite : COLORS.turqBright;
            ctx.fill();
          }
        }

        // Lower-Left Mini Equity Bars (x: cx - 0.31*s to cx - 0.07*s, y center cy + 0.24*s)
        const eqBaseY = cy + s * 0.35;
        const eqBarW = s * 0.068;
        const eqGap = s * 0.032;
        const eqHs = [0.10, 0.16, 0.23];
        for (let b = 0; b < 3; b++) {
          const bx = barLeft + b * (eqBarW + eqGap);
          const bGrow = easeOutCubic(seg(p, 0.22 + b * 0.06, 0.42 + b * 0.06));
          const bh = eqHs[b] * s * bGrow;
          if (bh > 2) {
            roundRectPath(bx, eqBaseY - bh, eqBarW, bh, s * 0.018);
            ctx.fillStyle = b === 2 ? COLORS.limeVolt : COLORS.turqMain;
            ctx.fill();
          }
        }

        // Lower-Right Hexagonal Rising-Chevron Property Seal (center: cx + 0.17*s, cy + 0.23*s, r = 0.145*s)
        // Left edge = cx + 0.025*s -> wide 0.09*s clear gap from mini equity bars right edge (cx - 0.042*s)!
        const sealIn = easeOutCubic(seg(p, 0.26, 0.44));
        const sealCx = cx + s * 0.17;
        const sealCy = cy + s * 0.23;
        const sealR = s * 0.145 * sealIn;
        if (sealR > 1) {
          hexPath(sealCx, sealCy, sealR);
          ctx.fillStyle = COLORS.limeVolt;
          ctx.fill();

          // Crisp Upward Equity Chevron cleanly centered inside hexagonal seal
          const chevIn = easeOutCubic(seg(p, 0.36, 0.52));
          const liftY = lerp(s * 0.03, 0, chevIn);
          ctx.beginPath();
          ctx.moveTo(sealCx - sealR * 0.36, sealCy + sealR * 0.16 + liftY);
          ctx.lineTo(sealCx, sealCy - sealR * 0.22 + liftY);
          ctx.lineTo(sealCx + sealR * 0.36, sealCy + sealR * 0.16 + liftY);
          ctx.strokeStyle = COLORS.petrolRecess;
          ctx.lineWidth = sealR * 0.22;
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';
          ctx.stroke();
        }

        ctx.restore();
      }
    } else {
      // Seamless Loop Return -> EXACT Scene 1 Residential House + Ground Plinth at p = 1.00!
      const curWallW = lerp(deedW, s * 0.78, toHouseU);
      const curWallH = lerp(deedH, s * 0.50, toHouseU);
      const curBaseY = lerp(cy + deedH * 0.5, wallBaseY, toHouseU);
      const plinthIn = easeOutCubic(seg(p, 0.86, 1.00));
      const roofIn = easeOutCubic(seg(p, 0.88, 1.00));
      const detailsIn = easeOutCubic(seg(p, 0.90, 1.00));

      if (plinthIn > 0.005) {
        drawGroundPlinth(cx, plinthY, s * 1.22 * plinthIn, plinthH, plinthIn);
      }

      drawResidentialHouse(
        curWallW, curWallH, curBaseY,
        roofIn, detailsIn, [0, 0, 0], 0
      );
    }
  }

  // Render Frame
  ctx.save();
  drawBackground();

  if (currentScene === 0) {
    drawScene1(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3(sceneProgress);
  } else {
    drawScene4(sceneProgress);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide * 0.42;
  const phase = (loopT / duration) * Math.PI * 2;

  const COLORS = {
    bgTop: '#140818',
    bgMid: '#200D28',
    bgBot: '#2C1236',
    coral: '#FB7185',
    coralDeep: '#F43F5E',
    magenta: '#EC4899',
    magentaDeep: '#BE185D',
    peach: '#FDBA74',
    peachLight: '#FED7AA',
    plumCard: '#361742',
    plumShade: '#2B1136',
    plumTile: '#4A215A',
    plumRecess: '#230D2C',
    stageShadow: 'rgba(10, 3, 14, 0.48)',
    sheen: 'rgba(255, 240, 246, 0.19)',
    ambientMark: '#5A2C64'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function seg(p, a, b) {
    return clamp01((p - a) / (b - a));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp01(u);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fill) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function drawClippedSheen(x, y, w, h, progress, alpha) {
    if (progress <= 0 || progress >= 1) return;
    const bandW = w * 0.22;
    const travel = w + h * 0.65 + bandW * 2;
    const startX = x - h * 0.35 - bandW + progress * travel;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.beginPath();
    ctx.moveTo(startX, y - h * 0.1);
    ctx.lineTo(startX + bandW, y - h * 0.1);
    ctx.lineTo(startX + bandW - h * 0.45, y + h * 1.1);
    ctx.lineTo(startX - h * 0.45, y + h * 1.1);
    ctx.closePath();
    ctx.fillStyle = COLORS.sheen;
    ctx.fill();
    ctx.restore();
  }

  function drawStageShadow(widthFactor, alpha) {
    if (alpha <= 0.001 || widthFactor <= 0.001) return;
    const sw = s * 0.54 * widthFactor;
    const sh = s * 0.044;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.ellipse(cx, cy + s * 0.68, sw, sh, 0, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.stageShadow;
    ctx.fill();
    ctx.restore();
  }

  // Clean Modern Dark Plum Noir Gradient Background (Zero Glow, Zero Edge Frames, Zero Corner Brackets)
  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, COLORS.bgTop);
    bgGrad.addColorStop(0.5, COLORS.bgMid);
    bgGrad.addColorStop(1, COLORS.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle crisp flat vector micro-accents strictly in outer margins far from hero icon
    const marks = [
      { nx: 0.10, ny: 0.26, type: 0, sz: 0.011, ph: 0.4, amp: 0.013, op: 0.22 },
      { nx: 0.16, ny: 0.72, type: 1, sz: 0.010, ph: 2.0, amp: 0.012, op: 0.18 },
      { nx: 0.08, ny: 0.53, type: 2, sz: 0.008, ph: 3.5, amp: 0.010, op: 0.16 },
      { nx: 0.20, ny: 0.34, type: 0, sz: 0.008, ph: 4.9, amp: 0.011, op: 0.16 },
      { nx: 0.90, ny: 0.27, type: 1, sz: 0.011, ph: 1.0, amp: 0.013, op: 0.20 },
      { nx: 0.84, ny: 0.73, type: 0, sz: 0.011, ph: 2.8, amp: 0.012, op: 0.22 },
      { nx: 0.92, ny: 0.55, type: 2, sz: 0.008, ph: 4.3, amp: 0.010, op: 0.16 },
      { nx: 0.80, ny: 0.36, type: 1, sz: 0.008, ph: 5.6, amp: 0.011, op: 0.15 }
    ];

    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      const mx = width * m.nx + Math.cos(phase + m.ph) * minSide * (m.amp * 0.45);
      const my = height * m.ny + Math.sin(phase + m.ph) * minSide * m.amp;
      const r = minSide * m.sz;
      const pulse = 0.78 + 0.22 * Math.sin(phase * 2 + m.ph);

      ctx.save();
      ctx.globalAlpha = m.op * pulse;
      ctx.fillStyle = COLORS.ambientMark;
      if (m.type === 0) {
        roundRectPath(mx - r * 1.4, my - r * 0.45, r * 2.8, r * 0.9, r * 0.45);
        ctx.fill();
      } else if (m.type === 1) {
        drawDiamond(mx, my, r, r, COLORS.ambientMark);
      } else {
        ctx.beginPath();
        ctx.arc(mx, my, r * 0.78, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  // Shared 2D Flat Dividend Calendar Body (Exact Match between Scene 1 Start and Scene 4 End!)
  function drawCalendarBase(calW, calH, calY, calR, headerVis, ringExt, gridVis, tileStates, gridScaleY, sheenP) {
    const left = cx - calW * 0.5;
    const top = calY - calH * 0.5;
    const headerH = calH * 0.26;

    // Main Card Body
    roundRectPath(left, top, calW, calH, calR);
    ctx.fillStyle = COLORS.plumCard;
    ctx.fill();

    // Clipped Interior (Duotone Right Shade, Coral Header, Diagonal Sheen)
    ctx.save();
    roundRectPath(left, top, calW, calH, calR);
    ctx.clip();

    // Right-half subtle flat shade
    ctx.fillStyle = COLORS.plumShade;
    ctx.fillRect(cx, top, calW * 0.52, calH);

    // Coral Rose Calendar Header Bar
    if (headerVis > 0.005) {
      ctx.save();
      ctx.globalAlpha = headerVis;
      ctx.fillStyle = COLORS.coral;
      ctx.fillRect(left, top, calW, headerH);
      ctx.fillStyle = COLORS.coralDeep;
      ctx.fillRect(cx, top, calW * 0.52, headerH);
      ctx.restore();
    }

    if (sheenP > 0 && sheenP < 1) {
      drawClippedSheen(left, top, calW, calH, sheenP, 0.9);
    }
    ctx.restore();

    // 2 Soft Peach Binder Rings cleanly straddling top edge (x = cx +/- 0.25*s)
    if (ringExt > 0.01) {
      const rW = s * 0.074;
      const rH = s * 0.165 * ringExt;
      const rRad = rW * 0.5;
      for (let side = -1; side <= 1; side += 2) {
        const rx = cx + side * s * 0.25;
        const ry = top - rH * 0.42;
        roundRectPath(rx - rW * 0.5, ry, rW, rH, rRad);
        ctx.fillStyle = COLORS.peach;
        ctx.fill();
      }
    }

    // Clean 3x2 Date Tile Grid strictly inside body below header (generous 0.11*s side margins & 0.065*s gaps!)
    if (gridVis > 0.005) {
      const bodyTop = top + headerH;
      const bodyH = calH - headerH;
      const bodyCy = bodyTop + bodyH * 0.5;
      const tileW = s * 0.21;
      const tileH = s * 0.175;
      const gapX = s * 0.068;
      const gapY = s * 0.072;

      ctx.save();
      ctx.globalAlpha = gridVis;
      ctx.translate(cx, bodyCy);
      ctx.scale(1, gridScaleY);
      ctx.translate(-cx, -bodyCy);

      for (let r = 0; r < 2; r++) {
        for (let c = 0; c < 3; c++) {
          const idx = r * 3 + c;
          const tx = cx + (c - 1) * (tileW + gapX);
          const ty = bodyCy + (r - 0.5) * (tileH + gapY);
          const active = tileStates[idx] || 0;

          // Tile Background
          roundRectPath(tx - tileW * 0.5, ty - tileH * 0.5, tileW, tileH, s * 0.036);
          if (active > 0.5) {
            ctx.fillStyle = idx === 5 ? COLORS.peach : COLORS.coral;
          } else {
            ctx.fillStyle = COLORS.plumTile;
          }
          ctx.fill();

          // Crisp centered dividend payout dot inside active date tiles
          if (active > 0.05) {
            const dotR = s * 0.032 * clamp01(active);
            ctx.beginPath();
            ctx.arc(tx, ty, dotR, 0, Math.PI * 2);
            ctx.fillStyle = idx === 5 ? COLORS.plumRecess : COLORS.peachLight;
            ctx.fill();
          }
        }
      }
      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 1 (0s - 5s): PAYOUT SCHEDULE (DIVIDEND CALENDAR)
  // =========================================================================
  function drawScene1(p) {
    // 0.00 - 0.16: Calendar holds clean & steady with header sheen
    // 0.14 - 0.66: Periodic payout dates (tiles 0, 2, 4, 5) illuminate smoothly in rhythmic cadence + gentle grid refresh
    // 0.78 - 1.00: Rings & date grid retract cleanly; body reshapes smoothly into Scene 2 Ticket silhouette!

    const toTicketU = easeInOutCubic(seg(p, 0.84, 1.00));
    const headerVis = 1 - easeInCubic(seg(p, 0.82, 0.94));
    const ringExt = 1 - easeInOutCubic(seg(p, 0.78, 0.89));
    const gridVis = 1 - easeInCubic(seg(p, 0.78, 0.87));

    // Smooth controlled vertical sheet-refresh micro-compression on inner grid only (0.48 - 0.62)
    let gridScaleY = 1;
    if (p > 0.48 && p < 0.64) {
      const f = seg(p, 0.48, 0.64);
      gridScaleY = 1 - Math.sin(f * Math.PI) * 0.14;
    }

    // Sequenced payout tile highlights (clean rhythmic dividend calendar beats)
    const tileStates = [
      easeOutCubic(seg(p, 0.14, 0.24)),
      0,
      easeOutCubic(seg(p, 0.28, 0.38)),
      0,
      easeOutCubic(seg(p, 0.56, 0.66)),
      easeOutCubic(seg(p, 0.64, 0.74))
    ];

    const curW = lerp(s * 1.00, s * 1.24, toTicketU);
    const curH = lerp(s * 0.88, s * 0.64, toTicketU);
    const curY = lerp(cy + s * 0.04, cy, toTicketU);
    const curR = lerp(s * 0.12, s * 0.09, toTicketU);

    drawStageShadow(lerp(1.04, 1.22, toTicketU), 1);

    drawCalendarBase(
      curW, curH, curY, curR,
      headerVis, ringExt, gridVis,
      tileStates, gridScaleY,
      seg(p, 0.05, 0.25)
    );
  }

  // True Vector Path for Coupon Ticket with Clean Transparent Semicircular Left & Right Notches
  function ticketNotchPath(x, y, w, h, r, notchR) {
    const left = x - w * 0.5;
    const right = x + w * 0.5;
    const top = y - h * 0.5;
    const bot = y + h * 0.5;
    const rad = Math.min(r, w * 0.2, h * 0.2);

    ctx.beginPath();
    ctx.moveTo(left + rad, top);
    ctx.lineTo(right - rad, top);
    ctx.arcTo(right, top, right, top + rad, rad);

    // Right edge with inward semicircular cutout
    if (notchR > 0.5) {
      ctx.lineTo(right, y - notchR);
      ctx.arc(right, y, notchR, -Math.PI * 0.5, Math.PI * 0.5, true);
    }
    ctx.lineTo(right, bot - rad);
    ctx.arcTo(right, bot, right - rad, bot, rad);
    ctx.lineTo(left + rad, bot);
    ctx.arcTo(left, bot, left, bot - rad, rad);

    // Left edge with inward semicircular cutout
    if (notchR > 0.5) {
      ctx.lineTo(left, y + notchR);
      ctx.arc(left, y, notchR, Math.PI * 0.5, -Math.PI * 0.5, true);
    }
    ctx.lineTo(left, top + rad);
    ctx.arcTo(left, top, left + rad, top, rad);
    ctx.closePath();
  }

  // Helper: Crisp Right-Pointing Chevron Arrow
  function drawChevron(x, y, size, thick, fill) {
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(x - size * 0.45, y - size * 0.65);
    ctx.lineTo(x + size * 0.45, y);
    ctx.lineTo(x - size * 0.45, y + size * 0.65);
    ctx.strokeStyle = fill;
    ctx.lineWidth = thick;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  // Shared 2D Flat Geometric Cashflow Funnel (Scene 2 -> Scene 3 Exact Handoff)
  function drawCashflowFunnel(topY, botY, topW, neckW, rimAlpha, alpha) {
    if (alpha <= 0.005) return;
    const rimH = s * 0.062;
    const nozzleH = s * 0.062;
    const coneTop = topY + rimH * 0.45;
    const coneBot = botY - nozzleH;

    ctx.save();
    ctx.globalAlpha = alpha;

    // Main Symmetrical Trapezoid Funnel Body
    ctx.beginPath();
    ctx.moveTo(cx - topW * 0.5, coneTop);
    ctx.lineTo(cx + topW * 0.5, coneTop);
    ctx.lineTo(cx + neckW * 0.5, coneBot);
    ctx.lineTo(cx - neckW * 0.5, coneBot);
    ctx.closePath();
    ctx.fillStyle = COLORS.coral;
    ctx.fill();

    // Crisp right-half flat shade clipped inside funnel cone
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(cx - topW * 0.5, coneTop);
    ctx.lineTo(cx + topW * 0.5, coneTop);
    ctx.lineTo(cx + neckW * 0.5, coneBot);
    ctx.lineTo(cx - neckW * 0.5, coneBot);
    ctx.closePath();
    ctx.clip();
    ctx.fillStyle = COLORS.coralDeep;
    ctx.fillRect(cx, coneTop, topW * 0.55, coneBot - coneTop + 2);
    ctx.restore();

    // Bottom Nozzle Spout
    roundRectPath(cx - neckW * 0.5, coneBot - s * 0.01, neckW, nozzleH + s * 0.01, s * 0.022);
    ctx.fillStyle = COLORS.magenta;
    ctx.fill();

    // Clean Top Soft Peach Rim Cap
    if (rimAlpha > 0.005) {
      const rimW = topW + s * 0.09;
      ctx.save();
      ctx.globalAlpha *= rimAlpha;
      roundRectPath(cx - rimW * 0.5, topY - rimH * 0.5, rimW, rimH, rimH * 0.5);
      ctx.fillStyle = COLORS.peach;
      ctx.fill();
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5s - 10s): YIELD COUPON TICKET
  // =========================================================================
  function drawScene2(p) {
    // 0.00 - 0.16: Side notches carve smoothly, magenta stub, perforation dots & coupon bars reveal cleanly
    // 0.16 - 0.80: 3 yield bars fill left-to-right, diamond emblem rotates 90 deg, top chevrons glide in rhythm + sheen
    // 0.80 - 1.00: Ticket retracts smoothly while Scene 3's upper Cashflow Funnel emerges cleanly in position!

    const introU = easeOutCubic(seg(p, 0.02, 0.18));
    const exitTicketU = easeInCubic(seg(p, 0.80, 0.91));
    const toFunnelU = easeInOutCubic(seg(p, 0.84, 1.00));
    const ticketVis = 1 - exitTicketU;

    const tw = s * 1.24;
    const th = s * 0.64;
    const notchR = s * 0.082 * introU * ticketVis;

    drawStageShadow(lerp(1.22, 0.96, toFunnelU), 1);

    if (ticketVis > 0.005) {
      const curY = lerp(cy, cy - s * 0.14, exitTicketU);
      const curScale = lerp(1, 0.82, exitTicketU);

      ctx.save();
      ctx.globalAlpha = ticketVis;
      ctx.translate(cx, curY);
      ctx.scale(curScale, curScale);
      ctx.translate(-cx, -curY);

      // Base Ticket Silhouette with True Transparent Notches
      ticketNotchPath(cx, curY, tw, th, s * 0.09, notchR);
      ctx.fillStyle = COLORS.plumCard;
      ctx.fill();

      // Clipped Interior Layout (Left Magenta Stub + Right Main Panel + Sheen)
      ctx.save();
      ticketNotchPath(cx, curY, tw, th, s * 0.09, notchR);
      ctx.clip();

      const perfX = cx - s * 0.16;

      // Right Panel subtle shade (aligns seamlessly with Scene 1 right-half shade at p = 0)
      ctx.fillStyle = COLORS.plumShade;
      ctx.fillRect(lerp(cx, cx + s * 0.12, introU), curY - th * 0.55, tw * 0.55, th * 1.1);

      // Left Magenta Stub (slides cleanly in from left over introU)
      const stubW = (perfX - (cx - tw * 0.5)) * introU;
      ctx.fillStyle = COLORS.magenta;
      ctx.fillRect(cx - tw * 0.5, curY - th * 0.55, stubW, th * 1.1);

      // Bottom subtle trim on left stub
      ctx.fillStyle = COLORS.magentaDeep;
      ctx.fillRect(cx - tw * 0.5, curY + th * 0.24, stubW, th * 0.35);

      // Clipped diagonal sheen sweep
      const sheenP = seg(p, 0.50, 0.72);
      if (sheenP > 0 && sheenP < 1) {
        drawClippedSheen(cx - tw * 0.5, curY - th * 0.5, tw, th, sheenP, 0.92);
      }
      ctx.restore();

      // Left Stub Diamond Seal Emblem (centered at cx - 0.38*s -> wide clearance from notch & perf line!)
      const sealX = cx - s * 0.38;
      const sealRot = easeInOutCubic(seg(p, 0.22, 0.72)) * Math.PI * 0.5;
      if (introU > 0.05) {
        ctx.save();
        ctx.globalAlpha *= introU;
        ctx.translate(sealX, curY);
        ctx.rotate(sealRot);
        drawDiamond(0, 0, s * 0.115 * introU, s * 0.115 * introU, COLORS.peach);
        drawDiamond(0, 0, s * 0.052 * introU, s * 0.052 * introU, COLORS.plumRecess);
        ctx.restore();
      }

      // Vertical Perforation Dots at perfX = cx - 0.16*s (5 evenly spaced dots strictly inside ticket)
      if (introU > 0.05) {
        ctx.save();
        ctx.globalAlpha *= introU;
        for (let d = -2; d <= 2; d++) {
          ctx.beginPath();
          ctx.arc(perfX, curY + d * s * 0.105, s * 0.018, 0, Math.PI * 2);
          ctx.fillStyle = COLORS.bgMid;
          ctx.fill();
        }
        ctx.restore();
      }

      // Right Main Panel: 3 Crisp Horizontal Dividend Yield Bars (strictly clear of perf line & right notch!)
      // X span: cx - 0.05*s to cx + 0.45*s (left gap 0.11*s from perfX, right gap 0.09*s from right notch!)
      if (introU > 0.005) {
        const barLeft = cx - s * 0.05;
        const maxBarW = s * 0.48;
        const barH = s * 0.072;
        const barGap = s * 0.072;
        const ratios = [0.96, 0.78, 0.62];
        const barFills = [COLORS.peach, COLORS.coral, COLORS.magenta];

        ctx.save();
        ctx.globalAlpha *= introU;
        for (let b = 0; b < 3; b++) {
          const by = curY + (b - 1) * (barH + barGap);
          const bFill = easeOutCubic(seg(p, 0.14 + b * 0.08, 0.40 + b * 0.08));
          const liveWave = 1 + 0.03 * Math.sin(seg(p, 0.42, 0.80) * Math.PI * 2 - b * 0.8);

          // Clean recessed track
          roundRectPath(barLeft, by - barH * 0.5, maxBarW, barH, barH * 0.5);
          ctx.fillStyle = COLORS.plumRecess;
          ctx.fill();

          // Crisp colored fill bar
          const curW = Math.min(maxBarW, maxBarW * ratios[b] * bFill * liveWave);
          if (curW > barH * 0.5) {
            roundRectPath(barLeft, by - barH * 0.5, curW, barH, barH * 0.5);
            ctx.fillStyle = barFills[b];
            ctx.fill();
          }
        }
        ctx.restore();
      }

      ctx.restore();
    }

    // 3 Kinetic Yield Flow Chevrons strictly ABOVE ticket (y = cy - 0.47*s -> 0.15*s clear vertical gap!)
    const chevIn = easeOutCubic(seg(p, 0.18, 0.30));
    const chevOut = easeInCubic(seg(p, 0.74, 0.82));
    const chevVis = chevIn * (1 - chevOut);
    if (chevVis > 0.005) {
      const chevY = cy - s * 0.47;
      const shiftX = (seg(p, 0.18, 0.82) - 0.5) * s * 0.16;
      for (let k = 0; k < 3; k++) {
        const kx = cx + (k - 1) * s * 0.18 + shiftX;
        const waveA = 0.45 + 0.55 * (0.5 + 0.5 * Math.sin(seg(p, 0.18, 0.82) * Math.PI * 5 - k * 1.1));
        ctx.save();
        ctx.globalAlpha = chevVis * waveA;
        drawChevron(kx, chevY, s * 0.072, s * 0.026, k === 2 ? COLORS.peach : COLORS.coral);
        ctx.restore();
      }
    }

    // Seamless Handoff: Scene 3 Cashflow Funnel emerging cleanly at upper stage (p = 0.85 -> 1.00)!
    if (toFunnelU > 0.005) {
      const fTop = lerp(cy - s * 0.32, cy - s * 0.46, toFunnelU);
      const fBot = lerp(cy - s * 0.02, cy - s * 0.06, toFunnelU);
      const fTopW = lerp(s * 0.54, s * 0.86, toFunnelU);
      const fNeckW = s * 0.21;
      drawCashflowFunnel(fTop, fBot, fTopW, fNeckW, toFunnelU, toFunnelU);
    }
  }

  // =========================================================================
  // SCENE 3 (10s - 15s): CASHFLOW COLLECTOR & DIVIDEND DRIP
  // =========================================================================
  function drawScene3(p) {
    // 0.00 - 0.16: Lower Balance Collector Tray rises cleanly below Scene 2's persistent Funnel
    // 0.12 - 0.80: 4 rhythmic Soft Peach dividend coins drop cleanly through open drip zone into tray, raising wave!
    // 0.80 - 1.00: Funnel & coins retract cleanly upward; filled Collector Tray expands seamlessly into Scene 4 Wallet!

    const trayIn = easeOutCubic(seg(p, 0.02, 0.18));
    const funnelOut = easeInCubic(seg(p, 0.80, 0.90));
    const toWalletU = easeInOutCubic(seg(p, 0.84, 1.00));

    const funnelTop = cy - s * 0.46;
    const funnelBot = cy - s * 0.06;

    drawStageShadow(lerp(0.96, 1.06, toWalletU), 1);

    // 1. Rhythmic Dividend Coins falling strictly inside clear Drip Zone (y: cy - 0.06*s -> cy + 0.17*s)
    // Clipped strictly between nozzle exit and tray top rim so coins NEVER overlap funnel or tray face!
    const dripVis = (1 - funnelOut);
    if (dripVis > 0.005) {
      const trayTopY = cy + s * 0.16;
      const coinR = s * 0.048;

      ctx.save();
      ctx.beginPath();
      ctx.rect(cx - s * 0.20, funnelBot - s * 0.01, s * 0.40, (trayTopY - funnelBot) + s * 0.02);
      ctx.clip();
      ctx.globalAlpha = dripVis;

      // 4 cleanly spaced coin drops across p = 0.10 -> 0.78 (zero coin-to-coin collision!)
      const dropStarts = [0.10, 0.27, 0.44, 0.61];
      const dropDur = 0.18;
      for (let i = 0; i < dropStarts.length; i++) {
        const dp = (p - dropStarts[i]) / dropDur;
        if (dp <= 0 || dp >= 1) continue;
        // Smooth gravity-like natural acceleration (quad ease-in mixed with linear)
        const fallU = dp * (0.45 + 0.55 * dp);
        const coinY = lerp(funnelBot - coinR, trayTopY + coinR, fallU);

        ctx.beginPath();
        ctx.arc(cx, coinY, coinR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.peach;
        ctx.fill();

        ctx.beginPath();
        ctx.arc(cx, coinY, coinR * 0.42, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.coralDeep;
        ctx.fill();
      }
      ctx.restore();
    }

    // 2. Upper Geometric Funnel (Continuous from Scene 2 p = 1.00!)
    if (funnelOut < 0.995) {
      const shiftY = -funnelOut * s * 0.18;
      drawCashflowFunnel(funnelTop + shiftY, funnelBot + shiftY, s * 0.86, s * 0.21, 1 - funnelOut, 1 - funnelOut);
    }

    // 3. Lower Balance Collector Tray -> Seamlessly expands into Scene 4 Wallet Body at p = 0.84 -> 1.00!
    const baseTrayW = s * 1.00;
    const baseTrayH = s * 0.34;
    const baseTrayY = cy + s * 0.33;

    const curW = lerp(baseTrayW * lerp(0.76, 1, trayIn), s * 1.04, toWalletU);
    const curH = lerp(baseTrayH * lerp(0.65, 1, trayIn), s * 0.68, toWalletU);
    const curY = lerp(lerp(baseTrayY + s * 0.08, baseTrayY, trayIn), cy + s * 0.02, toWalletU);
    const curR = lerp(s * 0.085, s * 0.11, toWalletU);
    const left = cx - curW * 0.5;
    const top = curY - curH * 0.5;

    ctx.save();
    ctx.globalAlpha = clamp01(trayIn * 1.5);

    // Outer Tray / Wallet Body
    roundRectPath(left, top, curW, curH, curR);
    ctx.fillStyle = COLORS.plumCard;
    ctx.fill();

    // Clipped Rising Dividend Wave strictly inside Tray Interior (fades smoothly before Scene 4 wallet interior)
    const waveVis = trayIn * (1 - easeInCubic(seg(p, 0.83, 0.95)));
    if (waveVis > 0.005) {
      const pad = s * 0.036;
      const inL = left + pad;
      const inT = top + pad;
      const inW = curW - pad * 2;
      const inH = curH - pad * 2;
      const inR = Math.max(4, curR - pad * 0.7);

      ctx.save();
      roundRectPath(inL, inT, inW, inH, inR);
      ctx.fillStyle = COLORS.plumRecess;
      ctx.fill();
      ctx.clip();

      // Smooth rising fill level synchronized to the 4 coin drops (26% -> 82%)
      const fillLevel = lerp(0.26, 0.82, easeInOutCubic(seg(p, 0.14, 0.78)));
      const surfY = inT + inH * (1 - fillLevel);
      const wavePhase = p * Math.PI * 10;
      const waveAmp = s * 0.022;

      // Back magenta wave layer
      ctx.save();
      ctx.globalAlpha = waveVis * 0.72;
      ctx.beginPath();
      ctx.moveTo(inL, inT + inH + 4);
      for (let st = 0; st <= 28; st++) {
        const u = st / 28;
        const wx = inL + u * inW;
        const wy = surfY - s * 0.012 + Math.sin(u * Math.PI * 2.2 + wavePhase + 1.4) * waveAmp;
        ctx.lineTo(wx, wy);
      }
      ctx.lineTo(inL + inW, inT + inH + 4);
      ctx.closePath();
      ctx.fillStyle = COLORS.magenta;
      ctx.fill();
      ctx.restore();

      // Front Coral-Peach wave layer
      ctx.save();
      ctx.globalAlpha = waveVis;
      const wGrad = ctx.createLinearGradient(0, surfY - waveAmp, 0, inT + inH);
      wGrad.addColorStop(0, COLORS.peach);
      wGrad.addColorStop(0.55, COLORS.coral);
      wGrad.addColorStop(1, COLORS.coralDeep);

      ctx.beginPath();
      ctx.moveTo(inL, inT + inH + 4);
      for (let st = 0; st <= 28; st++) {
        const u = st / 28;
        const wx = inL + u * inW;
        const wy = surfY + Math.sin(u * Math.PI * 2.0 + wavePhase) * waveAmp;
        ctx.lineTo(wx, wy);
      }
      ctx.lineTo(inL + inW, inT + inH + 4);
      ctx.closePath();
      ctx.fillStyle = wGrad;
      ctx.fill();
      ctx.restore();

      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15s - 20s): GROWING BALANCE WALLET CARD -> SEAMLESS LOOP TO CALENDAR
  // =========================================================================
  function drawScene4(p) {
    // 0.00 - 0.16: Top peek card strip & right wallet clasp slide cleanly onto persistent Scene 3 body
    // 0.14 - 0.62: 3 dividend status pills light up + Accumulated Yield Progress Bar fills cleanly to 100%
    // 0.56 - 0.76: Diagonal sheen sweep across wallet body
    // 0.78 - 1.00: Wallet clasp & bar retract; body reshapes smoothly into EXACT Scene 1 Dividend Calendar!

    const introU = easeOutCubic(seg(p, 0.02, 0.18));
    const walletOut = easeInCubic(seg(p, 0.78, 0.87));
    const toCalU = easeInOutCubic(seg(p, 0.85, 1.00));
    const wVis = introU * (1 - walletOut);

    drawStageShadow(lerp(1.06, 1.04, toCalU), 1);

    if (toCalU <= 0.001) {
      const wW = s * 1.04;
      const wH = s * 0.68;
      const wY = cy + s * 0.02;
      const wR = s * 0.11;
      const left = cx - wW * 0.5;
      const top = wY - wH * 0.5;

      // Top Peek Dividend Card Strip cleanly tucked above wallet top edge (no overlap with clasp!)
      if (wVis > 0.005) {
        const peekW = wW * 0.78;
        const peekH = s * 0.11 * wVis;
        const peekTop = top - peekH + s * 0.035;
        ctx.save();
        ctx.globalAlpha = wVis;
        roundRectPath(cx - peekW * 0.5, peekTop, peekW, peekH + s * 0.06, s * 0.055);
        ctx.fillStyle = COLORS.coral;
        ctx.fill();
        ctx.restore();
      }

      // Main Wallet Body (Matches Scene 3 p = 1.00 EXACTLY!)
      roundRectPath(left, top, wW, wH, wR);
      ctx.fillStyle = COLORS.plumCard;
      ctx.fill();

      // Clipped Right-Side Flat Shade & Diagonal Sheen
      ctx.save();
      roundRectPath(left, top, wW, wH, wR);
      ctx.clip();
      ctx.globalAlpha = introU;
      ctx.fillStyle = COLORS.plumShade;
      ctx.fillRect(cx + s * 0.06, top, wW * 0.5, wH);
      ctx.globalAlpha = 1;

      const sheenP = seg(p, 0.56, 0.75);
      if (sheenP > 0 && sheenP < 1) {
        drawClippedSheen(left, top, wW, wH, sheenP, 0.9);
      }
      ctx.restore();

      // Right-Side Wallet Clasp Flap (strictly x >= cx + 0.22*s -> wide 0.12*s gap from left bars!)
      if (wVis > 0.005) {
        const flapW = s * 0.30 * wVis;
        const flapH = s * 0.23;
        const flapRight = cx + wW * 0.5 + s * 0.02;
        const flapLeft = flapRight - flapW;

        ctx.save();
        ctx.globalAlpha = wVis;
        roundRectPath(flapLeft, wY - flapH * 0.5, flapW, flapH, s * 0.065);
        ctx.fillStyle = COLORS.magenta;
        ctx.fill();

        // Crisp Soft Peach Circular Snap Button centered on flap
        const btnR = s * 0.044 * wVis;
        ctx.beginPath();
        ctx.arc(flapLeft + flapW * 0.42, wY, btnR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.peach;
        ctx.fill();
        ctx.restore();
      }

      // Left Interior Content (strictly x ∈ [cx - 0.42*s, cx + 0.10*s] -> 0.12*s clear gap before clasp flap!)
      if (wVis > 0.005) {
        const areaLeft = cx - s * 0.42;
        const areaW = s * 0.52;

        // Top Row: 3 Sequenced Soft Peach & Coral Dividend Status Pills
        const pillW = s * 0.145;
        const pillH = s * 0.052;
        const pillGap = (areaW - pillW * 3) * 0.5;
        const pillY = wY - s * 0.135;
        const pFills = [COLORS.magenta, COLORS.coral, COLORS.peach];

        ctx.save();
        ctx.globalAlpha = wVis;
        for (let i = 0; i < 3; i++) {
          const px = areaLeft + i * (pillW + pillGap);
          const pOn = easeOutCubic(seg(p, 0.14 + i * 0.08, 0.26 + i * 0.08));
          roundRectPath(px, pillY - pillH * 0.5, pillW, pillH, pillH * 0.5);
          ctx.fillStyle = pOn > 0.35 ? pFills[i] : COLORS.plumRecess;
          ctx.fill();
        }

        // Bottom Row: Accumulated Yield Progress Track + Fill Bar (fills cleanly 25% -> 100%)
        const barH = s * 0.115;
        const barY = wY + s * 0.085;
        const fillProg = lerp(0.24, 1.0, easeInOutCubic(seg(p, 0.16, 0.56)));

        roundRectPath(areaLeft, barY - barH * 0.5, areaW, barH, barH * 0.5);
        ctx.fillStyle = COLORS.plumRecess;
        ctx.fill();

        const fillW = areaW * fillProg;
        if (fillW > barH * 0.5) {
          const bGrad = ctx.createLinearGradient(areaLeft, 0, areaLeft + areaW, 0);
          bGrad.addColorStop(0, COLORS.coral);
          bGrad.addColorStop(1, COLORS.peach);
          roundRectPath(areaLeft, barY - barH * 0.5, fillW, barH, barH * 0.5);
          ctx.fillStyle = bGrad;
          ctx.fill();
        }

        // Subtle crisp indicator bar below progress bar (clean balance inside left panel)
        const subW = areaW * 0.56 * easeOutCubic(seg(p, 0.30, 0.48));
        const subH = s * 0.032;
        roundRectPath(areaLeft, barY + s * 0.115 - subH * 0.5, subW, subH, subH * 0.5);
        ctx.fillStyle = COLORS.plumTile;
        ctx.fill();

        ctx.restore();
      }
    } else {
      // Seamless Morph Return -> EXACT Scene 1 Dividend Calendar at p = 1.00!
      const curW = lerp(s * 1.04, s * 1.00, toCalU);
      const curH = lerp(s * 0.68, s * 0.88, toCalU);
      const curY = lerp(cy + s * 0.02, cy + s * 0.04, toCalU);
      const curR = lerp(s * 0.11, s * 0.12, toCalU);
      const headerIn = easeOutCubic(seg(p, 0.88, 0.99));
      const ringIn = easeOutCubic(seg(p, 0.90, 1.00));
      const gridIn = easeOutCubic(seg(p, 0.90, 1.00));

      drawCalendarBase(
        curW, curH, curY, curR,
        headerIn, ringIn, gridIn,
        [0, 0, 0, 0, 0, 0], 1, 0
      );
    }
  }

  // Render Frame
  ctx.save();
  drawBackground();

  if (currentScene === 0) {
    drawScene1(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3(sceneProgress);
  } else {
    drawScene4(sceneProgress);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide * 0.42;
  const phase = (loopT / duration) * Math.PI * 2;

  const COLORS = {
    bgTop: '#120E0A',
    bgMid: '#1C1610',
    bgBot: '#271E15',
    goldPale: '#FDE68A',
    goldBright: '#FCD34D',
    amberMain: '#F59E0B',
    amberDeep: '#D97706',
    bronzeMain: '#B45309',
    bronzeDark: '#7C3908',
    bronzeShadow: '#4A2408',
    espressoRecess: '#23160B',
    stageShadow: 'rgba(10, 6, 3, 0.48)',
    sheen: 'rgba(255, 250, 225, 0.22)',
    ambientMark: '#543F2A'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function seg(p, a, b) {
    return clamp01((p - a) / (b - a));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp01(u);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fill) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  // Crisp 4-point sparkle diamond star (sharp flat 2D vector, no blur)
  function drawSparkle4(x, y, r, fill, alpha) {
    if (r <= 0.5 || alpha <= 0.005) return;
    const inner = r * 0.26;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(x, y);
    ctx.beginPath();
    ctx.moveTo(0, -r);
    ctx.lineTo(inner, -inner);
    ctx.lineTo(r, 0);
    ctx.lineTo(inner, inner);
    ctx.lineTo(0, r);
    ctx.lineTo(-inner, inner);
    ctx.lineTo(-r, 0);
    ctx.lineTo(-inner, -inner);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.restore();
  }

  function drawClippedSheen(x, y, w, h, progress, alpha) {
    if (progress <= 0 || progress >= 1) return;
    const bandW = w * 0.22;
    const travel = w + h * 0.65 + bandW * 2;
    const startX = x - h * 0.35 - bandW + progress * travel;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.beginPath();
    ctx.moveTo(startX, y - h * 0.1);
    ctx.lineTo(startX + bandW, y - h * 0.1);
    ctx.lineTo(startX + bandW - h * 0.45, y + h * 1.1);
    ctx.lineTo(startX - h * 0.45, y + h * 1.1);
    ctx.closePath();
    ctx.fillStyle = COLORS.sheen;
    ctx.fill();
    ctx.restore();
  }

  function drawStageShadow(widthFactor, alpha) {
    if (alpha <= 0.001 || widthFactor <= 0.001) return;
    const sw = s * 0.56 * widthFactor;
    const sh = s * 0.044;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.ellipse(cx, cy + s * 0.68, sw, sh, 0, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.stageShadow;
    ctx.fill();
    ctx.restore();
  }

  // Clean Modern Dark Espresso Gradient Background (Zero Glow, Zero Edge Frames, Zero Corner Brackets)
  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, COLORS.bgTop);
    bgGrad.addColorStop(0.5, COLORS.bgMid);
    bgGrad.addColorStop(1, COLORS.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle flat vector micro-accents strictly in outer margins far from hero icon
    const marks = [
      { nx: 0.10, ny: 0.25, type: 0, sz: 0.011, ph: 0.2, amp: 0.013, op: 0.22 },
      { nx: 0.17, ny: 0.72, type: 1, sz: 0.012, ph: 1.7, amp: 0.012, op: 0.18 },
      { nx: 0.08, ny: 0.54, type: 2, sz: 0.008, ph: 3.1, amp: 0.010, op: 0.16 },
      { nx: 0.20, ny: 0.35, type: 0, sz: 0.008, ph: 4.5, amp: 0.011, op: 0.15 },
      { nx: 0.90, ny: 0.27, type: 1, sz: 0.012, ph: 0.8, amp: 0.013, op: 0.20 },
      { nx: 0.83, ny: 0.73, type: 0, sz: 0.011, ph: 2.5, amp: 0.012, op: 0.22 },
      { nx: 0.92, ny: 0.55, type: 2, sz: 0.008, ph: 4.0, amp: 0.010, op: 0.16 },
      { nx: 0.80, ny: 0.36, type: 0, sz: 0.008, ph: 5.3, amp: 0.011, op: 0.15 }
    ];

    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      const mx = width * m.nx + Math.cos(phase + m.ph) * minSide * (m.amp * 0.45);
      const my = height * m.ny + Math.sin(phase + m.ph) * minSide * m.amp;
      const r = minSide * m.sz;
      const pulse = 0.78 + 0.22 * Math.sin(phase * 2 + m.ph);

      ctx.save();
      ctx.globalAlpha = m.op * pulse;
      if (m.type === 0) {
        drawDiamond(mx, my, r, r, COLORS.ambientMark);
      } else if (m.type === 1) {
        drawSparkle4(mx, my, r * 1.15, COLORS.ambientMark, 1);
      } else {
        roundRectPath(mx - r * 1.45, my - r * 0.32, r * 2.9, r * 0.64, r * 0.32);
        ctx.fillStyle = COLORS.ambientMark;
        ctx.fill();
      }
      ctx.restore();
    }
  }

  // Crisp 2D Flat Geometric Gold Ingot (Symmetrical Flat Trapezoid with Inner Bevel, No 3D Extrusion)
  function ingotTrapezoidPath(x, y, w, h, slopeRatio) {
    const hw = w * 0.5;
    const hh = h * 0.5;
    const inset = w * slopeRatio;
    const r = Math.min(h * 0.14, w * 0.05);

    const xTL = x - hw + inset;
    const xTR = x + hw - inset;
    const xBR = x + hw;
    const xBL = x - hw;
    const yT = y - hh;
    const yB = y + hh;

    ctx.beginPath();
    ctx.moveTo(xTL + r, yT);
    ctx.lineTo(xTR - r, yT);
    ctx.quadraticCurveTo(xTR, yT, xTR + r * 0.45, yT + r);
    ctx.lineTo(xBR - r * 0.45, yB - r);
    ctx.quadraticCurveTo(xBR, yB, xBR - r, yB);
    ctx.lineTo(xBL + r, yB);
    ctx.quadraticCurveTo(xBL, yB, xBL + r * 0.45, yB - r);
    ctx.lineTo(xTL - r * 0.45, yT + r);
    ctx.quadraticCurveTo(xTL, yT, xTL + r, yT);
    ctx.closePath();
  }

  function drawGoldIngot(x, y, w, h, detailed, sheenP, alpha) {
    if (alpha <= 0.005 || w <= 2 || h <= 2) return;

    ctx.save();
    ctx.globalAlpha = alpha;

    // Outer Gold Trapezoid
    ingotTrapezoidPath(x, y, w, h, 0.13);
    ctx.fillStyle = COLORS.amberMain;
    ctx.fill();

    // Clip flat duotone bevel details strictly inside trapezoid
    ctx.save();
    ingotTrapezoidPath(x, y, w, h, 0.13);
    ctx.clip();

    // Crisp right-half 2D flat shade
    ctx.fillStyle = COLORS.amberDeep;
    ctx.fillRect(x + w * 0.06, y - h * 0.55, w * 0.5, h * 1.1);

    // Crisp top bevel highlight strip
    ctx.fillStyle = COLORS.goldBright;
    ctx.fillRect(x - w * 0.55, y - h * 0.5, w * 1.1, h * 0.20);

    // Crisp bottom bronze grounding rim
    ctx.fillStyle = COLORS.bronzeMain;
    ctx.fillRect(x - w * 0.55, y + h * 0.34, w * 1.1, h * 0.20);

    // Inner Recessed Tablet Face (clean proportional flat bevel)
    const iw = w * 0.70;
    const ih = h * 0.52;
    ingotTrapezoidPath(x, y + h * 0.01, iw, ih, 0.10);
    ctx.fillStyle = COLORS.goldBright;
    ctx.fill();

    ctx.save();
    ingotTrapezoidPath(x, y + h * 0.01, iw, ih, 0.10);
    ctx.clip();
    ctx.fillStyle = COLORS.amberMain;
    ctx.fillRect(x + iw * 0.08, y - ih * 0.55, iw * 0.5, ih * 1.15);
    ctx.restore();

    // Crisp Engraved Detail inside inner tablet
    if (detailed) {
      // Top micro-diamond hallmark & clean engraved purity bars / "999.9"
      const markY = y - ih * 0.22;
      drawDiamond(x, markY, ih * 0.11, ih * 0.11, COLORS.bronzeDark);

      ctx.fillStyle = COLORS.bronzeDark;
      ctx.font = '700 ' + Math.round(ih * 0.36) + 'px system-ui, -apple-system, Segoe UI, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('999.9', x, y + ih * 0.15);
    } else {
      // Minimal crisp geometric stamp bar for smaller stacked ingots
      const bw = iw * 0.38;
      const bh = Math.max(2, ih * 0.22);
      roundRectPath(x - bw * 0.5, y + h * 0.01 - bh * 0.5, bw, bh, bh * 0.5);
      ctx.fillStyle = COLORS.bronzeDark;
      ctx.fill();
    }

    // Diagonal light sheen sweep
    if (sheenP > 0 && sheenP < 1) {
      drawClippedSheen(x - w * 0.5, y - h * 0.5, w, h, sheenP, 0.92);
    }

    ctx.restore();
    ctx.restore();
  }

  function drawBronzePlinth(x, y, w, h, alpha) {
    if (alpha <= 0.005 || w <= 1) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    roundRectPath(x - w * 0.5, y - h * 0.5, w, h, h * 0.5);
    ctx.fillStyle = COLORS.bronzeDark;
    ctx.fill();

    ctx.save();
    roundRectPath(x - w * 0.5, y - h * 0.5, w, h, h * 0.5);
    ctx.clip();
    ctx.fillStyle = COLORS.amberMain;
    ctx.fillRect(x - w * 0.5, y - h * 0.5, w, h * 0.34);
    ctx.restore();
    ctx.restore();
  }

  // =========================================================================
  // SCENE 1 (0s - 5s): PRECISION GOLD INGOT
  // =========================================================================
  function drawScene1(p) {
    // 0.00 - 0.18: Hero Gold Ingot centered at (cx, cy + 0.08*s) glides smoothly to (cx, cy) with sheen
    // 0.18 - 0.54: Top crest diamond & bottom 3-segment purity bar reveal cleanly with wide separation
    // 0.54 - 0.80: Second sheen sweep + gentle sparkle & purity cadence
    // 0.80 - 1.00: Accents retract; Hero Ingot scales cleanly down to bottom-center ingot of Scene 2 pyramid + plinth!

    const liftU = easeInOutCubic(seg(p, 0.06, 0.22));
    const accIn = easeOutCubic(seg(p, 0.20, 0.38));
    const accOut = easeInCubic(seg(p, 0.78, 0.88));
    const accVis = accIn * (1 - accOut);
    const toStackU = easeInOutCubic(seg(p, 0.82, 1.00));

    const plinthIn = easeOutCubic(seg(p, 0.86, 1.00));
    const plinthY = cy + s * 0.49;
    const plinthH = s * 0.052;
    const plinthW = lerp(s * 0.44, s * 1.46, plinthIn);

    drawStageShadow(lerp(1.08, 1.38, plinthIn), 1);

    // Base plinth enters smoothly at end of Scene 1 for exact Scene 2 handoff
    if (plinthIn > 0.005) {
      drawBronzePlinth(cx, plinthY, plinthW, plinthH, plinthIn);
    }

    // Main Ingot Geometry (transitions seamlessly from hero size to Scene 2 bottom-center ingot)
    const heroW = s * 1.06;
    const heroH = s * 0.44;
    const stackW = s * 0.42;
    const stackH = s * 0.195;

    const floatY = Math.sin(seg(p, 0.22, 0.82) * Math.PI * 2) * s * 0.016 * (1 - toStackU);
    const baseIngotY = lerp(cy + s * 0.08, cy, liftU) + floatY;
    const curY = lerp(baseIngotY, cy + s * 0.34, toStackU);
    const curW = lerp(heroW, stackW, toStackU);
    const curH = lerp(heroH, stackH, toStackU);
    const useDetailed = toStackU < 0.48;
    const sheenP = p < 0.42 ? seg(p, 0.06, 0.28) : seg(p, 0.56, 0.76);

    drawGoldIngot(cx, curY, curW, curH, useDetailed, sheenP, 1);

    // Top Crest Emblem strictly ABOVE ingot (y = cy - 0.38*s -> 0.16*s clear vertical gap!)
    if (accVis > 0.005) {
      const crestY = cy - s * 0.38 + lerp(s * 0.04, 0, accIn);
      const pulse = 1 + 0.06 * Math.sin(seg(p, 0.30, 0.80) * Math.PI * 4);
      ctx.save();
      ctx.globalAlpha = accVis;
      drawDiamond(cx, crestY, s * 0.065 * accVis * pulse, s * 0.065 * accVis * pulse, COLORS.goldBright);
      drawDiamond(cx, crestY, s * 0.028 * accVis, s * 0.028 * accVis, COLORS.bronzeDark);

      // Flanking horizontal accent micro-bars strictly clear of crest diamond
      const barW = s * 0.12 * accVis;
      const barH = s * 0.024;
      roundRectPath(cx - s * 0.12 - barW, crestY - barH * 0.5, barW, barH, barH * 0.5);
      ctx.fillStyle = COLORS.amberMain;
      ctx.fill();
      roundRectPath(cx + s * 0.12, crestY - barH * 0.5, barW, barH, barH * 0.5);
      ctx.fillStyle = COLORS.amberMain;
      ctx.fill();
      ctx.restore();
    }

    // Bottom 3-Segment Purity Bar strictly BELOW ingot (y = cy + 0.37*s -> 0.15*s clear vertical gap!)
    if (accVis > 0.005) {
      const segW = s * 0.24;
      const segH = s * 0.048;
      const segGap = s * 0.05;
      const segY = cy + s * 0.37 + lerp(-s * 0.03, 0, accIn);
      const segColors = [COLORS.bronzeMain, COLORS.amberMain, COLORS.goldBright];

      for (let i = 0; i < 3; i++) {
        const sIn = easeOutCubic(seg(p, 0.24 + i * 0.07, 0.38 + i * 0.07)) * (1 - accOut);
        if (sIn <= 0.005) continue;
        const sx = cx + (i - 1) * (segW + segGap);
        const wPulse = 0.86 + 0.14 * Math.sin(seg(p, 0.35, 0.80) * Math.PI * 4 - i * 0.9);
        ctx.save();
        ctx.globalAlpha = sIn * wPulse;
        roundRectPath(sx - segW * 0.5, segY - segH * 0.5, segW, segH, segH * 0.5);
        ctx.fillStyle = segColors[i];
        ctx.fill();
        ctx.restore();
      }
    }

    // Crisp 4-point sparkles cleanly in upper-left & upper-right open air (far from ingot corners)
    const spVis = easeOutCubic(seg(p, 0.28, 0.42)) * (1 - accOut);
    if (spVis > 0.005) {
      const p1 = 0.72 + 0.28 * Math.sin(seg(p, 0.30, 0.80) * Math.PI * 4);
      const p2 = 0.72 + 0.28 * Math.cos(seg(p, 0.30, 0.80) * Math.PI * 4);
      drawSparkle4(cx - s * 0.56, cy - s * 0.28, s * 0.052 * spVis * p1, COLORS.goldPale, spVis);
      drawSparkle4(cx + s * 0.56, cy - s * 0.22, s * 0.044 * spVis * p2, COLORS.goldBright, spVis);
    }
  }

  // =========================================================================
  // SCENE 2 (5s - 10s): TIERED RESERVE PYRAMID (6 GOLD INGOTS IN 3 TIERS)
  // =========================================================================
  function drawScene2(p) {
    const plinthY = cy + s * 0.49;
    const plinthH = s * 0.052;
    const iw = s * 0.42;
    const ih = s * 0.195;
    const xPitch = s * 0.465; // 0.045*s clear horizontal gap
    const yPitch = s * 0.230; // 0.035*s clear vertical gap
    const row0Y = cy + s * 0.34;

    const toDiamondU = easeInOutCubic(seg(p, 0.84, 1.00));
    const plinthOut = easeInCubic(seg(p, 0.80, 0.92));

    drawStageShadow(lerp(1.38, 0.62, toDiamondU), 1);

    // Base Plinth (persists cleanly from Scene 1, retracts cleanly before Scene 3)
    if (plinthOut < 0.995) {
      drawBronzePlinth(cx, plinthY, s * 1.46 * (1 - plinthOut * 0.55), plinthH, 1 - plinthOut);
    }

    // 3-Tier Pyramid Ingot Definitions (Row 0 center is already present at p = 0.00!)
    const stackOut = easeInCubic(seg(p, 0.80, 0.93));
    const breath = Math.sin(seg(p, 0.46, 0.82) * Math.PI * 2) * s * 0.010 * (1 - stackOut);

    // Bottom Row: Left & Right slide cleanly outward from center; Center stays rock-solid
    const sideIn = easeOutCubic(seg(p, 0.02, 0.20));
    const bottomSheen = seg(p, 0.48, 0.64);
    const midSheen = seg(p, 0.55, 0.71);
    const topSheen = seg(p, 0.62, 0.78);

    // Row 0 Left & Right
    for (let dir = -1; dir <= 1; dir += 2) {
      const vis = sideIn * (1 - stackOut);
      if (vis > 0.005) {
        const targetX = cx + dir * xPitch;
        const curX = lerp(cx + dir * xPitch * 0.52, targetX, sideIn);
        const exitX = lerp(curX, cx + dir * xPitch * 0.35, stackOut);
        drawGoldIngot(exitX, row0Y + breath * 0.4, iw * lerp(0.7, 1, vis), ih * lerp(0.7, 1, vis), false, bottomSheen, vis);
      }
    }

    // Row 0 Center (Continuous from Scene 1 p = 1.00!)
    if (stackOut < 0.995) {
      const cVis = 1 - stackOut;
      drawGoldIngot(cx, lerp(row0Y + breath * 0.4, cy, stackOut), iw * lerp(1, 0.6, stackOut), ih * lerp(1, 0.6, stackOut), false, bottomSheen, cVis);
    }

    // Row 1 (2 Middle Ingots settling cleanly from slightly above)
    for (let m = 0; m < 2; m++) {
      const mIn = easeOutCubic(seg(p, 0.14 + m * 0.05, 0.32 + m * 0.05));
      const vis = mIn * (1 - stackOut);
      if (vis > 0.005) {
        const mx = cx + (m === 0 ? -0.5 : 0.5) * xPitch;
        const my = row0Y - yPitch + breath * 0.7;
        const curY = lerp(my - s * 0.09, my, mIn);
        drawGoldIngot(lerp(mx, cx, stackOut * 0.4), lerp(curY, cy, stackOut * 0.5), iw * lerp(0.75, 1, vis), ih * lerp(0.75, 1, vis), false, midSheen, vis);
      }
    }

    // Row 2 (Top Summit Ingot)
    const topIn = easeOutCubic(seg(p, 0.28, 0.44));
    const topVis = topIn * (1 - stackOut);
    if (topVis > 0.005) {
      const ty = row0Y - yPitch * 2 + breath;
      const curY = lerp(ty - s * 0.10, ty, topIn);
      drawGoldIngot(cx, lerp(curY, cy, stackOut * 0.5), iw * lerp(0.75, 1, topVis), ih * lerp(0.75, 1, topVis), false, topSheen, topVis);
    }

    // 3 Crisp 4-Point Sparkles strictly in clean open air around summit (wide clearance!)
    const spIn = easeOutCubic(seg(p, 0.42, 0.54));
    const spVis = spIn * (1 - easeInCubic(seg(p, 0.78, 0.86)));
    if (spVis > 0.005) {
      const w1 = 0.75 + 0.25 * Math.sin(seg(p, 0.44, 0.82) * Math.PI * 4);
      const w2 = 0.75 + 0.25 * Math.sin(seg(p, 0.44, 0.82) * Math.PI * 4 + 2.0);
      const w3 = 0.75 + 0.25 * Math.sin(seg(p, 0.44, 0.82) * Math.PI * 4 + 4.0);
      drawSparkle4(cx, cy - s * 0.36, s * 0.062 * spVis * w1, COLORS.goldPale, spVis);
      drawSparkle4(cx - s * 0.48, cy - s * 0.17, s * 0.048 * spVis * w2, COLORS.goldBright, spVis);
      drawSparkle4(cx + s * 0.48, cy - s * 0.17, s * 0.048 * spVis * w3, COLORS.goldBright, spVis);
    }

    // Seamless Diamond Seed Core emerging cleanly at center (p = 0.86 -> 1.00) -> Exact Scene 3 start!
    const coreIn = easeOutCubic(seg(p, 0.86, 1.00));
    if (coreIn > 0.005) {
      const rx = s * 0.22 * coreIn;
      const ry = s * 0.20 * coreIn;
      ctx.save();
      ctx.globalAlpha = coreIn;
      drawDiamond(cx, cy, rx, ry, COLORS.amberMain);
      drawDiamond(cx, cy, rx * 0.56, ry * 0.56, COLORS.goldBright);
      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 3 (10s - 15s): PRISMATIC ASSET DIAMOND (6-FACET 2D FLAT GEMSTONE)
  // =========================================================================
  function drawScene3(p) {
    // 0.00 - 0.18: Diamond core unfolds cleanly into crisp 6-facet 2D flat golden gemstone
    // 0.18 - 0.82: Smooth left-to-right prismatic light wave across facets + calm vertical hover + crisp side ray-bars
    // 0.82 - 1.00: Lower facets fold cleanly away while top crown expands into exact Scene 4 Treasury Pediment Roof!

    const openU = easeOutCubic(seg(p, 0.02, 0.20));
    const toPedimentU = easeInOutCubic(seg(p, 0.82, 1.00));
    const diamondVis = 1 - easeInCubic(seg(p, 0.80, 0.91));

    drawStageShadow(lerp(0.62, 1.08, openU), 1);

    // Cross-fade out of exact Scene 2 Diamond Seed Core during 0.00 - 0.10
    const coreFade = 1 - easeInCubic(seg(p, 0.0, 0.10));
    if (coreFade > 0.005) {
      ctx.save();
      ctx.globalAlpha = coreFade;
      drawDiamond(cx, cy, s * 0.22 * lerp(1, 1.45, 1 - coreFade), s * 0.20 * lerp(1, 1.45, 1 - coreFade), COLORS.amberMain);
      drawDiamond(cx, cy, s * 0.123 * coreFade, s * 0.112 * coreFade, COLORS.goldBright);
      ctx.restore();
    }

    // 6-Facet Cut Gemstone (Shared exact vertex mesh -> zero overlap, zero gaps!)
    const hoverY = Math.sin(seg(p, 0.18, 0.82) * Math.PI * 2) * s * 0.026 * diamondVis;
    const gemScale = lerp(0.42, 1.0, openU) * lerp(1.0, 0.82, 1 - diamondVis);

    if (diamondVis > 0.005) {
      const gx = cx;
      const gy = cy + hoverY;
      const sc = s * gemScale;

      // Exact gemstone vertices
      const yTop = gy - sc * 0.42;
      const yMid = gy - sc * 0.12;
      const yBot = gy + sc * 0.44;

      const xTopL = gx - sc * 0.30;
      const xTopR = gx + sc * 0.30;
      const xMidFarL = gx - sc * 0.52;
      const xMidInL = gx - sc * 0.19;
      const xMidInR = gx + sc * 0.19;
      const xMidFarR = gx + sc * 0.52;

      // Prismatic shimmer wave across the 6 facets
      const wavePhase = seg(p, 0.16, 0.84) * Math.PI * 3.0;
      const paletteCycle = [COLORS.bronzeMain, COLORS.amberDeep, COLORS.amberMain, COLORS.goldBright, COLORS.goldPale];

      function facetColor(idx, baseLevel) {
        const wave = 0.5 + 0.5 * Math.sin(wavePhase - idx * 0.85);
        const lvl = clamp01(baseLevel + (wave - 0.5) * 0.42);
        const ci = Math.min(paletteCycle.length - 1, Math.floor(lvl * paletteCycle.length));
        return paletteCycle[ci];
      }

      function fillPoly(pts, fill) {
        ctx.beginPath();
        ctx.moveTo(pts[0][0], pts[0][1]);
        for (let k = 1; k < pts.length; k++) ctx.lineTo(pts[k][0], pts[k][1]);
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.fill();
      }

      ctx.save();
      ctx.globalAlpha = clamp01(openU * 1.6) * diamondVis;

      // Crown Left Facet
      fillPoly([[xTopL, yTop], [xMidInL, yMid], [xMidFarL, yMid]], facetColor(0, 0.72));
      // Crown Center Facet (brightest table)
      fillPoly([[xTopL, yTop], [xTopR, yTop], [xMidInR, yMid], [xMidInL, yMid]], facetColor(1, 0.90));
      // Crown Right Facet
      fillPoly([[xTopR, yTop], [xMidFarR, yMid], [xMidInR, yMid]], facetColor(2, 0.56));

      // Pavilion Left Facet
      fillPoly([[xMidFarL, yMid], [xMidInL, yMid], [gx, yBot]], facetColor(1, 0.50));
      // Pavilion Center Facet
      fillPoly([[xMidInL, yMid], [xMidInR, yMid], [gx, yBot]], facetColor(2, 0.74));
      // Pavilion Right Facet
      fillPoly([[xMidInR, yMid], [xMidFarR, yMid], [gx, yBot]], facetColor(3, 0.30));

      // Subtle crisp internal facet ridge highlight along girdle
      ctx.beginPath();
      ctx.moveTo(xMidFarL, yMid);
      ctx.lineTo(xMidFarR, yMid);
      ctx.strokeStyle = 'rgba(255, 250, 225, 0.35)';
      ctx.lineWidth = Math.max(1.5, s * 0.008);
      ctx.stroke();

      // Clipped diagonal sheen across whole diamond silhouette
      const sheenP = seg(p, 0.36, 0.62);
      if (sheenP > 0 && sheenP < 1) {
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(xTopL, yTop);
        ctx.lineTo(xTopR, yTop);
        ctx.lineTo(xMidFarR, yMid);
        ctx.lineTo(gx, yBot);
        ctx.lineTo(xMidFarL, yMid);
        ctx.closePath();
        ctx.clip();
        drawClippedSheen(xMidFarL, yTop, sc * 1.04, sc * 0.86, sheenP, 0.95);
        ctx.restore();
      }

      ctx.restore();
    }

    // Flanking Geometric Ray Bars strictly in clear space Left & Right of girdle (0.11*s horizontal gap!)
    const rayIn = easeOutCubic(seg(p, 0.24, 0.38));
    const rayOut = easeInCubic(seg(p, 0.74, 0.84));
    const rayVis = rayIn * (1 - rayOut);
    if (rayVis > 0.005) {
      const rayPulse = 0.82 + 0.18 * Math.sin(seg(p, 0.26, 0.82) * Math.PI * 4);
      const barW = s * 0.11 * rayVis * rayPulse;
      const barH = s * 0.032;
      const rayY = cy - s * 0.12 + hoverY;

      ctx.save();
      ctx.globalAlpha = rayVis;
      // Left ray
      roundRectPath(cx - s * 0.63 - barW, rayY - barH * 0.5, barW, barH, barH * 0.5);
      ctx.fillStyle = COLORS.goldBright;
      ctx.fill();
      // Right ray
      roundRectPath(cx + s * 0.63, rayY - barH * 0.5, barW, barH, barH * 0.5);
      ctx.fillStyle = COLORS.goldBright;
      ctx.fill();

      // Top & diagonal sparkles far in clear air
      drawSparkle4(cx, cy - s * 0.56 + hoverY, s * 0.056 * rayVis * rayPulse, COLORS.goldPale, rayVis);
      ctx.restore();
    }

    // Seamless Treasury Pediment Roof emerging cleanly (p = 0.85 -> 1.00) -> Exact Scene 4 Start!
    const pedIn = easeOutCubic(seg(p, 0.85, 1.00));
    if (pedIn > 0.005) {
      const pedW = lerp(s * 0.40, s * 1.12, pedIn);
      const pedTop = lerp(cy - s * 0.22, cy - s * 0.50, pedIn);
      const pedBot = cy - s * 0.22;

      ctx.save();
      ctx.globalAlpha = pedIn;
      drawTreasuryPediment(cx, pedTop, pedBot, pedW, pedIn);
      ctx.restore();
    }
  }

  // Shared Crisp 2D Flat Treasury Pediment Roof (Scene 3 -> Scene 4 Exact Handoff)
  function drawTreasuryPediment(x, yTop, yBot, w, detailAlpha) {
    const hw = w * 0.5;
    // Outer Molten Amber Pediment Triangle
    ctx.beginPath();
    ctx.moveTo(x, yTop);
    ctx.lineTo(x + hw, yBot);
    ctx.lineTo(x - hw, yBot);
    ctx.closePath();
    ctx.fillStyle = COLORS.amberMain;
    ctx.fill();

    // Right-half flat shade clipped inside triangle
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(x, yTop);
    ctx.lineTo(x + hw, yBot);
    ctx.lineTo(x - hw, yBot);
    ctx.closePath();
    ctx.clip();
    ctx.fillStyle = COLORS.amberDeep;
    ctx.fillRect(x, yTop, hw + 2, yBot - yTop + 2);
    ctx.restore();

    // Recessed Inner Warm Gold Triangle + Medallion
    if (detailAlpha > 0.05) {
      const inW = w * 0.62;
      const inTop = lerp(yBot, yTop, 0.72);
      const inBot = yBot - (yBot - yTop) * 0.16;
      ctx.save();
      ctx.globalAlpha *= detailAlpha;
      ctx.beginPath();
      ctx.moveTo(x, inTop);
      ctx.lineTo(x + inW * 0.5, inBot);
      ctx.lineTo(x - inW * 0.5, inBot);
      ctx.closePath();
      ctx.fillStyle = COLORS.espressoRecess;
      ctx.fill();

      // Center Gold Medallion Dot inside tympanum
      const medR = Math.max(2, (inBot - inTop) * 0.23);
      ctx.beginPath();
      ctx.arc(x, inBot - (inBot - inTop) * 0.36, medR, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.goldBright;
      ctx.fill();
      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 4 (15s - 20s): TREASURY FACADE -> SEAMLESS LOOP TO SCENE 1 INGOT
  // =========================================================================
  function drawScene4(p) {
    // 0.00 - 0.26: Architrave, 3 classical flat columns & 2-step foundation build smoothly under Scene 3's pediment
    // 0.26 - 0.76: Architectural sheen wave + subtle column highlight pulse + crown sparkle above apex
    // 0.76 - 1.00: Upper facade retracts smoothly while foundation transforms seamlessly into EXACT Scene 1 Gold Ingot!

    const buildU = easeOutCubic(seg(p, 0.02, 0.24));
    const upperOut = easeInCubic(seg(p, 0.76, 0.88));
    const toIngotU = easeInOutCubic(seg(p, 0.84, 1.00));
    const upperVis = 1 - upperOut;

    drawStageShadow(lerp(1.08, 1.24, buildU * upperVis), 1);

    // 1. Pediment Roof (Continuous from Scene 3 p = 1.00!)
    if (upperVis > 0.005) {
      const pedShiftY = upperOut * s * 0.16;
      ctx.save();
      ctx.globalAlpha = upperVis;
      drawTreasuryPediment(cx, cy - s * 0.50 + pedShiftY, cy - s * 0.22 + pedShiftY, s * 1.12, 1);
      ctx.restore();
    }

    // 2. Architrave Beam (clear 0.022*s shadow gap below pediment!)
    const archVis = easeOutCubic(seg(p, 0.02, 0.16)) * upperVis;
    if (archVis > 0.005) {
      const aw = s * 1.06 * lerp(0.6, 1, archVis);
      const ah = s * 0.068;
      const ay = cy - s * 0.164 + upperOut * s * 0.14;
      ctx.save();
      ctx.globalAlpha = archVis;
      roundRectPath(cx - aw * 0.5, ay - ah * 0.5, aw, ah, s * 0.018);
      ctx.fillStyle = COLORS.goldBright;
      ctx.fill();
      ctx.restore();
    }

    // 3. Three Classical Flat Columns (x = cx - 0.34*s, cx, cx + 0.34*s -> 0.195*s wide gaps!)
    const colXs = [-0.34, 0, 0.34];
    const colTop = cy - s * 0.108;
    const colBot = cy + s * 0.296;
    const colFullH = colBot - colTop;
    const shaftW = s * 0.142;
    const capW = s * 0.20;
    const capH = s * 0.044;

    for (let i = 0; i < 3; i++) {
      const delay = i === 1 ? 0.04 : 0.10;
      const cIn = easeOutCubic(seg(p, delay, delay + 0.16));
      const cVis = cIn * upperVis;
      if (cVis <= 0.005) continue;

      const x = cx + colXs[i] * s;
      const curH = colFullH * cIn * (1 - upperOut * 0.5);
      const curTop = colTop + upperOut * s * 0.12;
      const colSheen = seg(p, 0.42 + i * 0.08, 0.58 + i * 0.08);

      ctx.save();
      ctx.globalAlpha = cVis;

      // Column Shaft
      const sTop = curTop + capH * 0.8;
      const sH = Math.max(2, curH - capH * 1.6);
      ctx.fillStyle = COLORS.amberMain;
      ctx.fillRect(x - shaftW * 0.5, sTop, shaftW, sH);

      // Crisp right-half flat shade + vertical flute groove
      ctx.fillStyle = COLORS.amberDeep;
      ctx.fillRect(x + shaftW * 0.08, sTop, shaftW * 0.42, sH);
      ctx.fillStyle = COLORS.goldPale;
      ctx.fillRect(x - shaftW * 0.24, sTop + sH * 0.08, shaftW * 0.12, sH * 0.84);

      if (colSheen > 0 && colSheen < 1) {
        ctx.save();
        ctx.beginPath();
        ctx.rect(x - shaftW * 0.5, sTop, shaftW, sH);
        ctx.clip();
        drawClippedSheen(x - shaftW * 0.5, sTop, shaftW, sH, colSheen, 0.9);
        ctx.restore();
      }

      // Column Top Capital
      roundRectPath(x - capW * 0.5, curTop, capW, capH, s * 0.015);
      ctx.fillStyle = COLORS.goldBright;
      ctx.fill();

      // Column Base Plinth
      roundRectPath(x - capW * 0.5, curTop + curH - capH, capW, capH, s * 0.015);
      ctx.fillStyle = COLORS.goldBright;
      ctx.fill();

      ctx.restore();
    }

    // 4. Two-Tier Stepped Foundation (smoothly fades as Scene 1 Ingot emerges cleanly from it)
    const foundVis = easeOutCubic(seg(p, 0.10, 0.24)) * (1 - easeInCubic(seg(p, 0.84, 0.93)));
    if (foundVis > 0.005) {
      ctx.save();
      ctx.globalAlpha = foundVis;
      // Upper Step
      const uW = s * 1.06 * lerp(0.7, 1, foundVis);
      const uH = s * 0.072;
      roundRectPath(cx - uW * 0.5, cy + s * 0.354 - uH * 0.5, uW, uH, s * 0.02);
      ctx.fillStyle = COLORS.amberMain;
      ctx.fill();

      // Lower Base Step
      const lW = s * 1.20 * lerp(0.7, 1, foundVis);
      const lH = s * 0.076;
      roundRectPath(cx - lW * 0.5, cy + s * 0.452 - lH * 0.5, lW, lH, s * 0.022);
      ctx.fillStyle = COLORS.bronzeMain;
      ctx.fill();
      ctx.restore();
    }

    // Crown Sparkle cleanly ABOVE pediment apex (y = cy - 0.60*s -> 0.10*s clear gap!)
    const topSpVis = easeOutCubic(seg(p, 0.30, 0.44)) * (1 - easeInCubic(seg(p, 0.72, 0.80)));
    if (topSpVis > 0.005) {
      const pulse = 0.78 + 0.22 * Math.sin(seg(p, 0.32, 0.76) * Math.PI * 4);
      drawSparkle4(cx, cy - s * 0.60, s * 0.056 * topSpVis * pulse, COLORS.goldPale, topSpVis);
    }

    // 5. Seamless Loop Return: Exact Scene 1 Gold Ingot emerging smoothly at (cx, cy + 0.08*s)!
    if (toIngotU > 0.005) {
      const curY = lerp(cy + s * 0.38, cy + s * 0.08, toIngotU);
      const curW = lerp(s * 0.96, s * 1.06, toIngotU);
      const curH = lerp(s * 0.14, s * 0.44, toIngotU);
      const alpha = clamp01(toIngotU * 1.5);
      drawGoldIngot(cx, curY, curW, curH, toIngotU > 0.55, 0, alpha);
    }
  }

  // Render Frame
  ctx.save();
  drawBackground();

  if (currentScene === 0) {
    drawScene1(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3(sceneProgress);
  } else {
    drawScene4(sceneProgress);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide * 0.42;
  const phase = (loopT / duration) * Math.PI * 2;

  const COLORS = {
    bgTop: '#060918',
    bgMid: '#0C132D',
    bgBot: '#121D42',
    cyan: '#22D3EE',
    cyanDeep: '#0891B2',
    azure: '#3B82F6',
    azureBright: '#60A5FA',
    indigoMid: '#2546A6',
    indigoDark: '#1A2D6B',
    indigoCard: '#142354',
    indigoPanel: '#0F1A40',
    periwinkle: '#818CF8',
    periwinkleDeep: '#6366F1',
    silver: '#E2E8F0',
    silverShade: '#CBD5E1',
    stageShadow: 'rgba(3, 6, 18, 0.46)',
    sheen: 'rgba(240, 248, 255, 0.18)',
    ambientMark: '#2B3E72'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function seg(p, a, b) {
    return clamp01((p - a) / (b - a));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp01(u);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fill) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function drawClippedSheen(x, y, w, h, progress, alpha) {
    if (progress <= 0 || progress >= 1) return;
    const bandW = w * 0.22;
    const travel = w + h * 0.65 + bandW * 2;
    const startX = x - h * 0.35 - bandW + progress * travel;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.beginPath();
    ctx.moveTo(startX, y - h * 0.1);
    ctx.lineTo(startX + bandW, y - h * 0.1);
    ctx.lineTo(startX + bandW - h * 0.45, y + h * 1.1);
    ctx.lineTo(startX - h * 0.45, y + h * 1.1);
    ctx.closePath();
    ctx.fillStyle = COLORS.sheen;
    ctx.fill();
    ctx.restore();
  }

  function drawStageShadow(widthFactor, alpha) {
    if (alpha <= 0.001 || widthFactor <= 0.001) return;
    const sw = s * 0.54 * widthFactor;
    const sh = s * 0.044;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.ellipse(cx, cy + s * 0.68, sw, sh, 0, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.stageShadow;
    ctx.fill();
    ctx.restore();
  }

  // Clean Modern Dark Aesthetic Linear Gradient Background (Zero Glow, Zero Edge Frames, Zero Corner Brackets)
  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, COLORS.bgTop);
    bgGrad.addColorStop(0.5, COLORS.bgMid);
    bgGrad.addColorStop(1, COLORS.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle crisp flat micro-accents strictly in outer margins far from hero icon
    const marks = [
      { nx: 0.10, ny: 0.26, type: 0, sz: 0.011, ph: 0.3, amp: 0.013, op: 0.22 },
      { nx: 0.16, ny: 0.72, type: 1, sz: 0.010, ph: 1.9, amp: 0.012, op: 0.18 },
      { nx: 0.08, ny: 0.52, type: 2, sz: 0.008, ph: 3.4, amp: 0.010, op: 0.16 },
      { nx: 0.20, ny: 0.34, type: 1, sz: 0.008, ph: 4.8, amp: 0.011, op: 0.16 },
      { nx: 0.90, ny: 0.28, type: 1, sz: 0.011, ph: 1.1, amp: 0.013, op: 0.20 },
      { nx: 0.84, ny: 0.74, type: 0, sz: 0.011, ph: 2.7, amp: 0.012, op: 0.22 },
      { nx: 0.92, ny: 0.56, type: 2, sz: 0.008, ph: 4.2, amp: 0.010, op: 0.16 },
      { nx: 0.80, ny: 0.36, type: 0, sz: 0.008, ph: 5.5, amp: 0.011, op: 0.15 }
    ];

    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      const mx = width * m.nx + Math.cos(phase + m.ph) * minSide * (m.amp * 0.45);
      const my = height * m.ny + Math.sin(phase + m.ph) * minSide * m.amp;
      const r = minSide * m.sz;
      const pulse = 0.78 + 0.22 * Math.sin(phase * 2 + m.ph);

      ctx.save();
      ctx.globalAlpha = m.op * pulse;
      ctx.fillStyle = COLORS.ambientMark;
      if (m.type === 0) {
        roundRectPath(mx - r, my - r, r * 2, r * 2, r * 0.45);
        ctx.fill();
      } else if (m.type === 1) {
        drawDiamond(mx, my, r, r, COLORS.ambientMark);
      } else {
        roundRectPath(mx - r * 1.5, my - r * 0.34, r * 3.0, r * 0.68, r * 0.34);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  // Crisp Asset Module Tile with Clean Flat Vector Mini-Glyph Inside (4 Distinct Portfolio Classes)
  function drawAssetTile(x, y, size, index, alpha) {
    if (alpha <= 0.005 || size <= 1) return;
    const fills = [COLORS.cyan, COLORS.azure, COLORS.periwinkle, COLORS.silver];
    const glyphColor = index === 3 ? COLORS.indigoDark : COLORS.indigoPanel;
    const rad = size * 0.22;
    const left = x - size * 0.5;
    const top = y - size * 0.5;

    ctx.save();
    ctx.globalAlpha = alpha;

    roundRectPath(left, top, size, size, rad);
    ctx.fillStyle = fills[index];
    ctx.fill();

    // Subtle 2D flat right-edge tone for visual richness
    ctx.save();
    roundRectPath(left, top, size, size, rad);
    ctx.clip();
    ctx.fillStyle = 'rgba(10, 18, 46, 0.11)';
    ctx.fillRect(x + size * 0.16, top, size * 0.36, size);
    ctx.restore();

    // Clean centered flat vector mini-icon inside tile (generous inner margin)
    ctx.fillStyle = glyphColor;
    if (index === 0) {
      // Ascending 2-bar equity glyph
      const bw = size * 0.16;
      const gap = size * 0.08;
      roundRectPath(x - bw - gap * 0.5, y + size * 0.02, bw, size * 0.22, bw * 0.3);
      ctx.fill();
      roundRectPath(x + gap * 0.5, y - size * 0.22, bw, size * 0.46, bw * 0.3);
      ctx.fill();
    } else if (index === 1) {
      // Precision diamond reserve glyph
      drawDiamond(x, y, size * 0.22, size * 0.26, glyphColor);
    } else if (index === 2) {
      // Structured bond/shield chevron glyph
      ctx.beginPath();
      ctx.moveTo(x, y - size * 0.24);
      ctx.lineTo(x + size * 0.22, y - size * 0.12);
      ctx.lineTo(x + size * 0.22, y + size * 0.06);
      ctx.lineTo(x, y + size * 0.24);
      ctx.lineTo(x - size * 0.22, y + size * 0.06);
      ctx.lineTo(x - size * 0.22, y - size * 0.12);
      ctx.closePath();
      ctx.fill();
    } else {
      // Balanced stable bars glyph
      const lw = size * 0.44;
      const lh = size * 0.11;
      roundRectPath(x - lw * 0.5, y - size * 0.16, lw, lh, lh * 0.5);
      ctx.fill();
      roundRectPath(x - lw * 0.5, y + size * 0.05, lw, lh, lh * 0.5);
      ctx.fill();
    }

    ctx.restore();
  }

  // Shared Sleek 2D Flat Portfolio Briefcase (Used in Scene 1 & Seamless Return from Scene 4)
  function drawPortfolioBriefcase(x, y, w, h, handleExtend, flapOpen, claspLift, sheenP, alpha) {
    if (alpha <= 0.005 || w <= 1 || h <= 1) return;
    const rad = s * 0.11;
    const left = x - w * 0.5;
    const top = y - h * 0.5;

    ctx.save();
    ctx.globalAlpha = alpha;

    // Clean Flat Arch Handle strictly ABOVE top edge (retracts smoothly when open)
    if (handleExtend > 0.01) {
      const hw = w * 0.34;
      const hh = s * 0.135 * handleExtend;
      const thick = s * 0.056;
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(x - hw * 0.5, top + s * 0.01);
      ctx.lineTo(x - hw * 0.5, top - hh + s * 0.05);
      ctx.arcTo(x - hw * 0.5, top - hh, x - hw * 0.5 + s * 0.06, top - hh, s * 0.055);
      ctx.lineTo(x + hw * 0.5 - s * 0.06, top - hh);
      ctx.arcTo(x + hw * 0.5, top - hh, x + hw * 0.5, top - hh + s * 0.05, s * 0.055);
      ctx.lineTo(x + hw * 0.5, top + s * 0.01);
      ctx.strokeStyle = COLORS.azure;
      ctx.lineWidth = thick;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.stroke();
      ctx.restore();
    }

    // Main Briefcase Body (Deep Indigo)
    roundRectPath(left, top, w, h, rad);
    ctx.fillStyle = COLORS.indigoCard;
    ctx.fill();

    // Clip interior flap, duotone & sheen strictly inside briefcase silhouette
    ctx.save();
    roundRectPath(left, top, w, h, rad);
    ctx.clip();

    // Subtle 2D flat right-half shadow on lower body
    ctx.fillStyle = COLORS.indigoPanel;
    ctx.fillRect(x, top, w * 0.52, h);

    // Upper Flap (Royal Azure) with gentle vertical slide when unlocked
    const flapH = h * lerp(0.49, 0.43, flapOpen);
    ctx.fillStyle = COLORS.indigoMid;
    ctx.fillRect(left, top, w, flapH);

    // Upper flap bright top trim strip
    ctx.fillStyle = COLORS.azure;
    ctx.fillRect(left, top, w, h * 0.08);

    // Crisp horizontal divider seam under flap
    ctx.fillStyle = COLORS.indigoDark;
    ctx.fillRect(left, top + flapH, w, s * 0.022);

    // Clipped diagonal sheen sweep
    if (sheenP > 0 && sheenP < 1) {
      drawClippedSheen(left, top, w, h, sheenP, 0.9);
    }
    ctx.restore();

    // Centered Ice Silver Clasp Buckle (slides smoothly up when unlocking)
    const claspW = s * 0.16;
    const claspH = s * 0.145;
    const claspY = top + h * lerp(0.49, 0.43, flapOpen) - claspH * 0.48 - claspLift * s * 0.025;
    roundRectPath(x - claspW * 0.5, claspY, claspW, claspH, s * 0.036);
    ctx.fillStyle = COLORS.silver;
    ctx.fill();

    // Clasp Core Indicator (switches cleanly to Luminous Cyan when unlocked)
    const coreW = claspW * 0.46;
    const coreH = claspH * 0.36;
    roundRectPath(x - coreW * 0.5, claspY + (claspH - coreH) * 0.5, coreW, coreH, coreH * 0.45);
    ctx.fillStyle = claspLift > 0.35 ? COLORS.cyan : COLORS.indigoDark;
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 1 (0s - 5s): PORTFOLIO BRIEFCASE & 4 ASSET MODULES
  // =========================================================================
  function drawScene1(p) {
    // 0.00 - 0.18: Briefcase holds centered cleanly, unlocks clasp + sheen
    // 0.18 - 0.36: Handle folds down flush, briefcase glides slightly downward to cy + 0.22*s
    // 0.26 - 0.56: 4 colored asset tiles emerge smoothly in a clean horizontal row ABOVE briefcase
    // 0.56 - 0.82: Synchronized gentle wave float on tiles + crisp indicator pips
    // 0.82 - 1.00: Briefcase exits cleanly downward; 4 tiles glide smoothly into 2x2 center matrix for Scene 2!

    const unlockU = easeInOutCubic(seg(p, 0.06, 0.22));
    const lowerU = easeInOutCubic(seg(p, 0.18, 0.34));
    const exitCaseU = easeInCubic(seg(p, 0.82, 0.93));
    const toMatrixU = easeInOutCubic(seg(p, 0.84, 1.00));

    const caseW = s * 1.04 * (1 - exitCaseU * 0.22);
    const caseH = s * 0.76 * (1 - exitCaseU * 0.22);
    const caseY = lerp(cy + s * 0.04, cy + s * 0.23, lowerU) + exitCaseU * s * 0.22;
    const handleExt = 1 - easeInOutCubic(seg(p, 0.15, 0.28));
    const caseAlpha = 1 - exitCaseU;

    drawStageShadow(lerp(1.06, 0.76, toMatrixU), 1);

    // Draw Briefcase
    if (caseAlpha > 0.005) {
      drawPortfolioBriefcase(
        cx, caseY, caseW, caseH,
        handleExt, unlockU, unlockU,
        seg(p, 0.04, 0.24), caseAlpha
      );
    }

    // 4 Asset Module Tiles (Row at y = cy - 0.36*s -> clear 0.105*s gap above lowered briefcase top cy - 0.15*s!)
    const rowXs = [-0.42, -0.14, 0.14, 0.42];
    const rowY = cy - s * 0.36;
    const tileSz = s * 0.21;

    // Target 2x2 Matrix at p = 1.00 (exact handoff into Scene 2!)
    const matOffsets = [
      { dx: -0.16, dy: -0.16 },
      { dx: 0.16, dy: -0.16 },
      { dx: 0.16, dy: 0.16 },
      { dx: -0.16, dy: 0.16 }
    ];

    for (let i = 0; i < 4; i++) {
      const tileIn = easeOutCubic(seg(p, 0.26 + i * 0.055, 0.44 + i * 0.055));
      if (tileIn <= 0.001) continue;

      const waveY = Math.sin(seg(p, 0.50, 0.84) * Math.PI * 2 - i * 0.75) * s * 0.018 * (1 - toMatrixU);
      const startX = cx + rowXs[i] * s * 0.62;
      const startY = cy - s * 0.14;
      const settledX = cx + rowXs[i] * s;
      const settledY = rowY + waveY;

      const inX = lerp(startX, settledX, tileIn);
      const inY = lerp(startY, settledY, tileIn);

      const finalX = cx + matOffsets[i].dx * s;
      const finalY = cy + matOffsets[i].dy * s;

      const tx = lerp(inX, finalX, toMatrixU);
      const ty = lerp(inY, finalY, toMatrixU);
      const curSz = lerp(tileSz * lerp(0.5, 1, tileIn), s * 0.23, toMatrixU);

      drawAssetTile(tx, ty, curSz, i, clamp01(tileIn * 1.4));

      // Subtle clean indicator dot centered beneath each tile in row phase (strictly clear of tile & briefcase)
      const dotAlpha = easeOutCubic(seg(p, 0.44 + i * 0.04, 0.54 + i * 0.04)) * (1 - easeInCubic(seg(p, 0.78, 0.86)));
      if (dotAlpha > 0.005) {
        const dotY = rowY + tileSz * 0.5 + s * 0.055;
        ctx.save();
        ctx.globalAlpha = dotAlpha * 0.85;
        ctx.beginPath();
        ctx.arc(settledX, dotY, s * 0.018, 0, Math.PI * 2);
        ctx.fillStyle = i === 0 ? COLORS.cyan : (i === 1 ? COLORS.azure : (i === 2 ? COLORS.periwinkle : COLORS.silver));
        ctx.fill();
        ctx.restore();
      }
    }
  }

  // Helper: Draw a Bold Solid Editorial Flat Wedge (NOT a thin HUD ring — thick solid flat sector!)
  function drawSolidWedge(cxW, cyW, rIn, rOut, aStart, aEnd, fill, popOffset) {
    if (aEnd <= aStart + 0.005 || rOut <= rIn + 1) return;
    const mid = (aStart + aEnd) * 0.5;
    const ox = Math.cos(mid) * popOffset;
    const oy = Math.sin(mid) * popOffset;

    ctx.save();
    ctx.translate(cxW + ox, cyW + oy);
    ctx.beginPath();
    ctx.arc(0, 0, rOut, aStart, aEnd, false);
    ctx.arc(0, 0, rIn, aEnd, aStart, true);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5s - 10s): DYNAMIC SOLID PIE ALLOCATION & LIVE REBALANCING
  // =========================================================================
  function drawScene2(p) {
    // 0.00 - 0.14: 2x2 asset matrix from Scene 1 smoothly unfolds into 4 bold solid editorial wedges
    // 0.14 - 0.82: Smooth multi-stage portfolio rebalancing across 3 balanced allocation states + gentle rotation
    // 0.82 - 1.00: Wedges & allocation pips retract cleanly while Scene 3's crisp balance beam extends horizontally!

    const fromMatrixU = easeOutCubic(seg(p, 0.0, 0.16));
    const toBeamU = easeInOutCubic(seg(p, 0.84, 1.00));
    const wedgeExitU = easeInCubic(seg(p, 0.80, 0.92));

    drawStageShadow(lerp(0.76, 1.02, fromMatrixU), 1);

    // Cross-fade smoothly out of the exact 2x2 Matrix from Scene 1 during 0.00 - 0.12
    const matFade = 1 - easeInCubic(seg(p, 0.0, 0.11));
    if (matFade > 0.005) {
      const matOffsets = [
        { dx: -0.16, dy: -0.16 },
        { dx: 0.16, dy: -0.16 },
        { dx: 0.16, dy: 0.16 },
        { dx: -0.16, dy: 0.16 }
      ];
      for (let i = 0; i < 4; i++) {
        const push = lerp(1, 1.38, 1 - matFade);
        drawAssetTile(
          cx + matOffsets[i].dx * s * push,
          cy + matOffsets[i].dy * s * push,
          s * 0.23 * matFade,
          i,
          matFade
        );
      }
    }

    // Live Rebalancing Weights (sum = 1.0 at every single frame!)
    const wA = [0.34, 0.28, 0.22, 0.16];
    const wB = [0.24, 0.34, 0.24, 0.18];
    const wC = [0.30, 0.26, 0.24, 0.20];

    const u1 = easeInOutCubic(seg(p, 0.22, 0.50));
    const u2 = easeInOutCubic(seg(p, 0.54, 0.78));

    const weights = [0, 0, 0, 0];
    for (let i = 0; i < 4; i++) {
      const midVal = lerp(wA[i], wB[i], u1);
      weights[i] = lerp(midVal, wC[i], u2);
    }

    // Bold Solid Pie Wedges (rIn = 0.21*s, rOut = 0.465*s -> thick solid radial depth, wide clear angular gaps!)
    const wedgeVis = easeOutCubic(seg(p, 0.04, 0.20)) * (1 - wedgeExitU);
    const pieCy = cy - s * 0.06;
    const rIn = s * 0.205 * lerp(0.7, 1, wedgeVis);
    const rOut = s * 0.465 * wedgeVis;
    const gapAngle = 0.075; // Guaranteed crisp clear space between all 4 wedges!
    const totalAvail = Math.PI * 2 - gapAngle * 4;
    const rotBase = -Math.PI * 0.5 + easeInOutCubic(seg(p, 0.12, 0.82)) * 0.62;
    const fills = [COLORS.cyan, COLORS.azure, COLORS.periwinkle, COLORS.silver];

    // Smooth highlight pop for leading allocation sector (shifts gently from sector 0 -> sector 1 -> sector 0)
    const pop0 = (1 - u1) * 0.85 + u2 * 0.85;
    const pop1 = u1 * (1 - u2) * 0.85;
    const pops = [pop0, pop1, 0, 0];

    if (wedgeVis > 0.005) {
      let cursor = rotBase;
      ctx.save();
      ctx.globalAlpha = wedgeVis;
      for (let i = 0; i < 4; i++) {
        const span = totalAvail * weights[i];
        const popDist = s * 0.042 * pops[i] * wedgeVis;
        drawSolidWedge(cx, pieCy, rIn, rOut, cursor, cursor + span, fills[i], popDist);
        cursor += span + gapAngle;
      }

      // Clean solid dark-indigo center hub inside the 0.205*s cutout (clear gap between hub r=0.14*s and rIn=0.205*s!)
      const hubR = s * 0.145 * wedgeVis;
      ctx.beginPath();
      ctx.arc(cx, pieCy, hubR, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.indigoCard;
      ctx.fill();

      // Clean crisp 2x2 mini-grid emblem centered inside hub
      const cell = hubR * 0.34;
      const cGap = hubR * 0.14;
      const halfSpan = cell + cGap * 0.5;
      for (let r = 0; r < 2; r++) {
        for (let c = 0; c < 2; c++) {
          const idx = r * 2 + c;
          const bx = cx - halfSpan + c * (cell + cGap);
          const by = pieCy - halfSpan + r * (cell + cGap);
          roundRectPath(bx, by, cell, cell, cell * 0.28);
          ctx.fillStyle = fills[idx];
          ctx.fill();
        }
      }
      ctx.restore();
    }

    // 4 Live Proportional Allocation Bars cleanly BELOW pie (y = cy + 0.55*s -> generous 0.11*s below pie!)
    const barRowIn = easeOutCubic(seg(p, 0.14, 0.28));
    const barRowAlpha = barRowIn * (1 - wedgeExitU);
    if (barRowAlpha > 0.005) {
      const totalBarW = s * 1.12;
      const barGap = s * 0.04;
      const usableW = totalBarW - barGap * 3;
      const barH = s * 0.054;
      const barY = cy + s * 0.55;
      let curX = cx - totalBarW * 0.5;

      ctx.save();
      ctx.globalAlpha = barRowAlpha;
      for (let i = 0; i < 4; i++) {
        const segW = usableW * weights[i] * barRowIn;
        roundRectPath(curX, barY - barH * 0.5, segW, barH, barH * 0.5);
        ctx.fillStyle = fills[i];
        ctx.fill();
        curX += segW + barGap;
      }
      ctx.restore();
    }

    // Seamless Handoff Beam extending cleanly at center (p = 0.86 -> 1.00) -> Exact Scene 3 Beam!
    if (toBeamU > 0.005) {
      const beamW = lerp(s * 0.18, s * 1.08, toBeamU);
      const beamH = s * 0.058;
      const beamY = cy + s * 0.02;
      ctx.save();
      ctx.globalAlpha = clamp01(toBeamU * 1.6);
      roundRectPath(cx - beamW * 0.5, beamY - beamH * 0.5, beamW, beamH, beamH * 0.5);
      ctx.fillStyle = COLORS.silver;
      ctx.fill();

      // Center pivot pin appearing smoothly
      const pinR = s * 0.054 * toBeamU;
      ctx.beginPath();
      ctx.arc(cx, beamY, pinR, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.silver;
      ctx.fill();
      ctx.beginPath();
      ctx.arc(cx, beamY, pinR * 0.45, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.indigoDark;
      ctx.fill();
      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 3 (10s - 15s): EQUILIBRIUM BALANCE SCALE
  // =========================================================================
  function drawScene3(p) {
    const pivotY = cy + s * 0.02;
    const baseY = cy + s * 0.46;
    const beamW = s * 1.08;
    const beamH = s * 0.058;

    // 0.00 - 0.16: Fulcrum prism, base plinth, & balanced asset trays rise smoothly around Scene 2's persistent beam
    // 0.12 - 0.72: Natural damped harmonic oscillation settling cleanly to exact 0.0 deg equilibrium
    // 0.64 - 0.84: Crisp Luminous Cyan equilibrium confirmation diamond illuminates cleanly centered above pivot
    // 0.84 - 1.00: Fulcrum & trays retract cleanly while central beam expands vertically into Scene 4 Portfolio Card!

    const scaleIn = easeOutCubic(seg(p, 0.02, 0.18));
    const scaleOut = easeInCubic(seg(p, 0.82, 0.92));
    const toCardU = easeInOutCubic(seg(p, 0.85, 1.00));
    const partsVis = scaleIn * (1 - scaleOut);

    drawStageShadow(lerp(0.96, 1.06, toCardU), 1);

    // Damped Harmonic Pendulum Angle (calm, proportional, realistic physics, settles to exact 0)
    let tilt = 0;
    if (p > 0.08 && p < 0.78) {
      const oscT = seg(p, 0.08, 0.76);
      const env = Math.pow(1 - oscT, 2.2) * Math.sin(clamp01(oscT * 6) * Math.PI * 0.5);
      tilt = Math.sin(oscT * Math.PI * 3.0) * 0.175 * env; // max ~10 degrees, zero jerk!
    }

    // 1. Base Plinth & Central Fulcrum Prism (Strictly below pivotY)
    if (partsVis > 0.005) {
      ctx.save();
      ctx.globalAlpha = partsVis;

      // Horizontal Base Plinth
      const plinthW = s * 0.72 * partsVis;
      const plinthH = s * 0.062;
      roundRectPath(cx - plinthW * 0.5, baseY - plinthH * 0.5, plinthW, plinthH, plinthH * 0.5);
      ctx.fillStyle = COLORS.azure;
      ctx.fill();

      // Duotone Flat Isosceles Fulcrum Triangle rising from plinth top to pivotY
      const triBaseY = baseY - plinthH * 0.5 - s * 0.015;
      const triTopY = lerp(triBaseY, pivotY + s * 0.02, partsVis);
      const triHalfW = s * 0.135;

      // Left half
      ctx.beginPath();
      ctx.moveTo(cx, triTopY);
      ctx.lineTo(cx, triBaseY);
      ctx.lineTo(cx - triHalfW, triBaseY);
      ctx.closePath();
      ctx.fillStyle = COLORS.indigoMid;
      ctx.fill();

      // Right half (subtle flat duotone shade)
      ctx.beginPath();
      ctx.moveTo(cx, triTopY);
      ctx.lineTo(cx + triHalfW, triBaseY);
      ctx.lineTo(cx, triBaseY);
      ctx.closePath();
      ctx.fillStyle = COLORS.indigoCard;
      ctx.fill();

      ctx.restore();
    }

    // 2. Upright Asset Trays & Stacked Portfolio Blocks ABOVE Beam Ends
    // Stem height = 0.115*s ensures >= 0.048*s clear vertical air gap between tilted beam and tray bottom!
    const armDist = s * 0.455;
    const trayW = s * 0.34;
    const trayH = s * 0.042;
    const stemH = s * 0.115;
    const blkW = s * 0.27;
    const blkH = s * 0.082;
    const blkGap = s * 0.026;

    const sides = [
      { dir: -1, colors: [COLORS.cyan, COLORS.periwinkle] },
      { dir: 1, colors: [COLORS.azure, COLORS.silver] }
    ];

    if (partsVis > 0.005) {
      for (let si = 0; si < 2; si++) {
        const side = sides[si];
        const ax = cx + Math.cos(tilt) * (side.dir * armDist);
        const ay = pivotY + Math.sin(tilt) * (side.dir * armDist);
        const trayY = ay - stemH * partsVis;

        ctx.save();
        ctx.globalAlpha = partsVis;

        // Vertical Stem connecting beam anchor cleanly to tray underside
        const stemW = s * 0.032;
        roundRectPath(ax - stemW * 0.5, trayY, stemW, stemH * partsVis, stemW * 0.5);
        ctx.fillStyle = COLORS.silverShade;
        ctx.fill();

        // Horizontal Asset Tray Platform
        roundRectPath(ax - trayW * 0.5, trayY - trayH * 0.5, trayW, trayH, trayH * 0.5);
        ctx.fillStyle = COLORS.silver;
        ctx.fill();

        // 2 Crisp Stacked Asset Blocks per side (guaranteed clear vertical gaps!)
        for (let bi = 0; bi < 2; bi++) {
          const bIn = easeOutCubic(seg(p, 0.10 + bi * 0.05 + si * 0.03, 0.24 + bi * 0.05 + si * 0.03)) * (1 - scaleOut);
          if (bIn <= 0.005) continue;

          const by = trayY - trayH * 0.5 - s * 0.024 - blkH * 0.5 - bi * (blkH + blkGap);
          const curY = lerp(by - s * 0.06, by, bIn);

          ctx.save();
          ctx.globalAlpha = bIn;
          roundRectPath(ax - blkW * 0.5, curY - blkH * 0.5, blkW, blkH, s * 0.024);
          ctx.fillStyle = side.colors[bi];
          ctx.fill();

          // Subtle right-side flat shade on block
          ctx.save();
          roundRectPath(ax - blkW * 0.5, curY - blkH * 0.5, blkW, blkH, s * 0.024);
          ctx.clip();
          ctx.fillStyle = 'rgba(10, 18, 46, 0.12)';
          ctx.fillRect(ax + blkW * 0.14, curY - blkH * 0.5, blkW * 0.38, blkH);
          ctx.restore();

          ctx.restore();
        }

        ctx.restore();
      }
    }

    // 3. Balance Beam (or seamlessly morphing into Scene 4 Card Body during p = 0.85 -> 1.00)
    if (toCardU <= 0.001) {
      ctx.save();
      ctx.translate(cx, pivotY);
      ctx.rotate(tilt);
      roundRectPath(-beamW * 0.5, -beamH * 0.5, beamW, beamH, beamH * 0.5);
      ctx.fillStyle = COLORS.silver;
      ctx.fill();
      ctx.restore();

      // Center Pivot Pin
      const pinR = s * 0.054;
      ctx.beginPath();
      ctx.arc(cx, pivotY, pinR, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.silver;
      ctx.fill();
      ctx.beginPath();
      ctx.arc(cx, pivotY, pinR * 0.45, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.indigoDark;
      ctx.fill();
    } else {
      // Smooth architectural expansion from beam into Scene 4 Card Silhouette (W = 1.04s, H = 0.76s, y = cy + 0.04s)
      const curW = lerp(beamW, s * 1.04, toCardU);
      const curH = lerp(beamH, s * 0.76, toCardU);
      const curY = lerp(pivotY, cy + s * 0.04, toCardU);
      const curR = lerp(beamH * 0.5, s * 0.11, toCardU);

      ctx.save();
      roundRectPath(cx - curW * 0.5, curY - curH * 0.5, curW, curH, curR);
      ctx.fillStyle = COLORS.indigoCard;
      ctx.fill();

      // Blend beam silver cleanly into dark indigo card surface
      const beamFade = 1 - easeOutCubic(clamp01(toCardU * 2.2));
      if (beamFade > 0.005) {
        ctx.globalAlpha = beamFade;
        ctx.fillStyle = COLORS.silver;
        ctx.fill();
      }
      ctx.restore();
    }

    // 4. Equilibrium Confirmation Diamond cleanly centered ABOVE pivot (between trays — wide clearance!)
    const eqIn = easeOutCubic(seg(p, 0.58, 0.70));
    const eqOut = easeInCubic(seg(p, 0.80, 0.88));
    const eqVis = eqIn * (1 - eqOut);
    if (eqVis > 0.005) {
      const pulse = 1 + 0.06 * Math.sin(seg(p, 0.62, 0.85) * Math.PI * 4);
      const dr = s * 0.066 * eqVis * pulse;
      ctx.save();
      ctx.globalAlpha = eqVis;
      drawDiamond(cx, cy - s * 0.30, dr, dr, COLORS.cyan);
      drawDiamond(cx, cy - s * 0.30, dr * 0.42, dr * 0.42, COLORS.silver);
      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 4 (15s - 20s): UNIFIED PORTFOLIO CARD -> SEAMLESS LOOP TO BRIEFCASE
  // =========================================================================
  function drawScene4(p) {
    const cardW = s * 1.04;
    const cardH = s * 0.76;
    const cardR = s * 0.11;
    const cardY = cy + s * 0.04;
    const left = cx - cardW * 0.5;
    const top = cardY - cardH * 0.5;

    // 0.00 - 0.12: Card interior reveals cleanly
    // 0.10 - 0.55: 4 portfolio allocation bars fill smoothly on left; verified checkmark draws cleanly on right
    // 0.55 - 0.80: Sleek diagonal sheen sweep across card + subtle synchronized bar pulse
    // 0.80 - 1.00: Interior retracts smoothly while briefcase flap, clasp & handle assemble -> EXACT Scene 1 Briefcase!

    const cardIntro = easeOutCubic(seg(p, 0.0, 0.12));
    const contentOut = easeInCubic(seg(p, 0.78, 0.88));
    const toBriefcaseU = easeInOutCubic(seg(p, 0.86, 1.00));

    drawStageShadow(1.06, 1);

    // Base Card / Transitioning Briefcase Silhouette
    if (toBriefcaseU <= 0.001) {
      roundRectPath(left, top, cardW, cardH, cardR);
      ctx.fillStyle = COLORS.indigoCard;
      ctx.fill();

      ctx.save();
      roundRectPath(left, top, cardW, cardH, cardR);
      ctx.clip();

      // Crisp 2D right-side flat shade (smooth intro fade from Scene 3)
      ctx.globalAlpha = cardIntro;
      ctx.fillStyle = COLORS.indigoPanel;
      ctx.fillRect(cx + s * 0.02, top, cardW * 0.52, cardH);

      // Subtle sleek top accent bar inside card
      ctx.fillStyle = COLORS.azure;
      ctx.fillRect(left, top, cardW, cardH * 0.08 * cardIntro);
      ctx.globalAlpha = 1;

      // Diagonal light sheen sweep
      const sheenP = seg(p, 0.56, 0.76);
      if (sheenP > 0 && sheenP < 1) {
        drawClippedSheen(left, top, cardW, cardH, sheenP, 0.88);
      }
      ctx.restore();
    } else {
      // Smoothly transition card directly into Scene 1 Briefcase (pixel-exact at p = 1.00!)
      // Draw card base first, then reveal briefcase flap/clasp/handle smoothly on top
      const flapIn = easeInOutCubic(seg(p, 0.86, 0.98));
      const handleIn = easeOutCubic(seg(p, 0.88, 1.00));

      // Draw full briefcase with animated handle & alpha crossfade for flap/clasp
      roundRectPath(left, top, cardW, cardH, cardR);
      ctx.fillStyle = COLORS.indigoCard;
      ctx.fill();

      ctx.save();
      roundRectPath(left, top, cardW, cardH, cardR);
      ctx.clip();
      ctx.fillStyle = COLORS.indigoPanel;
      ctx.fillRect(cx, top, cardW * 0.52, cardH);

      // Flap slides down cleanly from top edge to exact Scene 1 resting seam (49% height)
      const curFlapH = cardH * lerp(0.08, 0.49, flapIn);
      ctx.fillStyle = COLORS.indigoMid;
      ctx.fillRect(left, top, cardW, curFlapH);

      ctx.fillStyle = COLORS.azure;
      ctx.fillRect(left, top, cardW, cardH * 0.08);

      if (flapIn > 0.05) {
        ctx.fillStyle = COLORS.indigoDark;
        ctx.globalAlpha = flapIn;
        ctx.fillRect(left, top + curFlapH, cardW, s * 0.022);
      }
      ctx.restore();

      // Handle rises cleanly above top edge (matching Scene 1 handle at p = 1.00)
      if (handleIn > 0.01) {
        const hw = cardW * 0.34;
        const hh = s * 0.135 * handleIn;
        const thick = s * 0.056;
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(cx - hw * 0.5, top + s * 0.01);
        ctx.lineTo(cx - hw * 0.5, top - hh + s * 0.05);
        ctx.arcTo(cx - hw * 0.5, top - hh, cx - hw * 0.5 + s * 0.06, top - hh, s * 0.055);
        ctx.lineTo(cx + hw * 0.5 - s * 0.06, top - hh);
        ctx.arcTo(cx + hw * 0.5, top - hh, cx + hw * 0.5, top - hh + s * 0.05, s * 0.055);
        ctx.lineTo(cx + hw * 0.5, top + s * 0.01);
        ctx.strokeStyle = COLORS.azure;
        ctx.lineWidth = thick;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.stroke();
        ctx.restore();
      }

      // Clasp scales cleanly into exact Scene 1 resting center position
      const claspIn = easeOutCubic(seg(p, 0.90, 1.00));
      if (claspIn > 0.01) {
        const claspW = s * 0.16 * claspIn;
        const claspH = s * 0.145 * claspIn;
        const claspY = top + cardH * 0.49 - claspH * 0.48;
        ctx.save();
        ctx.globalAlpha = claspIn;
        roundRectPath(cx - claspW * 0.5, claspY, claspW, claspH, s * 0.036 * claspIn);
        ctx.fillStyle = COLORS.silver;
        ctx.fill();

        const coreW = claspW * 0.46;
        const coreH = claspH * 0.36;
        roundRectPath(cx - coreW * 0.5, claspY + (claspH - coreH) * 0.5, coreW, coreH, coreH * 0.45);
        ctx.fillStyle = COLORS.indigoDark;
        ctx.fill();
        ctx.restore();
      }
    }

    // Interior Content (Strictly aligned 2-column layout with generous 0.135*s center separation & 0.10*s margins)
    if (contentOut < 0.995 && cardIntro > 0.005) {
      const vis = cardIntro * (1 - contentOut);

      // Left Column: 4 Allocation Progress Bars (x: cx - 0.41*s to cx - 0.07*s)
      const barLeft = cx - s * 0.41;
      const maxBarW = s * 0.34;
      const barH = s * 0.076;
      const barGap = s * 0.044;
      const totalBarsH = 4 * barH + 3 * barGap;
      const barsStartY = cardY + s * 0.025 - totalBarsH * 0.5;
      const ratios = [0.95, 0.80, 0.68, 0.54];
      const fills = [COLORS.cyan, COLORS.azure, COLORS.periwinkle, COLORS.silver];

      ctx.save();
      ctx.globalAlpha = vis;
      for (let i = 0; i < 4; i++) {
        const by = barsStartY + i * (barH + barGap);
        const fillIn = easeOutCubic(seg(p, 0.08 + i * 0.06, 0.30 + i * 0.06));
        const subtlePulse = 1 + 0.03 * Math.sin(seg(p, 0.45, 0.80) * Math.PI * 2 - i * 0.6);

        // Clean dark track behind bar
        roundRectPath(barLeft, by, maxBarW, barH, barH * 0.5);
        ctx.fillStyle = COLORS.indigoPanel;
        ctx.fill();

        // Crisp colored fill bar
        const curW = Math.min(maxBarW, maxBarW * ratios[i] * fillIn * subtlePulse);
        if (curW > barH * 0.5) {
          roundRectPath(barLeft, by, curW, barH, barH * 0.5);
          ctx.fillStyle = fills[i];
          ctx.fill();
        }
      }
      ctx.restore();

      // Right Column: Precision Circular Verification Badge (center: cx + 0.23*s, cy + 0.065*s, r = 0.165*s)
      // Left edge = cx + 0.065*s -> 0.135*s clean gap from Left Column right edge (cx - 0.07*s)!
      const badgeCx = cx + s * 0.23;
      const badgeCy = cardY + s * 0.025;
      const badgeIn = easeOutCubic(seg(p, 0.18, 0.36));
      const badgeR = s * 0.165 * badgeIn * vis;

      if (badgeR > 1) {
        ctx.save();
        ctx.globalAlpha = vis;

        // Solid Luminous Cyan Disc
        ctx.beginPath();
        ctx.arc(badgeCx, badgeCy, badgeR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.cyan;
        ctx.fill();

        // Subtle inner flat shade arc on lower-right
        ctx.save();
        ctx.beginPath();
        ctx.arc(badgeCx, badgeCy, badgeR, 0, Math.PI * 2);
        ctx.clip();
        ctx.beginPath();
        ctx.arc(badgeCx - badgeR * 0.16, badgeCy - badgeR * 0.16, badgeR * 1.05, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(255, 255, 255, 0.10)';
        ctx.fill();
        ctx.restore();

        // Crisp Animated Checkmark Drawn Smoothly Inside Badge (p = 0.34 -> 0.56)
        const ckP = easeInOutCubic(seg(p, 0.34, 0.56));
        if (ckP > 0.01) {
          const p1x = badgeCx - badgeR * 0.38;
          const p1y = badgeCy + badgeR * 0.02;
          const p2x = badgeCx - badgeR * 0.10;
          const p2y = badgeCy + badgeR * 0.30;
          const p3x = badgeCx + badgeR * 0.42;
          const p3y = badgeCy - badgeR * 0.26;

          const seg1 = clamp01(ckP / 0.38);
          const seg2 = clamp01((ckP - 0.38) / 0.62);

          ctx.beginPath();
          ctx.moveTo(p1x, p1y);
          ctx.lineTo(lerp(p1x, p2x, seg1), lerp(p1y, p2y, seg1));
          if (seg2 > 0) {
            ctx.lineTo(lerp(p2x, p3x, seg2), lerp(p2y, p3y, seg2));
          }
          ctx.strokeStyle = COLORS.indigoPanel;
          ctx.lineWidth = badgeR * 0.22;
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';
          ctx.stroke();
        }

        ctx.restore();
      }
    }
  }

  // Render Frame
  ctx.save();
  drawBackground();

  if (currentScene === 0) {
    drawScene1(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3(sceneProgress);
  } else {
    drawScene4(sceneProgress);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide * 0.42;
  const phase = (loopT / duration) * Math.PI * 2;

  const COLORS = {
    bgTop: '#03120F',
    bgMid: '#071E19',
    bgBot: '#0B2A22',
    mintBright: '#34F5C5',
    mintMid: '#10B981',
    mintDeep: '#0B7A58',
    emeraldDark: '#0D4A3B',
    emeraldChassis: '#0D382E',
    emeraldChassisShade: '#0A2C24',
    emeraldRecess: '#071F19',
    goldLight: '#F7D794',
    goldMain: '#EAB854',
    goldShade: '#C89232',
    goldDeep: '#9E6E1E',
    stageShadow: 'rgba(2, 10, 8, 0.42)',
    sheen: 'rgba(255, 252, 240, 0.18)',
    ambientMark: '#1F5C4B'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function seg(p, a, b) {
    return clamp01((p - a) / (b - a));
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp01(u);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp01(u);
    return x * x * x;
  }

  function easeInOutCubic(u) {
    const x = clamp01(u);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  function easeInOutQuart(u) {
    const x = clamp01(u);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawDiamond(x, y, rx, ry, fill) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function drawPlus(x, y, arm, thick, fill) {
    const h = thick * 0.5;
    roundRectPath(x - arm, y - h, arm * 2, thick, h);
    ctx.fillStyle = fill;
    ctx.fill();
    roundRectPath(x - h, y - arm, thick, arm * 2, h);
    ctx.fill();
  }

  function drawClippedSheen(x, y, w, h, progress, alpha) {
    if (progress <= 0 || progress >= 1) return;
    const bandW = w * 0.24;
    const travel = w + h * 0.6 + bandW * 2;
    const startX = x - h * 0.3 - bandW + progress * travel;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.beginPath();
    ctx.moveTo(startX, y - h * 0.1);
    ctx.lineTo(startX + bandW, y - h * 0.1);
    ctx.lineTo(startX + bandW - h * 0.45, y + h * 1.1);
    ctx.lineTo(startX - h * 0.45, y + h * 1.1);
    ctx.closePath();
    ctx.fillStyle = COLORS.sheen;
    ctx.fill();
    ctx.restore();
  }

  function drawStageShadow(widthFactor, alpha) {
    if (alpha <= 0.001 || widthFactor <= 0.001) return;
    const sw = s * 0.54 * widthFactor;
    const sh = s * 0.045;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.ellipse(cx, cy + s * 0.68, sw, sh, 0, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.stageShadow;
    ctx.fill();
    ctx.restore();
  }

  // Clean Modern Dark Aesthetic Linear Gradient Background (Zero Glow, Zero Edge Frames)
  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, COLORS.bgTop);
    bgGrad.addColorStop(0.52, COLORS.bgMid);
    bgGrad.addColorStop(1, COLORS.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle crisp flat micro-accents strictly in outer left & right margins (far from hero icon)
    const marks = [
      { nx: 0.11, ny: 0.24, type: 0, sz: 0.011, ph: 0.0, amp: 0.014, op: 0.22 },
      { nx: 0.17, ny: 0.72, type: 1, sz: 0.012, ph: 1.4, amp: 0.012, op: 0.18 },
      { nx: 0.08, ny: 0.54, type: 0, sz: 0.008, ph: 2.6, amp: 0.010, op: 0.16 },
      { nx: 0.21, ny: 0.34, type: 2, sz: 0.009, ph: 4.1, amp: 0.011, op: 0.15 },
      { nx: 0.89, ny: 0.26, type: 1, sz: 0.012, ph: 0.9, amp: 0.013, op: 0.20 },
      { nx: 0.83, ny: 0.74, type: 0, sz: 0.011, ph: 3.1, amp: 0.014, op: 0.22 },
      { nx: 0.92, ny: 0.56, type: 2, sz: 0.009, ph: 5.0, amp: 0.010, op: 0.15 },
      { nx: 0.79, ny: 0.36, type: 0, sz: 0.008, ph: 2.1, amp: 0.011, op: 0.16 }
    ];

    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      const mx = width * m.nx + Math.cos(phase + m.ph) * minSide * (m.amp * 0.45);
      const my = height * m.ny + Math.sin(phase + m.ph) * minSide * m.amp;
      const r = minSide * m.sz;
      const pulse = 0.78 + 0.22 * Math.sin(phase * 2 + m.ph);

      ctx.save();
      ctx.globalAlpha = m.op * pulse;
      if (m.type === 0) {
        drawDiamond(mx, my, r, r, COLORS.ambientMark);
      } else if (m.type === 1) {
        drawPlus(mx, my, r, r * 0.34, COLORS.ambientMark);
      } else {
        roundRectPath(mx - r * 1.4, my - r * 0.32, r * 2.8, r * 0.64, r * 0.32);
        ctx.fillStyle = COLORS.ambientMark;
        ctx.fill();
      }
      ctx.restore();
    }
  }

  // Shared Crisp 2D Flat Vector Seed Coin (Used in Scene 1 & Seamless Bridge from Scene 4)
  function drawSeedCoin(x, y, radius, emblemRot, notchRot, sheenP, alpha) {
    if (radius <= 0.5 || alpha <= 0.001) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(x, y);

    // Outer Champagne Gold Rim
    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.goldLight;
    ctx.fill();

    // Right-half flat 2D rim shadow for crisp depth without 3D
    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, radius, -Math.PI * 0.5, Math.PI * 0.5);
    ctx.closePath();
    ctx.fillStyle = COLORS.goldMain;
    ctx.fill();
    ctx.restore();

    // Precision Outer Gear-Notch Ticks (8 evenly spaced solid flat ticks on rim)
    ctx.save();
    ctx.rotate(notchRot);
    for (let i = 0; i < 8; i++) {
      ctx.save();
      ctx.rotate((i * Math.PI) / 4);
      roundRectPath(-radius * 0.045, -radius * 0.94, radius * 0.09, radius * 0.11, radius * 0.03);
      ctx.fillStyle = COLORS.goldDeep;
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();

    // Inner Gold Ring Face
    const rMid = radius * 0.80;
    ctx.beginPath();
    ctx.arc(0, 0, rMid, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.goldMain;
    ctx.fill();

    // Recessed Dark Emerald Core
    const rCore = radius * 0.62;
    ctx.beginPath();
    ctx.arc(0, 0, rCore, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.emeraldDark;
    ctx.fill();

    // Clean Geometric Value Emblem (Symmetric Double-Diamond Core, Non-Brand)
    ctx.save();
    ctx.rotate(emblemRot);
    drawDiamond(0, 0, rCore * 0.58, rCore * 0.70, COLORS.goldLight);
    drawDiamond(0, 0, rCore * 0.28, rCore * 0.36, COLORS.mintBright);
    ctx.restore();

    // Clipped Diagonal Light Sheen
    if (sheenP > 0 && sheenP < 1) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.clip();
      drawClippedSheen(-radius, -radius, radius * 2, radius * 2, sheenP, 0.9);
      ctx.restore();
    }

    ctx.restore();
  }

  // Flat 2D Vector Coin Stack Disc (No 3D extrusion, clean duotone flat capsule)
  function drawFlatCoinDisc(x, y, w, h, sheenP, alpha) {
    if (alpha <= 0.001 || w <= 0.5 || h <= 0.5) return;
    const r = h * 0.34;
    const left = x - w * 0.5;
    const top = y - h * 0.5;

    ctx.save();
    ctx.globalAlpha = alpha;

    // Main Gold Body
    roundRectPath(left, top, w, h, r);
    ctx.fillStyle = COLORS.goldMain;
    ctx.fill();

    // Clip interior details strictly inside disc
    ctx.save();
    roundRectPath(left, top, w, h, r);
    ctx.clip();

    // Crisp right-side 2D flat shade segment
    ctx.fillStyle = COLORS.goldShade;
    ctx.fillRect(x + w * 0.16, top, w * 0.35, h);

    // Crisp top bevel highlight strip
    ctx.fillStyle = COLORS.goldLight;
    ctx.fillRect(left, top, w, h * 0.28);

    // Crisp vertical center accent notch
    const notchW = w * 0.10;
    ctx.fillStyle = COLORS.goldDeep;
    ctx.fillRect(x - notchW * 0.5, top + h * 0.32, notchW, h * 0.68);

    if (sheenP > 0 && sheenP < 1) {
      drawClippedSheen(left, top, w, h, sheenP, 0.85);
    }

    ctx.restore();
    ctx.restore();
  }

  // Shared Baseline Plinth Bar (Scene 1 -> Scene 2 -> Scene 3 Handoff Anchor)
  function drawBasePlinth(x, y, w, h, alpha, highlightAlpha) {
    if (alpha <= 0.001 || w <= 0.5) return;
    const r = h * 0.5;
    const hAlpha = highlightAlpha === undefined ? 1 : highlightAlpha;
    ctx.save();
    ctx.globalAlpha = alpha;
    roundRectPath(x - w * 0.5, y - h * 0.5, w, h, r);
    ctx.fillStyle = COLORS.emeraldChassis;
    ctx.fill();

    // Clean top highlight accent inside plinth (fades cleanly before Scene 3 chassis rise)
    if (hAlpha > 0.005) {
      ctx.save();
      roundRectPath(x - w * 0.5, y - h * 0.5, w, h, r);
      ctx.clip();
      ctx.globalAlpha *= hAlpha;
      ctx.fillStyle = COLORS.mintMid;
      ctx.fillRect(x - w * 0.5, y - h * 0.5, w, h * 0.36);
      ctx.restore();
    }
    ctx.restore();
  }

  // =========================================================================
  // SCENE 1 (0s - 5s): SEED CAPITAL
  // =========================================================================
  function drawScene1(p) {
    const baseY = cy + s * 0.50;
    const plinthH = s * 0.052;

    // Phase choreography:
    // 0.00 - 0.18: Hero centered coin rotates smoothly & shines
    // 0.18 - 0.38: Coin glides smoothly up to crest badge while baseline plinth opens
    // 0.28 - 0.60: 3 ascending coin stacks build smoothly upward with clean separation
    // 0.60 - 0.84: Continuous gentle breath + sheen wave across stacks + crest emblem turn
    // 0.84 - 1.00: Crest coin & stacks retract cleanly into shared baseline plinth for Scene 2

    const liftU = easeInOutCubic(seg(p, 0.16, 0.36));
    const exitStacksU = easeInCubic(seg(p, 0.84, 0.96));
    const exitCrestU = easeInCubic(seg(p, 0.82, 0.93));

    const plinthIn = easeOutCubic(seg(p, 0.18, 0.34));
    const plinthW = lerp(s * 0.40, s * 1.44, plinthIn);

    // Shadow width responds smoothly to composition width
    const shadowW = lerp(0.58, 1.38, plinthIn);
    drawStageShadow(shadowW, 1);

    // Draw shared baseline plinth (persists cleanly into Scene 2 at p = 1.0)
    if (plinthIn > 0.001) {
      drawBasePlinth(cx, baseY, plinthW, plinthH, plinthIn);
    }

    // 3 Ascending Coin Stacks (strictly below crest coin, wide horizontal & vertical clearance)
    const cols = [
      { dx: -s * 0.42, count: 2, startP: 0.21 },
      { dx: 0, count: 4, startP: 0.26 },
      { dx: s * 0.42, count: 6, startP: 0.31 }
    ];
    const discW = s * 0.32;
    const discH = s * 0.082;
    const discGap = s * 0.028;
    const discPitch = discH + discGap;
    const stackBottom = baseY - plinthH * 0.5 - s * 0.035;

    for (let c = 0; c < cols.length; c++) {
      const col = cols[c];
      const colX = cx + col.dx;
      const breathe = Math.sin(seg(p, 0.56, 0.84) * Math.PI * 2 - c * 0.6) * s * 0.012 * (1 - exitStacksU);
      const colSheen = seg(p, 0.58 + c * 0.06, 0.74 + c * 0.06);

      for (let i = 0; i < col.count; i++) {
        const dIn = easeOutCubic(seg(p, col.startP + i * 0.024, col.startP + 0.11 + i * 0.024));
        if (dIn <= 0.001) continue;

        const targetY = stackBottom - discH * 0.5 - i * discPitch + breathe;
        const startY = stackBottom - discH * 0.5 + s * 0.04;
        const yIn = lerp(startY, targetY, dIn);
        const curY = lerp(yIn, stackBottom - discH * 0.3, exitStacksU);
        const curScale = dIn * (1 - exitStacksU);
        const curAlpha = clamp01(dIn * 1.4) * (1 - exitStacksU);

        if (curAlpha > 0.005) {
          drawFlatCoinDisc(colX, curY, discW * lerp(0.86, 1, curScale), discH * curScale, colSheen, curAlpha);
        }
      }

      // Clean mint accent diamond strictly above Column 0 and Column 2 (clear air, no overlap)
      if (c !== 1) {
        const topDiscY = stackBottom - col.count * discPitch - s * 0.075;
        const accIn = easeOutCubic(seg(p, 0.52 + c * 0.04, 0.64 + c * 0.04));
        const accAlpha = accIn * (1 - exitStacksU);
        if (accAlpha > 0.005) {
          const floatY = Math.sin(seg(p, 0.55, 0.85) * Math.PI * 2 + c) * s * 0.014;
          ctx.save();
          ctx.globalAlpha = accAlpha;
          drawDiamond(colX, topDiscY + floatY, s * 0.038, s * 0.038, COLORS.mintBright);
          ctx.restore();
        }
      }
    }

    // Hero Seed Coin -> Glides smoothly into Top Crest Position (Center X, Y = cy - 0.44*s)
    // Crest bottom at cy - 0.44s + 0.155s = cy - 0.285s. Center column (4 discs) top at cy + 0.01s -> 0.295s clear gap!
    // Right column (6 discs) left edge at cx + 0.26s vs Crest right edge at cx + 0.155s -> 0.105s horizontal gap!
    const coinY = lerp(cy, cy - s * 0.44, liftU);
    const coinR = lerp(s * 0.30, s * 0.155, liftU) * (1 - exitCrestU);
    const notchRot = easeInOutCubic(seg(p, 0.0, 0.84)) * Math.PI * 0.5;
    const emblemRot = easeInOutCubic(seg(p, 0.44, 0.78)) * Math.PI * 0.5;
    const coinSheen = p < 0.35 ? seg(p, 0.04, 0.24) : seg(p, 0.62, 0.80);
    const coinAlpha = 1 - exitCrestU;

    drawSeedCoin(cx, coinY, coinR, emblemRot, notchRot, coinSheen, coinAlpha);
  }

  // =========================================================================
  // SCENE 2 (5s - 10s): EXPONENTIAL MOMENTUM
  // =========================================================================
  function drawScene2(p) {
    const baseY = cy + s * 0.50;
    const plinthH = s * 0.052;
    const exitToChassis = easeInOutCubic(seg(p, 0.86, 1.0));
    const plinthW = lerp(s * 1.44, s * 1.04, exitToChassis);
    const plinthHi = 1 - easeInOutCubic(seg(p, 0.88, 0.99));

    drawStageShadow(lerp(1.38, 1.04, exitToChassis), 1);
    drawBasePlinth(cx, baseY, plinthW, plinthH, 1, plinthHi);

    // 4 Exponential Flat Duotone Bars (Guaranteed clear gaps = 0.10*s between bars)
    const barXs = [-0.51, -0.17, 0.17, 0.51];
    const barHs = [0.22, 0.36, 0.56, 0.82];
    const barW = s * 0.24;
    const barBase = baseY - plinthH * 0.5 - s * 0.038;
    const exitBars = easeInCubic(seg(p, 0.82, 0.94));

    const barTops = [];
    for (let i = 0; i < 4; i++) {
      const growU = easeOutCubic(seg(p, 0.03 + i * 0.06, 0.25 + i * 0.06));
      const liveWave = Math.sin(seg(p, 0.40, 0.84) * Math.PI * 2 - i * 0.55) * s * 0.018 * (1 - exitBars);
      const curH = Math.max(0, (barHs[i] * s * growU + liveWave * growU) * (1 - exitBars));
      const bx = cx + barXs[i] * s;
      const by = barBase - curH;
      barTops.push({ x: bx, y: by });

      if (curH > 1) {
        const rad = Math.min(s * 0.04, curH * 0.45);
        ctx.save();
        roundRectPath(bx - barW * 0.5, by, barW, curH, rad);
        ctx.fillStyle = i === 3 ? COLORS.mintBright : COLORS.mintMid;
        ctx.fill();

        ctx.save();
        roundRectPath(bx - barW * 0.5, by, barW, curH, rad);
        ctx.clip();

        // Crisp 2D right-side flat duotone split
        ctx.fillStyle = i === 3 ? COLORS.mintMid : COLORS.mintDeep;
        ctx.fillRect(bx + barW * 0.12, by, barW * 0.40, curH);

        // Clean Champagne Gold top cap strip
        const capH = Math.min(s * 0.045, curH * 0.32);
        ctx.fillStyle = COLORS.goldLight;
        ctx.fillRect(bx - barW * 0.5, by, barW, capH);

        // Sequenced sheen across bars
        const sheenP = seg(p, 0.52 + i * 0.05, 0.68 + i * 0.05);
        if (sheenP > 0 && sheenP < 1) {
          drawClippedSheen(bx - barW * 0.5, by, barW, curH, sheenP, 0.85);
        }
        ctx.restore();
        ctx.restore();
      }
    }

    // Subtle crisp scale ticks strictly to the LEFT of Bar 0 (clear 0.11*s horizontal separation)
    const tickIn = easeOutCubic(seg(p, 0.14, 0.30));
    const tickAlpha = tickIn * (1 - exitBars);
    if (tickAlpha > 0.005) {
      const tickRight = cx - 0.51 * s - barW * 0.5 - s * 0.10;
      ctx.save();
      ctx.globalAlpha = tickAlpha * 0.72;
      for (let k = 0; k < 4; k++) {
        const ty = barBase - (0.18 + k * 0.21) * s;
        const tw = k === 3 ? s * 0.085 : s * 0.055;
        roundRectPath(tickRight - tw, ty - s * 0.012, tw, s * 0.024, s * 0.012);
        ctx.fillStyle = k === 3 ? COLORS.goldLight : COLORS.mintDeep;
        ctx.fill();
      }
      ctx.restore();
    }

    // Exponential Bezier Curve & Precision Arrowhead strictly ABOVE all bar tops (guaranteed wide clearance!)
    const curveClear = s * 0.215;
    const p0x = cx + barXs[0] * s;
    const p0y = barBase - barHs[0] * s - curveClear;
    const p3x = cx + barXs[3] * s;
    const p3y = barBase - barHs[3] * s - s * 0.235;
    const ctrlX = cx + s * 0.08;
    const ctrlY = barBase - s * 0.44 - curveClear;

    function evalQuad(u) {
      const inv = 1 - u;
      const x = inv * inv * p0x + 2 * inv * u * ctrlX + u * u * p3x;
      const y = inv * inv * p0y + 2 * inv * u * ctrlY + u * u * p3y;
      const dx = 2 * inv * (ctrlX - p0x) + 2 * u * (p3x - ctrlX);
      const dy = 2 * inv * (ctrlY - p0y) + 2 * u * (p3y - ctrlY);
      return { x: x, y: y, ang: Math.atan2(dy, dx) };
    }

    const drawHead = easeInOutCubic(seg(p, 0.24, 0.62));
    const eraseTail = easeInCubic(seg(p, 0.80, 0.91));
    const uStart = eraseTail;
    const uEnd = drawHead;

    if (uEnd > uStart + 0.005) {
      const steps = 40;
      const curveBreath = Math.sin(seg(p, 0.45, 0.84) * Math.PI * 2) * s * 0.012 * (1 - eraseTail);

      ctx.save();
      ctx.beginPath();
      for (let st = 0; st <= steps; st++) {
        const u = lerp(uStart, uEnd, st / steps);
        const pt = evalQuad(u);
        if (st === 0) ctx.moveTo(pt.x, pt.y + curveBreath);
        else ctx.lineTo(pt.x, pt.y + curveBreath);
      }
      ctx.strokeStyle = COLORS.goldLight;
      ctx.lineWidth = s * 0.042;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.stroke();

      // Precision Solid Arrowhead at curve tip
      const tip = evalQuad(uEnd);
      const tipAlpha = clamp01((uEnd - uStart) * 5);
      const arrowLen = s * 0.125;
      const arrowHalfW = s * 0.068;

      ctx.save();
      ctx.globalAlpha = tipAlpha;
      ctx.translate(tip.x, tip.y + curveBreath);
      ctx.rotate(tip.ang);
      ctx.beginPath();
      ctx.moveTo(arrowLen * 0.58, 0);
      ctx.lineTo(-arrowLen * 0.42, -arrowHalfW);
      ctx.lineTo(-arrowLen * 0.22, 0);
      ctx.lineTo(-arrowLen * 0.42, arrowHalfW);
      ctx.closePath();
      ctx.fillStyle = COLORS.goldLight;
      ctx.fill();
      ctx.restore();

      // Clean Node Dots along curve aligned with intermediate bars (non-overlapping with tip)
      const nodeUs = [0.0, 0.34, 0.68];
      for (let n = 0; n < nodeUs.length; n++) {
        const nu = nodeUs[n];
        if (uEnd > nu + 0.06 && uStart < nu - 0.01) {
          const npt = evalQuad(nu);
          const nScale = easeOutCubic(clamp01((uEnd - nu) * 6));
          const nr = s * 0.044 * nScale;
          ctx.beginPath();
          ctx.arc(npt.x, npt.y + curveBreath, nr, 0, Math.PI * 2);
          ctx.fillStyle = COLORS.bgMid;
          ctx.fill();
          ctx.lineWidth = s * 0.022;
          ctx.strokeStyle = COLORS.mintBright;
          ctx.stroke();
        }
      }
      ctx.restore();
    }
  }

  // Precision 2D Flat Vector Spur Gear (Mathematically accurate involute-style flat teeth)
  function drawPrecisionGear(x, y, teeth, pitchR, toothDepth, rot, fill, shadeFill, hubFill, alpha) {
    if (alpha <= 0.001 || pitchR <= 0.5) return;
    const rootR = pitchR - toothDepth * 0.52;
    const tipR = pitchR + toothDepth * 0.48;
    const step = (Math.PI * 2) / teeth;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(x, y);
    ctx.rotate(rot);

    ctx.beginPath();
    for (let i = 0; i < teeth; i++) {
      const a = i * step;
      const a1 = a - step * 0.26;
      const a2 = a - step * 0.16;
      const a3 = a + step * 0.16;
      const a4 = a + step * 0.26;

      if (i === 0) ctx.moveTo(Math.cos(a1) * rootR, Math.sin(a1) * rootR);
      else ctx.lineTo(Math.cos(a1) * rootR, Math.sin(a1) * rootR);

      ctx.lineTo(Math.cos(a2) * tipR, Math.sin(a2) * tipR);
      ctx.lineTo(Math.cos(a3) * tipR, Math.sin(a3) * tipR);
      ctx.lineTo(Math.cos(a4) * rootR, Math.sin(a4) * rootR);
    }
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();

    // Inner bevel ring
    ctx.beginPath();
    ctx.arc(0, 0, rootR * 0.72, 0, Math.PI * 2);
    ctx.fillStyle = shadeFill;
    ctx.fill();

    // Center hub cutout
    ctx.beginPath();
    ctx.arc(0, 0, rootR * 0.36, 0, Math.PI * 2);
    ctx.fillStyle = hubFill;
    ctx.fill();

    // Crisp center axle pin
    ctx.beginPath();
    ctx.arc(0, 0, rootR * 0.16, 0, Math.PI * 2);
    ctx.fillStyle = fill;
    ctx.fill();

    ctx.restore();
  }

  // Shared Rounded-Square Chassis Body (Scene 3 -> Scene 4 Exact Handoff)
  function drawChassisFrame(w, h, rad, recessInset, alpha) {
    if (alpha <= 0.001 || w <= 1 || h <= 1) return;
    const left = cx - w * 0.5;
    const top = cy - h * 0.5;

    ctx.save();
    ctx.globalAlpha = alpha;

    roundRectPath(left, top, w, h, rad);
    ctx.fillStyle = COLORS.emeraldChassis;
    ctx.fill();

    // Crisp 2D flat duotone right-half shade
    ctx.save();
    roundRectPath(left, top, w, h, rad);
    ctx.clip();
    ctx.fillStyle = COLORS.emeraldChassisShade;
    ctx.fillRect(cx, top, w * 0.52, h);
    ctx.restore();

    // Recessed inner panel (only draws once inset is meaningful so plinth handoff is pure solid)
    const rw = w - recessInset * 2;
    const rh = h - recessInset * 2;
    if (recessInset > 1 && rw > 4 && rh > 8) {
      roundRectPath(cx - rw * 0.5, cy - rh * 0.5, rw, rh, Math.max(4, rad - recessInset * 0.6));
      ctx.fillStyle = COLORS.emeraldRecess;
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10s - 15s): COMPOUNDING MULTIPLIER
  // =========================================================================
  function drawScene3(p) {
    const chassisW = s * 1.04;
    const chassisH = s * 1.04;
    const chassisR = s * 0.17;
    const recessInset = s * 0.10;

    // 0.00 - 0.16: Chassis rises seamlessly from Scene 2's baseline plinth (exact bottom match!)
    const riseU = easeOutCubic(seg(p, 0.0, 0.16));
    const curH = lerp(s * 0.052, chassisH, riseU);
    const curBottom = lerp(cy + s * 0.526, cy + s * 0.52, riseU);
    const curTop = curBottom - curH;
    const curCy = curTop + curH * 0.5;
    const recessU = easeInOutCubic(seg(p, 0.06, 0.18));

    drawStageShadow(1.04, 1);

    // Draw rising/settled chassis
    ctx.save();
    ctx.translate(0, curCy - cy);
    drawChassisFrame(chassisW, curH, lerp(s * 0.026, chassisR, riseU), recessInset * recessU, 1);
    ctx.restore();

    // Precision Meshed Gears inside recessed panel (0.14 - 0.94)
    const gearIn = easeOutCubic(seg(p, 0.14, 0.30));
    const gearOut = easeInCubic(seg(p, 0.85, 0.96));
    const gearScale = gearIn * (1 - gearOut);

    if (gearScale > 0.005) {
      const m = s * 0.033;
      const N1 = 10;
      const N2 = 8;
      const R1 = (N1 * m) * 0.5; // 0.165*s
      const R2 = (N2 * m) * 0.5; // 0.132*s
      const toothDepth = m * 1.95;

      // Exact center-to-center distance with crisp micro-clearance so teeth mesh without colliding
      const dist = R1 + R2 + m * 0.28;
      const lineAng = -Math.PI * 0.25; // Up-Right 45 degrees

      const g1x = cx - s * 0.115;
      const g1y = cy + s * 0.115;
      const g2x = g1x + Math.cos(lineAng) * dist;
      const g2y = g1y + Math.sin(lineAng) * dist;

      // Smooth continuous rotation (accelerates cleanly, cruises steadily, decelerates cleanly)
      const spin = easeInOutCubic(seg(p, 0.12, 0.92)) * Math.PI * 1.6;
      const theta1 = lineAng + spin;
      // Exact meshing phase: tooth of gear 1 centers precisely in valley of gear 2 along lineAng
      const theta2 = (lineAng + Math.PI) + (Math.PI / N2) - spin * (N1 / N2);

      drawPrecisionGear(
        g1x, g1y, N1, R1 * gearScale, toothDepth * gearScale,
        theta1, COLORS.mintBright, COLORS.mintMid, COLORS.emeraldRecess, gearScale
      );
      drawPrecisionGear(
        g2x, g2y, N2, R2 * gearScale, toothDepth * gearScale,
        theta2, COLORS.goldLight, COLORS.goldMain, COLORS.emeraldRecess, gearScale
      );

      // Clean balanced diagonal "+" multiplier mark in bottom-right interior quadrant (far from both gears)
      const badgeIn = easeOutCubic(seg(p, 0.24, 0.38)) * (1 - gearOut);
      if (badgeIn > 0.005) {
        const bx = cx + s * 0.245;
        const by = cy + s * 0.245;
        const bPulse = 1 + 0.06 * Math.sin(seg(p, 0.30, 0.85) * Math.PI * 4);
        ctx.save();
        ctx.globalAlpha = badgeIn;
        drawPlus(bx, by, s * 0.062 * badgeIn * bPulse, s * 0.024 * badgeIn, COLORS.goldLight);
        ctx.restore();
      }
    }

    // 3 Sequenced Compounding Output Pills cleanly ABOVE chassis (y = cy - 0.64*s, 0.12*s gap above top edge!)
    const pillOut = easeInCubic(seg(p, 0.83, 0.93));
    const pillY = cy - s * 0.635;
    const pillW = s * 0.24;
    const pillH = s * 0.054;
    const pillPitch = s * 0.30; // 0.06*s clear gap between pills

    for (let k = 0; k < 3; k++) {
      const px = cx + (k - 1) * pillPitch;
      const pIn = easeOutCubic(seg(p, 0.24 + k * 0.10, 0.38 + k * 0.10));
      const pAlpha = pIn * (1 - pillOut);
      if (pAlpha <= 0.005) continue;

      const activeWave = 0.5 + 0.5 * Math.sin(seg(p, 0.30, 0.86) * Math.PI * 4 - k * 1.1);
      const liftY = lerp(s * 0.04, 0, pIn) - activeWave * s * 0.012;

      ctx.save();
      ctx.globalAlpha = pAlpha;
      roundRectPath(px - pillW * 0.5, pillY + liftY - pillH * 0.5, pillW, pillH, pillH * 0.5);
      ctx.fillStyle = k === 2 ? COLORS.goldLight : (k === 1 ? COLORS.mintBright : COLORS.mintMid);
      ctx.fill();
      ctx.restore();
    }
  }

  // =========================================================================
  // SCENE 4 (15s - 20s): VAULTED RETURN -> SEAMLESS LOOP TO SCENE 1 COIN
  // =========================================================================
  function drawScene4(p) {
    const chassisW = s * 1.04;
    const chassisH = s * 1.04;
    const chassisR = s * 0.17;
    const recessInset = s * 0.10;

    // 0.00 - 0.16: Vault hinges, bolts & center wheel enter cleanly on persistent Scene 3 chassis
    // 0.16 - 0.80: Vault wheel performs 2 smooth locking rotations, bolts slide out cleanly, status turns bright mint
    // 0.80 - 1.00: Vault body, hinges & bolts retract smoothly behind central wheel -> transforms into exact Scene 1 Seed Coin!
    const detailIn = easeOutCubic(seg(p, 0.02, 0.18));
    const bodyExit = easeInOutCubic(seg(p, 0.82, 0.98));
    const bodyScale = 1 - bodyExit * 0.58;
    const bodyAlpha = 1 - easeInCubic(seg(p, 0.85, 0.98));

    drawStageShadow(lerp(1.04, 0.58, bodyExit), 1);

    // Vault Outer Chassis, Hinges, Bolts & Door Details
    if (bodyAlpha > 0.005) {
      ctx.save();
      ctx.translate(cx, cy);
      ctx.scale(bodyScale, bodyScale);
      ctx.translate(-cx, -cy);
      ctx.globalAlpha = bodyAlpha;

      // Left Exterior Hinges (flush against outer left wall, no interior overlap)
      const hingeW = s * 0.062 * detailIn;
      const hingeH = s * 0.155;
      const hingeX = cx - chassisW * 0.5 - hingeW + s * 0.01;
      for (let h = -1; h <= 1; h += 2) {
        roundRectPath(hingeX, cy + h * s * 0.24 - hingeH * 0.5, hingeW, hingeH, s * 0.024);
        ctx.fillStyle = COLORS.goldMain;
        ctx.fill();
      }

      // Right Exterior Locking Bolts (extend smoothly as vault locks)
      const boltLock = easeInOutCubic(seg(p, 0.26, 0.44)) * (1 - easeInCubic(seg(p, 0.78, 0.88)));
      const boltProtrude = s * (0.025 + 0.055 * boltLock) * detailIn;
      const boltH = s * 0.11;
      for (let b = -1; b <= 1; b += 2) {
        roundRectPath(cx + chassisW * 0.5 - s * 0.015, cy + b * s * 0.24 - boltH * 0.5, boltProtrude + s * 0.015, boltH, s * 0.024);
        ctx.fillStyle = COLORS.mintBright;
        ctx.fill();
      }

      // Main Vault Chassis Frame
      drawChassisFrame(chassisW, chassisH, chassisR, recessInset, 1);

      // Door diagonal sheen sweep clipped to inner panel
      const doorSheen = seg(p, 0.54, 0.76);
      if (doorSheen > 0 && doorSheen < 1) {
        const rw = chassisW - recessInset * 2;
        const rh = chassisH - recessInset * 2;
        ctx.save();
        roundRectPath(cx - rw * 0.5, cy - rh * 0.5, rw, rh, s * 0.11);
        ctx.clip();
        drawClippedSheen(cx - rw * 0.5, cy - rh * 0.5, rw, rh, doorSheen, 0.85);
        ctx.restore();
      }

      // Crisp Top-Right Lock Status Indicator Pill inside door (strictly clear of R=0.30s wheel!)
      const statusIn = easeOutCubic(seg(p, 0.06, 0.18));
      if (statusIn > 0.005) {
        const statusPillW = s * 0.11 * statusIn;
        const statusPillH = s * 0.042;
        const isLocked = easeInOutCubic(seg(p, 0.38, 0.52));
        ctx.save();
        ctx.globalAlpha *= statusIn;
        roundRectPath(cx + s * 0.245, cy - s * 0.355, statusPillW, statusPillH, statusPillH * 0.5);
        ctx.fillStyle = isLocked > 0.5 ? COLORS.mintBright : COLORS.goldMain;
        ctx.fill();
        ctx.restore();
      }

      ctx.restore();
    }

    // Central Precision Vault Wheel (R = 0.30*s -> matches Scene 1 Seed Coin EXACTLY!)
    const wheelIn = easeOutCubic(seg(p, 0.04, 0.18));
    const wheelR = s * 0.30 * wheelIn;
    const turn1 = easeInOutQuart(seg(p, 0.20, 0.44)) * (Math.PI * 0.5);
    const turn2 = easeInOutQuart(seg(p, 0.48, 0.72)) * (Math.PI * 0.5);
    const wheelRot = turn1 + turn2;

    // Cross-morph smoothly from vault spokes into Scene 1's Seed Coin emblem during p = 0.80 -> 0.98
    const spokeRetract = 1 - easeInOutCubic(seg(p, 0.78, 0.90));

    if (wheelR > 0.5) {
      // Base circular coin/wheel rim (wheelRot ends at PI, exact symmetry of 8 notches -> seamless continuity into Scene 1!)
      drawSeedCoin(
        cx, cy, wheelR,
        0,
        wheelRot,
        seg(p, 0.64, 0.82),
        1
      );

      // Vault 3-Spoke Locking Handle Overlay (smoothly retracts before t = 20s so only pure Seed Coin remains)
      if (spokeRetract > 0.005) {
        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate(wheelRot);
        ctx.globalAlpha = spokeRetract;

        // Clean inner vault hub overlay covering coin diamond while locked
        ctx.beginPath();
        ctx.arc(0, 0, wheelR * 0.62, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.emeraldRecess;
        ctx.fill();

        // 3 Symmetrical Rounded Spoke Bars (120 degrees apart)
        const spokeLen = wheelR * 0.56 * spokeRetract;
        const spokeThick = wheelR * 0.17;
        for (let i = 0; i < 3; i++) {
          ctx.save();
          ctx.rotate((i * Math.PI * 2) / 3 - Math.PI * 0.5);
          roundRectPath(-spokeThick * 0.5, -spokeLen, spokeThick, spokeLen, spokeThick * 0.5);
          ctx.fillStyle = COLORS.goldLight;
          ctx.fill();
          ctx.restore();
        }

        // Center Hub Cap
        ctx.beginPath();
        ctx.arc(0, 0, wheelR * 0.24, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.goldMain;
        ctx.fill();

        ctx.beginPath();
        ctx.arc(0, 0, wheelR * 0.11, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.mintBright;
        ctx.fill();

        ctx.restore();
      }
    }
  }

  // Render Frame
  ctx.save();
  drawBackground();

  if (currentScene === 0) {
    drawScene1(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3(sceneProgress);
  } else {
    drawScene4(sceneProgress);
  }

  ctx.restore();
}
